-- +goose Up
-- Advisory workflow graphs and small, normalized account portraits.
ALTER TABLE workflow_versions ADD COLUMN graph jsonb NOT NULL DEFAULT '{"nodes":[],"edges":[]}';
ALTER TABLE users ADD COLUMN avatar_png bytea, ADD COLUMN avatar_version bigint NOT NULL DEFAULT 0;
CREATE TABLE workflow_drafts (
    id uuid PRIMARY KEY,
    project_id uuid NOT NULL REFERENCES projects(id),
    user_id uuid NOT NULL REFERENCES users(id),
    input jsonb NOT NULL,
    state text NOT NULL DEFAULT 'queued' CHECK(state IN('queued','running','ready','failed')),
    result jsonb,
    error text,
    job_id uuid REFERENCES background_jobs(id),
    usage jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX workflow_drafts_owner ON workflow_drafts(user_id,created_at);

-- Recover graphs only for untouched built-in revisions. Edited text is preserved.
WITH builtins(preset_id,content_hash,graph) AS (VALUES
('software-delivery-advanced','cd89a3224c2a339d2ce39c02ceed4867','{"nodes":[{"id":"p1_work1","name":"场景与验收基线","phase":"需求与风险","kind":"activity","responsibility":"产品与项目负责人收集关键使用场景，划定本次范围和可验证的验收标准。交付：需求与验收基线。"},{"id":"p1_work2","name":"依赖与安全风险","phase":"需求与风险","kind":"activity","responsibility":"技术与安全人员识别接口、数据、外部依赖和信任边界，标明风险责任人。交付：依赖图与风险清单。"},{"id":"p1_review","name":"需求与风险评审","phase":"需求与风险","kind":"decision","responsibility":"核对目标、验收范围和风险清单并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p2_work1","name":"架构与接口契约","phase":"方案准入","kind":"activity","responsibility":"技术负责人拆解服务边界，确认接口、错误语义、迁移方案与方案取舍。交付：架构记录与接口契约。"},{"id":"p2_work2","name":"体验与交互方案","phase":"方案准入","kind":"activity","responsibility":"设计与产品人员确认关键路径、异常状态、交互原型与无障碍要求。交付：交互原型与设计说明。"},{"id":"p2_work3","name":"验证与发布策略","phase":"方案准入","kind":"activity","responsibility":"测试与运维人员制定回归范围、可观测性、灰度验证和回退检查。交付：测试与发布检查方案。"},{"id":"p2_review","name":"方案准入评审","phase":"方案准入","kind":"decision","responsibility":"核对接口契约、设计取舍与测试策略并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p3_work1","name":"前端实现与自检","phase":"并行研发","kind":"activity","responsibility":"前端人员依据确认的交互与契约实现页面、状态和测试，标注偏差。交付：前端实现与测试结果。"},{"id":"p3_work2","name":"后端实现与自检","phase":"并行研发","kind":"activity","responsibility":"后端人员实现服务、事务和接口，验证权限、失败处理与数据一致性。交付：服务实现与验证记录。"},{"id":"p3_work3","name":"环境与供应链检查","phase":"并行研发","kind":"activity","responsibility":"运维与安全人员检查依赖、构建产物、配置及环境，登记可部署版本。交付：环境与产物核对记录。"},{"id":"p3_review","name":"并行研发评审","phase":"并行研发","kind":"decision","responsibility":"核对实现、自检记录与集成准备并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p4_work1","name":"契约与端到端联调","phase":"集成与验收","kind":"activity","responsibility":"研发人员核对跨服务契约和关键用户路径，记录接口及协作缺陷。交付：联调结果与问题清单。"},{"id":"p4_work2","name":"质量与安全验证","phase":"集成与验收","kind":"activity","responsibility":"测试与安全人员执行功能、回归和相关风险验证，区分阻断问题。交付：质量报告与风险处置。"},{"id":"p4_work3","name":"业务成果审阅","phase":"集成与验收","kind":"activity","responsibility":"产品与验收负责人对照范围检查成果，确认限制、遗留事项和交付依据。交付：验收意见与遗留事项。"},{"id":"p4_review","name":"集成与验收评审","phase":"集成与验收","kind":"decision","responsibility":"核对联调、质量证据与用户验收并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p5_work1","name":"发布包与运行手册","phase":"发布与恢复准备","kind":"activity","responsibility":"核对版本、配置、迁移、监控和回退资料，明确发布与观察责任人。交付：发布包与运行手册。"},{"id":"p5_work2","name":"灰度发布与观察","phase":"发布与恢复准备","kind":"activity","responsibility":"成员在本地执行批准的发布方案，核对服务状态、核心指标与业务结果。交付：实际发布与观察记录。"},{"id":"p5_review","name":"发布与恢复准备评审","phase":"发布与恢复准备","kind":"decision","responsibility":"核对批准版本、灰度结果与恢复条件并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p6_work1","name":"运行交付与支持安排","phase":"运维交付与复盘","kind":"activity","responsibility":"运维与支持人员确认值守、告警、故障路径和资料可用性，记录接收。交付：运行接收与支持清单。"},{"id":"p6_work2","name":"迭代复盘与后续范围","phase":"运维交付与复盘","kind":"activity","responsibility":"团队核对交付收益、缺陷和协作问题，将后续改进整理为待审阅事项。交付：复盘与后续改进清单。"},{"id":"p6_review","name":"运维交付与复盘评审","phase":"运维交付与复盘","kind":"decision","responsibility":"核对运维接收、成果归档和改进计划并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"exception_action","name":"发布回退与影响隔离","phase":"异常处置与恢复","kind":"activity","responsibility":"由运维与技术负责人按已确认预案回退或隔离，核对数据和依赖状态，提交故障处置与重新发布条件。"},{"id":"exception_review","name":"恢复与重新准入","phase":"异常处置与恢复","kind":"decision","responsibility":"核对异常影响、处置证据与恢复状态，明确哪些工作需要重新评审；获得有权人确认后再进入正常推进路径。"}],"edges":[{"from":"p1_work1","to":"p1_review","kind":"sequence","label":""},{"from":"p1_work2","to":"p1_review","kind":"sequence","label":""},{"from":"p1_review","to":"p1_work1","kind":"feedback","label":"未通过：修订"},{"from":"p1_review","to":"p2_work1","kind":"sequence","label":"通过"},{"from":"p1_review","to":"p2_work2","kind":"sequence","label":"通过"},{"from":"p1_review","to":"p2_work3","kind":"sequence","label":"通过"},{"from":"p2_work1","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work2","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work3","to":"p2_review","kind":"sequence","label":""},{"from":"p2_review","to":"p2_work1","kind":"feedback","label":"未通过：修订"},{"from":"p2_review","to":"p3_work1","kind":"sequence","label":"通过"},{"from":"p2_review","to":"p3_work2","kind":"sequence","label":"通过"},{"from":"p2_review","to":"p3_work3","kind":"sequence","label":"通过"},{"from":"p3_work1","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work2","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work3","to":"p3_review","kind":"sequence","label":""},{"from":"p3_review","to":"p3_work1","kind":"feedback","label":"未通过：修订"},{"from":"p3_review","to":"p4_work1","kind":"sequence","label":"通过"},{"from":"p3_review","to":"p4_work2","kind":"sequence","label":"通过"},{"from":"p3_review","to":"p4_work3","kind":"sequence","label":"通过"},{"from":"p4_work1","to":"p4_review","kind":"sequence","label":""},{"from":"p4_work2","to":"p4_review","kind":"sequence","label":""},{"from":"p4_work3","to":"p4_review","kind":"sequence","label":""},{"from":"p4_review","to":"p4_work1","kind":"feedback","label":"未通过：修订"},{"from":"p4_review","to":"p5_work1","kind":"sequence","label":"通过"},{"from":"p5_work1","to":"p5_work2","kind":"sequence","label":""},{"from":"p5_work2","to":"p5_review","kind":"sequence","label":""},{"from":"p5_review","to":"p5_work1","kind":"feedback","label":"未通过：修订"},{"from":"p5_review","to":"p6_work1","kind":"sequence","label":"通过"},{"from":"p5_review","to":"p6_work2","kind":"sequence","label":"通过"},{"from":"p6_work1","to":"p6_review","kind":"sequence","label":""},{"from":"p6_work2","to":"p6_review","kind":"sequence","label":""},{"from":"p6_review","to":"p6_work1","kind":"feedback","label":"未通过：修订"},{"from":"p5_review","to":"exception_action","kind":"sequence","label":"异常：专项处置"},{"from":"exception_action","to":"exception_review","kind":"sequence","label":""},{"from":"exception_review","to":"p4_work1","kind":"feedback","label":"确认后重新评审"}]}'::jsonb),
('software-delivery-advanced','acf53c62a9b5b227b8b07cac9e805c34','{"nodes":[{"id":"p1_work1","name":"Scenario and acceptance baseline","phase":"Scope and risk","kind":"activity","responsibility":"Product and project leads define scenarios, scope and testable acceptance criteria. Deliver: scope and acceptance baseline."},{"id":"p1_work2","name":"Dependencies and security risks","phase":"Scope and risk","kind":"activity","responsibility":"Technical and security staff identify interfaces, data, dependencies and trust boundaries. Deliver: dependency map and risk register."},{"id":"p1_review","name":"Scope and risk review","phase":"Scope and risk","kind":"decision","responsibility":"Review goals, acceptance scope and recorded risks and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p2_work1","name":"Architecture and interface contracts","phase":"Design readiness","kind":"activity","responsibility":"Technical leads define boundaries, interfaces, error handling and migration decisions. Deliver: architecture decisions and interface contracts."},{"id":"p2_work2","name":"Experience and interaction design","phase":"Design readiness","kind":"activity","responsibility":"Design and product staff review journeys, exceptional states, prototypes and accessibility. Deliver: interaction prototype and design notes."},{"id":"p2_work3","name":"Verification and release strategy","phase":"Design readiness","kind":"activity","responsibility":"QA and operations define regression coverage, observability, rollout checks and rollback verification. Deliver: testing and release verification plan."},{"id":"p2_review","name":"Design readiness review","phase":"Design readiness","kind":"decision","responsibility":"Review interface contracts, design decisions and testing strategy and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p3_work1","name":"Frontend implementation","phase":"Parallel development","kind":"activity","responsibility":"Frontend staff implement confirmed interactions and contracts, test states and record deviations. Deliver: frontend changes and test evidence."},{"id":"p3_work2","name":"Backend implementation","phase":"Parallel development","kind":"activity","responsibility":"Backend staff implement services and transactions and check permissions, failures and consistency. Deliver: service changes and verification evidence."},{"id":"p3_work3","name":"Environment and supply-chain checks","phase":"Parallel development","kind":"activity","responsibility":"Operations and security check dependencies, artifacts, configuration and the deployable version. Deliver: environment and artifact checks."},{"id":"p3_review","name":"Parallel development review","phase":"Parallel development","kind":"decision","responsibility":"Review implementation, self-check evidence and integration readiness and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p4_work1","name":"Contract and end-to-end integration","phase":"Integration and acceptance","kind":"activity","responsibility":"Developers verify cross-service contracts and user journeys and record integration defects. Deliver: integration evidence and issue list."},{"id":"p4_work2","name":"Quality and security verification","phase":"Integration and acceptance","kind":"activity","responsibility":"QA and security perform functional, regression and risk checks and identify blocking issues. Deliver: quality report and risk disposition."},{"id":"p4_work3","name":"Business result review","phase":"Integration and acceptance","kind":"activity","responsibility":"Product and acceptance owners compare results with scope and identify limitations and remaining work. Deliver: acceptance findings and remaining items."},{"id":"p4_review","name":"Integration and acceptance review","phase":"Integration and acceptance","kind":"decision","responsibility":"Review integration, quality evidence and user acceptance and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p5_work1","name":"Release package and runbook","phase":"Release readiness","kind":"activity","responsibility":"Verify versions, configuration, migrations, monitoring and rollback materials and assign release observers. Deliver: release package and runbook."},{"id":"p5_work2","name":"Staged release and observation","phase":"Release readiness","kind":"activity","responsibility":"Members execute the approved rollout locally and verify health, key metrics and business results. Deliver: actual rollout and observation evidence."},{"id":"p5_review","name":"Release readiness review","phase":"Release readiness","kind":"decision","responsibility":"Review approved artifacts, rollout evidence and recovery criteria and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p6_work1","name":"Operations handoff","phase":"Operations and retrospective","kind":"activity","responsibility":"Operations and support confirm ownership, alerts, incident paths and usable handoff materials. Deliver: operations receipt and support checklist."},{"id":"p6_work2","name":"Iteration retrospective","phase":"Operations and retrospective","kind":"activity","responsibility":"The team reviews outcomes, defects and collaboration and records proposed future improvements. Deliver: retrospective and improvement backlog."},{"id":"p6_review","name":"Operations and retrospective review","phase":"Operations and retrospective","kind":"decision","responsibility":"Review operations receipt, archived results and improvements and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"exception_action","name":"Release rollback and containment","phase":"Exceptions and recovery","kind":"activity","responsibility":"Operators and technical leads execute an approved response, verify data and dependencies, and document recovery and release criteria."},{"id":"exception_review","name":"Recovery and readiness review","phase":"Exceptions and recovery","kind":"decision","responsibility":"Check impact, response evidence and recovery status. Identify reviews to repeat and obtain authorized confirmation before resuming."}],"edges":[{"from":"p1_work1","to":"p1_review","kind":"sequence","label":""},{"from":"p1_work2","to":"p1_review","kind":"sequence","label":""},{"from":"p1_review","to":"p1_work1","kind":"feedback","label":"Needs revision"},{"from":"p1_review","to":"p2_work1","kind":"sequence","label":"Accepted"},{"from":"p1_review","to":"p2_work2","kind":"sequence","label":"Accepted"},{"from":"p1_review","to":"p2_work3","kind":"sequence","label":"Accepted"},{"from":"p2_work1","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work2","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work3","to":"p2_review","kind":"sequence","label":""},{"from":"p2_review","to":"p2_work1","kind":"feedback","label":"Needs revision"},{"from":"p2_review","to":"p3_work1","kind":"sequence","label":"Accepted"},{"from":"p2_review","to":"p3_work2","kind":"sequence","label":"Accepted"},{"from":"p2_review","to":"p3_work3","kind":"sequence","label":"Accepted"},{"from":"p3_work1","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work2","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work3","to":"p3_review","kind":"sequence","label":""},{"from":"p3_review","to":"p3_work1","kind":"feedback","label":"Needs revision"},{"from":"p3_review","to":"p4_work1","kind":"sequence","label":"Accepted"},{"from":"p3_review","to":"p4_work2","kind":"sequence","label":"Accepted"},{"from":"p3_review","to":"p4_work3","kind":"sequence","label":"Accepted"},{"from":"p4_work1","to":"p4_review","kind":"sequence","label":""},{"from":"p4_work2","to":"p4_review","kind":"sequence","label":""},{"from":"p4_work3","to":"p4_review","kind":"sequence","label":""},{"from":"p4_review","to":"p4_work1","kind":"feedback","label":"Needs revision"},{"from":"p4_review","to":"p5_work1","kind":"sequence","label":"Accepted"},{"from":"p5_work1","to":"p5_work2","kind":"sequence","label":""},{"from":"p5_work2","to":"p5_review","kind":"sequence","label":""},{"from":"p5_review","to":"p5_work1","kind":"feedback","label":"Needs revision"},{"from":"p5_review","to":"p6_work1","kind":"sequence","label":"Accepted"},{"from":"p5_review","to":"p6_work2","kind":"sequence","label":"Accepted"},{"from":"p6_work1","to":"p6_review","kind":"sequence","label":""},{"from":"p6_work2","to":"p6_review","kind":"sequence","label":""},{"from":"p6_review","to":"p6_work1","kind":"feedback","label":"Needs revision"},{"from":"p5_review","to":"exception_action","kind":"sequence","label":"Exception response"},{"from":"exception_action","to":"exception_review","kind":"sequence","label":""},{"from":"exception_review","to":"p4_work1","kind":"feedback","label":"Confirmed re-review"}]}'::jsonb),
('software-incident-advanced','e30e0d6014803445d968f5040ea9441a','{"nodes":[{"id":"p1_work1","name":"复现与证据收集","phase":"问题确认","kind":"activity","responsibility":"收集输入、版本、日志与复现步骤，明确期望和实际表现。交付：可复现问题记录。"},{"id":"p1_work2","name":"影响与紧急程度","phase":"问题确认","kind":"activity","responsibility":"产品、支持和技术人员核对受影响场景、用户与依赖，提出优先级。交付：影响范围与优先级建议。"},{"id":"p1_review","name":"问题确认评审","phase":"问题确认","kind":"decision","responsibility":"核对复现依据与影响边界并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p2_work1","name":"根因与变更定位","phase":"诊断与缓解","kind":"activity","responsibility":"结合运行证据和最近变更验证根因假设，记录尚未排除的解释。交付：根因分析与变更定位。"},{"id":"p2_work2","name":"临时缓解与监控","phase":"诊断与缓解","kind":"activity","responsibility":"评估隔离、降级与用户支持措施，执行经确认的缓解并观察结果。交付：缓解记录与观察结果。"},{"id":"p2_review","name":"诊断与缓解评审","phase":"诊断与缓解","kind":"decision","responsibility":"核对根因假设与临时措施并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p3_work1","name":"修复与数据处理方案","phase":"修复方案","kind":"activity","responsibility":"确认代码、配置和受影响数据的处理方式，说明风险与回退条件。交付：修复方案与风险说明。"},{"id":"p3_work2","name":"回归与防复发方案","phase":"修复方案","kind":"activity","responsibility":"围绕复现、相邻功能和根因设计验证与长期改进，避免只验证表象。交付：回归与防复发清单。"},{"id":"p3_review","name":"修复方案评审","phase":"修复方案","kind":"decision","responsibility":"核对修复取舍与回归边界并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p4_work1","name":"实施修复与自检","phase":"修复与验证","kind":"activity","responsibility":"责任成员完成修复和必要测试，登记变更内容与可回退版本。交付：修复变更与自检记录。"},{"id":"p4_work2","name":"跨团队回归","phase":"修复与验证","kind":"activity","responsibility":"测试与相关团队验证原问题、依赖接口和关键业务，核对附加影响。交付：回归报告与影响核对。"},{"id":"p4_review","name":"修复与验证评审","phase":"修复与验证","kind":"decision","responsibility":"核对实现证据与回归结果并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p5_work1","name":"部署修复与恢复观察","phase":"恢复与确认","kind":"activity","responsibility":"按确认方案部署或应用修复，跟踪运行指标和用户场景的恢复结果。交付：实际恢复证据。"},{"id":"p5_work2","name":"业务与支持确认","phase":"恢复与确认","kind":"activity","responsibility":"业务和支持人员核对受影响用户的反馈、补偿或沟通事项并确认状态。交付：业务恢复与支持记录。"},{"id":"p5_review","name":"恢复与确认评审","phase":"恢复与确认","kind":"decision","responsibility":"核对实际恢复结果与业务确认并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p6_work1","name":"问题关闭资料","phase":"关闭与预防","kind":"activity","responsibility":"归档复现、根因、变更与验证，明确遗留风险和关闭依据。交付：完整问题记录。"},{"id":"p6_work2","name":"预防改进与复盘","phase":"关闭与预防","kind":"activity","responsibility":"梳理监控、测试与工作流程的改进，形成需要确认的后续安排。交付：预防与复盘清单。"},{"id":"p6_review","name":"关闭与预防评审","phase":"关闭与预防","kind":"decision","responsibility":"核对关闭依据和预防措施并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"exception_action","name":"修复失败与回退处置","phase":"异常处置与恢复","kind":"activity","responsibility":"确认修复造成的附加影响，由责任人回退或隔离；保留原问题与新问题证据。"},{"id":"exception_review","name":"恢复与重新准入","phase":"异常处置与恢复","kind":"decision","responsibility":"核对异常影响、处置证据与恢复状态，明确哪些工作需要重新评审；获得有权人确认后再进入正常推进路径。"}],"edges":[{"from":"p1_work1","to":"p1_review","kind":"sequence","label":""},{"from":"p1_work2","to":"p1_review","kind":"sequence","label":""},{"from":"p1_review","to":"p1_work1","kind":"feedback","label":"未通过：修订"},{"from":"p1_review","to":"p2_work1","kind":"sequence","label":"通过"},{"from":"p1_review","to":"p2_work2","kind":"sequence","label":"通过"},{"from":"p2_work1","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work2","to":"p2_review","kind":"sequence","label":""},{"from":"p2_review","to":"p2_work1","kind":"feedback","label":"未通过：修订"},{"from":"p2_review","to":"p3_work1","kind":"sequence","label":"通过"},{"from":"p2_review","to":"p3_work2","kind":"sequence","label":"通过"},{"from":"p3_work1","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work2","to":"p3_review","kind":"sequence","label":""},{"from":"p3_review","to":"p3_work1","kind":"feedback","label":"未通过：修订"},{"from":"p3_review","to":"p4_work1","kind":"sequence","label":"通过"},{"from":"p4_work1","to":"p4_work2","kind":"sequence","label":""},{"from":"p4_work2","to":"p4_review","kind":"sequence","label":""},{"from":"p4_review","to":"p4_work1","kind":"feedback","label":"未通过：修订"},{"from":"p4_review","to":"p5_work1","kind":"sequence","label":"通过"},{"from":"p5_work1","to":"p5_work2","kind":"sequence","label":""},{"from":"p5_work2","to":"p5_review","kind":"sequence","label":""},{"from":"p5_review","to":"p5_work1","kind":"feedback","label":"未通过：修订"},{"from":"p5_review","to":"p6_work1","kind":"sequence","label":"通过"},{"from":"p5_review","to":"p6_work2","kind":"sequence","label":"通过"},{"from":"p6_work1","to":"p6_review","kind":"sequence","label":""},{"from":"p6_work2","to":"p6_review","kind":"sequence","label":""},{"from":"p6_review","to":"p6_work1","kind":"feedback","label":"未通过：修订"},{"from":"p4_review","to":"exception_action","kind":"sequence","label":"异常：专项处置"},{"from":"exception_action","to":"exception_review","kind":"sequence","label":""},{"from":"exception_review","to":"p2_work1","kind":"feedback","label":"确认后重新评审"}]}'::jsonb),
('software-incident-advanced','d2bbdfe24a10984e15c790695229fde2','{"nodes":[{"id":"p1_work1","name":"Reproduction and evidence","phase":"Issue confirmation","kind":"activity","responsibility":"Collect inputs, versions, logs and reproduction steps and compare expected and actual results. Deliver: reproducible issue record."},{"id":"p1_work2","name":"Impact and urgency","phase":"Issue confirmation","kind":"activity","responsibility":"Product, support and technical staff assess affected scenarios, users and dependencies. Deliver: impact assessment and priority proposal."},{"id":"p1_review","name":"Issue confirmation review","phase":"Issue confirmation","kind":"decision","responsibility":"Review reproduction evidence and impact boundaries and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p2_work1","name":"Root cause and change tracing","phase":"Diagnosis and mitigation","kind":"activity","responsibility":"Validate hypotheses against operational evidence and recent changes and record unresolved explanations. Deliver: root-cause analysis and change trace."},{"id":"p2_work2","name":"Mitigation and monitoring","phase":"Diagnosis and mitigation","kind":"activity","responsibility":"Assess containment, degradation and support options, then apply approved mitigation and observe results. Deliver: mitigation record and observation evidence."},{"id":"p2_review","name":"Diagnosis and mitigation review","phase":"Diagnosis and mitigation","kind":"decision","responsibility":"Review root-cause hypotheses and mitigation measures and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p3_work1","name":"Repair and data treatment","phase":"Repair design","kind":"activity","responsibility":"Define code, configuration and data treatment and document risks and rollback conditions. Deliver: repair proposal and risk assessment."},{"id":"p3_work2","name":"Regression and prevention","phase":"Repair design","kind":"activity","responsibility":"Design checks around reproduction, adjacent functions and root cause, plus prevention work. Deliver: regression and prevention plan."},{"id":"p3_review","name":"Repair design review","phase":"Repair design","kind":"decision","responsibility":"Review repair tradeoffs and regression boundaries and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p4_work1","name":"Implement repair and self-check","phase":"Repair and verification","kind":"activity","responsibility":"Owners implement the repair and tests and record changes and recoverable versions. Deliver: repair changes and self-check evidence."},{"id":"p4_work2","name":"Cross-team regression","phase":"Repair and verification","kind":"activity","responsibility":"QA and related teams verify the issue, interfaces and core business paths for side effects. Deliver: regression report and impact checks."},{"id":"p4_review","name":"Repair and verification review","phase":"Repair and verification","kind":"decision","responsibility":"Review repair evidence and regression results and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p5_work1","name":"Deploy repair and observe recovery","phase":"Recovery confirmation","kind":"activity","responsibility":"Apply the approved repair and track operational metrics and recovered user scenarios. Deliver: actual recovery evidence."},{"id":"p5_work2","name":"Business and support confirmation","phase":"Recovery confirmation","kind":"activity","responsibility":"Business and support staff check affected-user feedback and required follow-up communication. Deliver: business recovery and support record."},{"id":"p5_review","name":"Recovery confirmation review","phase":"Recovery confirmation","kind":"decision","responsibility":"Review actual recovery and business confirmation and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p6_work1","name":"Issue closure evidence","phase":"Closure and prevention","kind":"activity","responsibility":"Archive reproduction, cause, changes and checks with residual risks and closure evidence. Deliver: complete issue record."},{"id":"p6_work2","name":"Prevention and retrospective","phase":"Closure and prevention","kind":"activity","responsibility":"Review monitoring, testing and process improvements and propose follow-up work. Deliver: prevention and retrospective checklist."},{"id":"p6_review","name":"Closure and prevention review","phase":"Closure and prevention","kind":"decision","responsibility":"Review closure evidence and prevention measures and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"exception_action","name":"Failed repair and rollback","phase":"Exceptions and recovery","kind":"activity","responsibility":"Confirm additional impact, execute an approved rollback or containment, and preserve evidence of both issues."},{"id":"exception_review","name":"Recovery and readiness review","phase":"Exceptions and recovery","kind":"decision","responsibility":"Check impact, response evidence and recovery status. Identify reviews to repeat and obtain authorized confirmation before resuming."}],"edges":[{"from":"p1_work1","to":"p1_review","kind":"sequence","label":""},{"from":"p1_work2","to":"p1_review","kind":"sequence","label":""},{"from":"p1_review","to":"p1_work1","kind":"feedback","label":"Needs revision"},{"from":"p1_review","to":"p2_work1","kind":"sequence","label":"Accepted"},{"from":"p1_review","to":"p2_work2","kind":"sequence","label":"Accepted"},{"from":"p2_work1","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work2","to":"p2_review","kind":"sequence","label":""},{"from":"p2_review","to":"p2_work1","kind":"feedback","label":"Needs revision"},{"from":"p2_review","to":"p3_work1","kind":"sequence","label":"Accepted"},{"from":"p2_review","to":"p3_work2","kind":"sequence","label":"Accepted"},{"from":"p3_work1","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work2","to":"p3_review","kind":"sequence","label":""},{"from":"p3_review","to":"p3_work1","kind":"feedback","label":"Needs revision"},{"from":"p3_review","to":"p4_work1","kind":"sequence","label":"Accepted"},{"from":"p4_work1","to":"p4_work2","kind":"sequence","label":""},{"from":"p4_work2","to":"p4_review","kind":"sequence","label":""},{"from":"p4_review","to":"p4_work1","kind":"feedback","label":"Needs revision"},{"from":"p4_review","to":"p5_work1","kind":"sequence","label":"Accepted"},{"from":"p5_work1","to":"p5_work2","kind":"sequence","label":""},{"from":"p5_work2","to":"p5_review","kind":"sequence","label":""},{"from":"p5_review","to":"p5_work1","kind":"feedback","label":"Needs revision"},{"from":"p5_review","to":"p6_work1","kind":"sequence","label":"Accepted"},{"from":"p5_review","to":"p6_work2","kind":"sequence","label":"Accepted"},{"from":"p6_work1","to":"p6_review","kind":"sequence","label":""},{"from":"p6_work2","to":"p6_review","kind":"sequence","label":""},{"from":"p6_review","to":"p6_work1","kind":"feedback","label":"Needs revision"},{"from":"p4_review","to":"exception_action","kind":"sequence","label":"Exception response"},{"from":"exception_action","to":"exception_review","kind":"sequence","label":""},{"from":"exception_review","to":"p2_work1","kind":"feedback","label":"Confirmed re-review"}]}'::jsonb),
('software-release-advanced','7613e461cab082776fb404f6fb3f930f','{"nodes":[{"id":"p1_work1","name":"发布内容与版本核对","phase":"变更范围","kind":"activity","responsibility":"汇集待发布变更、成果验收与版本，核对关联任务和未解决问题。交付：发布范围与版本清单。"},{"id":"p1_work2","name":"依赖与业务影响","phase":"变更范围","kind":"activity","responsibility":"识别下游接口、数据、用户场景和发布窗口，提出通知与协调事项。交付：影响与协调清单。"},{"id":"p1_review","name":"变更范围评审","phase":"变更范围","kind":"decision","responsibility":"核对变更与受影响依赖并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p2_work1","name":"回归与安全检查","phase":"质量与环境","kind":"activity","responsibility":"测试和安全人员核对阻断问题、风险处置和已确认的验收证据。交付：质量准入证据。"},{"id":"p2_work2","name":"配置与资源核对","phase":"质量与环境","kind":"activity","responsibility":"运维人员比较环境配置、凭据引用、资源和外部服务可用性。交付：环境差异与资源检查。"},{"id":"p2_review","name":"质量与环境评审","phase":"质量与环境","kind":"decision","responsibility":"核对质量结果与环境差异并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p3_work1","name":"迁移与恢复演练","phase":"演练与预案","kind":"activity","responsibility":"在隔离环境演练升级、数据处理及恢复步骤，记录时间和限制。交付：迁移与恢复演练记录。"},{"id":"p3_work2","name":"运行手册与责任安排","phase":"演练与预案","kind":"activity","responsibility":"明确变更顺序、验证点、决策责任人、回退条件和观察期限。交付：可审阅发布运行手册。"},{"id":"p3_review","name":"演练与预案评审","phase":"演练与预案","kind":"decision","responsibility":"核对演练结果、迁移与回退并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p4_work1","name":"发布依据整合","phase":"发布准入","kind":"activity","responsibility":"整合版本、测试、演练与风险依据，列出发布所依赖的确认事项。交付：发布审阅包。"},{"id":"p4_work2","name":"发布窗口与人员确认","phase":"发布准入","kind":"activity","responsibility":"确认发布、验证、业务支持和应急人员能在窗口内承担职责。交付：人员与窗口确认记录。"},{"id":"p4_review","name":"发布准入评审","phase":"发布准入","kind":"decision","responsibility":"核对人审结论与可用发布包并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p5_work1","name":"执行灰度发布","phase":"灰度与运行验证","kind":"activity","responsibility":"成员在本地按运行手册逐步发布，记录实际步骤与偏差。交付：实际发布记录。"},{"id":"p5_work2","name":"运行与业务核验","phase":"灰度与运行验证","kind":"activity","responsibility":"核对服务、数据和关键用户路径，判断是否满足扩大发布或恢复的依据。交付：运行与业务核验结果。"},{"id":"p5_review","name":"灰度与运行验证评审","phase":"灰度与运行验证","kind":"decision","responsibility":"核对灰度、业务与运行指标并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p6_work1","name":"运维接收与支持","phase":"接收与复盘","kind":"activity","responsibility":"交付运行资料、监控和故障路径，记录实际接收与后续观察。交付：运维接收记录。"},{"id":"p6_work2","name":"变更归档与复盘","phase":"接收与复盘","kind":"activity","responsibility":"对照预期检查结果、偏差和恢复措施，形成改进建议。交付：发布复盘与改进。"},{"id":"p6_review","name":"接收与复盘评审","phase":"接收与复盘","kind":"decision","responsibility":"核对运维接收与变更归档并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"exception_action","name":"回退与数据一致性处置","phase":"异常处置与恢复","kind":"activity","responsibility":"在确认的回退边界内恢复服务，核对数据、接口和配置状态，提交重新发布所需的证据。"},{"id":"exception_review","name":"恢复与重新准入","phase":"异常处置与恢复","kind":"decision","responsibility":"核对异常影响、处置证据与恢复状态，明确哪些工作需要重新评审；获得有权人确认后再进入正常推进路径。"}],"edges":[{"from":"p1_work1","to":"p1_review","kind":"sequence","label":""},{"from":"p1_work2","to":"p1_review","kind":"sequence","label":""},{"from":"p1_review","to":"p1_work1","kind":"feedback","label":"未通过：修订"},{"from":"p1_review","to":"p2_work1","kind":"sequence","label":"通过"},{"from":"p1_review","to":"p2_work2","kind":"sequence","label":"通过"},{"from":"p2_work1","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work2","to":"p2_review","kind":"sequence","label":""},{"from":"p2_review","to":"p2_work1","kind":"feedback","label":"未通过：修订"},{"from":"p2_review","to":"p3_work1","kind":"sequence","label":"通过"},{"from":"p2_review","to":"p3_work2","kind":"sequence","label":"通过"},{"from":"p3_work1","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work2","to":"p3_review","kind":"sequence","label":""},{"from":"p3_review","to":"p3_work1","kind":"feedback","label":"未通过：修订"},{"from":"p3_review","to":"p4_work1","kind":"sequence","label":"通过"},{"from":"p4_work1","to":"p4_work2","kind":"sequence","label":""},{"from":"p4_work2","to":"p4_review","kind":"sequence","label":""},{"from":"p4_review","to":"p4_work1","kind":"feedback","label":"未通过：修订"},{"from":"p4_review","to":"p5_work1","kind":"sequence","label":"通过"},{"from":"p5_work1","to":"p5_work2","kind":"sequence","label":""},{"from":"p5_work2","to":"p5_review","kind":"sequence","label":""},{"from":"p5_review","to":"p5_work1","kind":"feedback","label":"未通过：修订"},{"from":"p5_review","to":"p6_work1","kind":"sequence","label":"通过"},{"from":"p5_review","to":"p6_work2","kind":"sequence","label":"通过"},{"from":"p6_work1","to":"p6_review","kind":"sequence","label":""},{"from":"p6_work2","to":"p6_review","kind":"sequence","label":""},{"from":"p6_review","to":"p6_work1","kind":"feedback","label":"未通过：修订"},{"from":"p5_review","to":"exception_action","kind":"sequence","label":"异常：专项处置"},{"from":"exception_action","to":"exception_review","kind":"sequence","label":""},{"from":"exception_review","to":"p3_work1","kind":"feedback","label":"确认后重新评审"}]}'::jsonb),
('software-release-advanced','5fac9dc23bbb72749745a1a85145d2fd','{"nodes":[{"id":"p1_work1","name":"Release content and version checks","phase":"Change scope","kind":"activity","responsibility":"Gather release changes, acceptance evidence and versions and check related work and unresolved issues. Deliver: release scope and version list."},{"id":"p1_work2","name":"Dependency and business impact","phase":"Change scope","kind":"activity","responsibility":"Identify downstream interfaces, data, user scenarios and release windows for coordination. Deliver: impact and coordination checklist."},{"id":"p1_review","name":"Change scope review","phase":"Change scope","kind":"decision","responsibility":"Review changes and affected dependencies and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p2_work1","name":"Regression and security checks","phase":"Quality and environment","kind":"activity","responsibility":"QA and security review blocking issues, risk disposition and accepted evidence. Deliver: quality readiness evidence."},{"id":"p2_work2","name":"Configuration and resource checks","phase":"Quality and environment","kind":"activity","responsibility":"Operations compare environment settings, credential references, resources and external services. Deliver: environment differences and resource checks."},{"id":"p2_review","name":"Quality and environment review","phase":"Quality and environment","kind":"decision","responsibility":"Review quality results and environment differences and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p3_work1","name":"Migration and recovery rehearsal","phase":"Rehearsal and response plans","kind":"activity","responsibility":"Rehearse upgrades, data treatment and recovery in isolation and record timing and limits. Deliver: migration and recovery rehearsal."},{"id":"p3_work2","name":"Runbook and responsibilities","phase":"Rehearsal and response plans","kind":"activity","responsibility":"Define change order, checks, decision owners, rollback criteria and observation periods. Deliver: reviewable release runbook."},{"id":"p3_review","name":"Rehearsal and response plans review","phase":"Rehearsal and response plans","kind":"decision","responsibility":"Review rehearsal, migration and rollback evidence and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p4_work1","name":"Consolidate release evidence","phase":"Release authorization","kind":"activity","responsibility":"Combine version, testing, rehearsal and risk evidence and list required confirmations. Deliver: release review package."},{"id":"p4_work2","name":"Confirm window and responders","phase":"Release authorization","kind":"activity","responsibility":"Confirm release, verification, business support and response ownership during the window. Deliver: ownership and window confirmation."},{"id":"p4_review","name":"Release authorization review","phase":"Release authorization","kind":"decision","responsibility":"Review human decisions and deployable artifacts and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p5_work1","name":"Execute staged rollout","phase":"Rollout and operational checks","kind":"activity","responsibility":"Members execute staged rollout locally using the runbook and record steps and deviations. Deliver: actual release record."},{"id":"p5_work2","name":"Verify operations and business","phase":"Rollout and operational checks","kind":"activity","responsibility":"Verify services, data and critical journeys and assess evidence for wider rollout or recovery. Deliver: operational and business verification."},{"id":"p5_review","name":"Rollout and operational checks review","phase":"Rollout and operational checks","kind":"decision","responsibility":"Review staged rollout, business and operational results and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p6_work1","name":"Operations receipt and support","phase":"Receipt and retrospective","kind":"activity","responsibility":"Hand over operational materials, monitoring and incident paths and record receipt and observation. Deliver: operations receipt."},{"id":"p6_work2","name":"Change archive and retrospective","phase":"Receipt and retrospective","kind":"activity","responsibility":"Compare outcomes, deviations and recovery measures with expectations and record improvements. Deliver: release retrospective and improvements."},{"id":"p6_review","name":"Receipt and retrospective review","phase":"Receipt and retrospective","kind":"decision","responsibility":"Review operations receipt and change archive and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"exception_action","name":"Rollback and data consistency response","phase":"Exceptions and recovery","kind":"activity","responsibility":"Restore within approved rollback boundaries, verify data, interfaces and configuration, and record evidence needed for another release."},{"id":"exception_review","name":"Recovery and readiness review","phase":"Exceptions and recovery","kind":"decision","responsibility":"Check impact, response evidence and recovery status. Identify reviews to repeat and obtain authorized confirmation before resuming."}],"edges":[{"from":"p1_work1","to":"p1_review","kind":"sequence","label":""},{"from":"p1_work2","to":"p1_review","kind":"sequence","label":""},{"from":"p1_review","to":"p1_work1","kind":"feedback","label":"Needs revision"},{"from":"p1_review","to":"p2_work1","kind":"sequence","label":"Accepted"},{"from":"p1_review","to":"p2_work2","kind":"sequence","label":"Accepted"},{"from":"p2_work1","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work2","to":"p2_review","kind":"sequence","label":""},{"from":"p2_review","to":"p2_work1","kind":"feedback","label":"Needs revision"},{"from":"p2_review","to":"p3_work1","kind":"sequence","label":"Accepted"},{"from":"p2_review","to":"p3_work2","kind":"sequence","label":"Accepted"},{"from":"p3_work1","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work2","to":"p3_review","kind":"sequence","label":""},{"from":"p3_review","to":"p3_work1","kind":"feedback","label":"Needs revision"},{"from":"p3_review","to":"p4_work1","kind":"sequence","label":"Accepted"},{"from":"p4_work1","to":"p4_work2","kind":"sequence","label":""},{"from":"p4_work2","to":"p4_review","kind":"sequence","label":""},{"from":"p4_review","to":"p4_work1","kind":"feedback","label":"Needs revision"},{"from":"p4_review","to":"p5_work1","kind":"sequence","label":"Accepted"},{"from":"p5_work1","to":"p5_work2","kind":"sequence","label":""},{"from":"p5_work2","to":"p5_review","kind":"sequence","label":""},{"from":"p5_review","to":"p5_work1","kind":"feedback","label":"Needs revision"},{"from":"p5_review","to":"p6_work1","kind":"sequence","label":"Accepted"},{"from":"p5_review","to":"p6_work2","kind":"sequence","label":"Accepted"},{"from":"p6_work1","to":"p6_review","kind":"sequence","label":""},{"from":"p6_work2","to":"p6_review","kind":"sequence","label":""},{"from":"p6_review","to":"p6_work1","kind":"feedback","label":"Needs revision"},{"from":"p5_review","to":"exception_action","kind":"sequence","label":"Exception response"},{"from":"exception_action","to":"exception_review","kind":"sequence","label":""},{"from":"exception_review","to":"p3_work1","kind":"feedback","label":"Confirmed re-review"}]}'::jsonb),
('ai-lifecycle-advanced','4d0f626f57af901f71eade651283536a','{"nodes":[{"id":"p1_work1","name":"应用场景与交付目标","phase":"目标与评测范围","kind":"activity","responsibility":"明确用户任务、可接受结果和成本时延目标，划分模型与人工处理边界。交付：应用需求与交付标准。"},{"id":"p1_work2","name":"基线与评测集设计","phase":"目标与评测范围","kind":"activity","responsibility":"设计可重复的对比基线、评测样本和失败类别，记录覆盖不足。交付：评测协议与基线。"},{"id":"p1_review","name":"目标与评测范围评审","phase":"目标与评测范围","kind":"decision","responsibility":"核对业务目标、基线与评测边界并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p2_work1","name":"来源与授权核对","phase":"数据与特征准入","kind":"activity","responsibility":"核对数据来源、使用范围和版本，确认适用的审阅和访问安排。交付：数据来源与使用记录。"},{"id":"p2_work2","name":"质量与标注验证","phase":"数据与特征准入","kind":"activity","responsibility":"检查缺失、偏差、重复与标注一致性，确认训练评测划分。交付：数据质量与标注报告。"},{"id":"p2_work3","name":"特征与数据契约","phase":"数据与特征准入","kind":"activity","responsibility":"规定特征口径、变换和输入输出契约，检查在线与离线一致性。交付：特征与数据契约。"},{"id":"p2_review","name":"数据与特征准入评审","phase":"数据与特征准入","kind":"decision","responsibility":"核对来源、质量与特征契约并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p3_work1","name":"模型实验与版本记录","phase":"模型与应用开发","kind":"activity","responsibility":"记录数据、参数、代码和环境，完成基线比较与实验复现。交付：实验记录与模型版本。"},{"id":"p3_work2","name":"应用集成与失败处理","phase":"模型与应用开发","kind":"activity","responsibility":"实现接口、上下文与结果处理，设计超时、低可信输出和人工接管路径。交付：应用集成与失败处理说明。"},{"id":"p3_work3","name":"观测与运行准备","phase":"模型与应用开发","kind":"activity","responsibility":"准备输入输出、质量、成本和时延观察，避免记录不必要的敏感内容。交付：观测指标与运行方案。"},{"id":"p3_review","name":"模型与应用开发评审","phase":"模型与应用开发","kind":"decision","responsibility":"核对实验可复现性与集成结果并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p4_work1","name":"质量与泛化评测","phase":"综合评测","kind":"activity","responsibility":"对照基线评估主要场景、分组表现和失败类别，记录效果限制。交付：模型与应用质量报告。"},{"id":"p4_work2","name":"安全与边界验证","phase":"综合评测","kind":"activity","responsibility":"验证相关攻击、越权输入、异常输出和人工接管处理，不将模型判断视为授权。交付：边界测试与风险记录。"},{"id":"p4_review","name":"综合评测评审","phase":"综合评测","kind":"decision","responsibility":"核对效果、边界与运行表现并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p5_work1","name":"运行包与发布准入","phase":"发布与运行观察","kind":"activity","responsibility":"核对模型、数据、接口和配置版本，整合评测和恢复依据供人工确认。交付：可审阅运行包。"},{"id":"p5_work2","name":"小范围发布与观察","phase":"发布与运行观察","kind":"activity","responsibility":"成员执行确认的发布，核对输出、质量、时延和成本，记录实际表现。交付：实际发布与观察结果。"},{"id":"p5_review","name":"发布与运行观察评审","phase":"发布与运行观察","kind":"decision","responsibility":"核对批准版本、线上验证与降级条件并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p6_work1","name":"质量漂移与用户反馈","phase":"漂移与持续改进","kind":"activity","responsibility":"比较当前输入和结果与基线，收集异常案例及用户反馈。交付：漂移与反馈报告。"},{"id":"p6_work2","name":"重训与回滚建议","phase":"漂移与持续改进","kind":"activity","responsibility":"根据证据提出数据修订、重训或版本恢复建议，由项目人员决定后续工作。交付：重训与恢复建议。"},{"id":"p6_review","name":"漂移与持续改进评审","phase":"漂移与持续改进","kind":"decision","responsibility":"核对漂移、反馈与重训依据并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"exception_action","name":"模型失效与数据隔离","phase":"异常处置与恢复","kind":"activity","responsibility":"核对异常输出和数据来源，由成员按预案隔离、恢复或降级，保留模型与数据版本证据。"},{"id":"exception_review","name":"恢复与重新准入","phase":"异常处置与恢复","kind":"decision","responsibility":"核对异常影响、处置证据与恢复状态，明确哪些工作需要重新评审；获得有权人确认后再进入正常推进路径。"}],"edges":[{"from":"p1_work1","to":"p1_review","kind":"sequence","label":""},{"from":"p1_work2","to":"p1_review","kind":"sequence","label":""},{"from":"p1_review","to":"p1_work1","kind":"feedback","label":"未通过：修订"},{"from":"p1_review","to":"p2_work1","kind":"sequence","label":"通过"},{"from":"p1_review","to":"p2_work2","kind":"sequence","label":"通过"},{"from":"p1_review","to":"p2_work3","kind":"sequence","label":"通过"},{"from":"p2_work1","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work2","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work3","to":"p2_review","kind":"sequence","label":""},{"from":"p2_review","to":"p2_work1","kind":"feedback","label":"未通过：修订"},{"from":"p2_review","to":"p3_work1","kind":"sequence","label":"通过"},{"from":"p2_review","to":"p3_work2","kind":"sequence","label":"通过"},{"from":"p2_review","to":"p3_work3","kind":"sequence","label":"通过"},{"from":"p3_work1","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work2","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work3","to":"p3_review","kind":"sequence","label":""},{"from":"p3_review","to":"p3_work1","kind":"feedback","label":"未通过：修订"},{"from":"p3_review","to":"p4_work1","kind":"sequence","label":"通过"},{"from":"p3_review","to":"p4_work2","kind":"sequence","label":"通过"},{"from":"p4_work1","to":"p4_review","kind":"sequence","label":""},{"from":"p4_work2","to":"p4_review","kind":"sequence","label":""},{"from":"p4_review","to":"p4_work1","kind":"feedback","label":"未通过：修订"},{"from":"p4_review","to":"p5_work1","kind":"sequence","label":"通过"},{"from":"p5_work1","to":"p5_work2","kind":"sequence","label":""},{"from":"p5_work2","to":"p5_review","kind":"sequence","label":""},{"from":"p5_review","to":"p5_work1","kind":"feedback","label":"未通过：修订"},{"from":"p5_review","to":"p6_work1","kind":"sequence","label":"通过"},{"from":"p5_review","to":"p6_work2","kind":"sequence","label":"通过"},{"from":"p6_work1","to":"p6_review","kind":"sequence","label":""},{"from":"p6_work2","to":"p6_review","kind":"sequence","label":""},{"from":"p6_review","to":"p6_work1","kind":"feedback","label":"未通过：修订"},{"from":"p5_review","to":"exception_action","kind":"sequence","label":"异常：专项处置"},{"from":"exception_action","to":"exception_review","kind":"sequence","label":""},{"from":"exception_review","to":"p2_work1","kind":"feedback","label":"确认后重新评审"}]}'::jsonb),
('ai-lifecycle-advanced','39c8f3a9cd2f3ec29580d8b088874633','{"nodes":[{"id":"p1_work1","name":"Application scenarios and delivery goals","phase":"Goals and evaluation scope","kind":"activity","responsibility":"Define user tasks, acceptable results, cost and latency goals, and human handling boundaries. Deliver: application requirements and delivery criteria."},{"id":"p1_work2","name":"Baseline and evaluation design","phase":"Goals and evaluation scope","kind":"activity","responsibility":"Design reproducible baselines, evaluation samples and failure categories and note coverage gaps. Deliver: evaluation protocol and baseline."},{"id":"p1_review","name":"Goals and evaluation scope review","phase":"Goals and evaluation scope","kind":"decision","responsibility":"Review business goals, baseline and evaluation boundaries and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p2_work1","name":"Lineage and authorization checks","phase":"Data and feature readiness","kind":"activity","responsibility":"Check data origin, permitted use and versions and identify applicable review and access arrangements. Deliver: data lineage and use record."},{"id":"p2_work2","name":"Quality and labeling validation","phase":"Data and feature readiness","kind":"activity","responsibility":"Check missing data, bias, duplicates, labeling consistency and training-evaluation separation. Deliver: data quality and labeling report."},{"id":"p2_work3","name":"Feature and data contracts","phase":"Data and feature readiness","kind":"activity","responsibility":"Define feature meanings, transformations and contracts and check offline-online consistency. Deliver: feature and data contracts."},{"id":"p2_review","name":"Data and feature readiness review","phase":"Data and feature readiness","kind":"decision","responsibility":"Review lineage, quality and feature contracts and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p3_work1","name":"Model experiments and versions","phase":"Model and application development","kind":"activity","responsibility":"Record data, parameters, code and environments and reproduce baseline comparisons. Deliver: experiment records and model version."},{"id":"p3_work2","name":"Application integration and failure handling","phase":"Model and application development","kind":"activity","responsibility":"Implement interfaces and result handling with timeout, low-confidence and human handoff paths. Deliver: integration and failure-handling notes."},{"id":"p3_work3","name":"Observability and operations readiness","phase":"Model and application development","kind":"activity","responsibility":"Prepare observation of inputs, quality, cost and latency without unnecessary sensitive content. Deliver: observability and operations plan."},{"id":"p3_review","name":"Model and application development review","phase":"Model and application development","kind":"decision","responsibility":"Review experiment reproducibility and integration results and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p4_work1","name":"Quality and generalization evaluation","phase":"Integrated evaluation","kind":"activity","responsibility":"Compare key scenarios, cohort performance and failures against the baseline and record limits. Deliver: model and application quality report."},{"id":"p4_work2","name":"Safety and boundary verification","phase":"Integrated evaluation","kind":"activity","responsibility":"Check relevant attacks, unauthorized inputs, failures and human handoff without treating model judgments as authority. Deliver: boundary tests and risk record."},{"id":"p4_review","name":"Integrated evaluation review","phase":"Integrated evaluation","kind":"decision","responsibility":"Review effectiveness, boundaries and runtime behavior and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p5_work1","name":"Runtime package and release readiness","phase":"Deployment and observation","kind":"activity","responsibility":"Check model, data, interface and configuration versions and consolidate evaluation and recovery evidence. Deliver: reviewable runtime package."},{"id":"p5_work2","name":"Limited rollout and observation","phase":"Deployment and observation","kind":"activity","responsibility":"Members execute approved rollout and record outputs, quality, latency and cost. Deliver: actual rollout and observation results."},{"id":"p5_review","name":"Deployment and observation review","phase":"Deployment and observation","kind":"decision","responsibility":"Review approved versions, live checks and fallback criteria and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p6_work1","name":"Quality drift and user feedback","phase":"Drift and ongoing improvement","kind":"activity","responsibility":"Compare current inputs and results with the baseline and collect exceptions and user feedback. Deliver: drift and feedback report."},{"id":"p6_work2","name":"Retraining and rollback proposals","phase":"Drift and ongoing improvement","kind":"activity","responsibility":"Use evidence to propose data updates, retraining or version recovery for human planning. Deliver: retraining and recovery proposal."},{"id":"p6_review","name":"Drift and ongoing improvement review","phase":"Drift and ongoing improvement","kind":"decision","responsibility":"Review drift, feedback and retraining evidence and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"exception_action","name":"Model failure and data isolation","phase":"Exceptions and recovery","kind":"activity","responsibility":"Investigate outputs and data lineage, apply approved containment or fallback, and preserve model and data versions."},{"id":"exception_review","name":"Recovery and readiness review","phase":"Exceptions and recovery","kind":"decision","responsibility":"Check impact, response evidence and recovery status. Identify reviews to repeat and obtain authorized confirmation before resuming."}],"edges":[{"from":"p1_work1","to":"p1_review","kind":"sequence","label":""},{"from":"p1_work2","to":"p1_review","kind":"sequence","label":""},{"from":"p1_review","to":"p1_work1","kind":"feedback","label":"Needs revision"},{"from":"p1_review","to":"p2_work1","kind":"sequence","label":"Accepted"},{"from":"p1_review","to":"p2_work2","kind":"sequence","label":"Accepted"},{"from":"p1_review","to":"p2_work3","kind":"sequence","label":"Accepted"},{"from":"p2_work1","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work2","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work3","to":"p2_review","kind":"sequence","label":""},{"from":"p2_review","to":"p2_work1","kind":"feedback","label":"Needs revision"},{"from":"p2_review","to":"p3_work1","kind":"sequence","label":"Accepted"},{"from":"p2_review","to":"p3_work2","kind":"sequence","label":"Accepted"},{"from":"p2_review","to":"p3_work3","kind":"sequence","label":"Accepted"},{"from":"p3_work1","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work2","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work3","to":"p3_review","kind":"sequence","label":""},{"from":"p3_review","to":"p3_work1","kind":"feedback","label":"Needs revision"},{"from":"p3_review","to":"p4_work1","kind":"sequence","label":"Accepted"},{"from":"p3_review","to":"p4_work2","kind":"sequence","label":"Accepted"},{"from":"p4_work1","to":"p4_review","kind":"sequence","label":""},{"from":"p4_work2","to":"p4_review","kind":"sequence","label":""},{"from":"p4_review","to":"p4_work1","kind":"feedback","label":"Needs revision"},{"from":"p4_review","to":"p5_work1","kind":"sequence","label":"Accepted"},{"from":"p5_work1","to":"p5_work2","kind":"sequence","label":""},{"from":"p5_work2","to":"p5_review","kind":"sequence","label":""},{"from":"p5_review","to":"p5_work1","kind":"feedback","label":"Needs revision"},{"from":"p5_review","to":"p6_work1","kind":"sequence","label":"Accepted"},{"from":"p5_review","to":"p6_work2","kind":"sequence","label":"Accepted"},{"from":"p6_work1","to":"p6_review","kind":"sequence","label":""},{"from":"p6_work2","to":"p6_review","kind":"sequence","label":""},{"from":"p6_review","to":"p6_work1","kind":"feedback","label":"Needs revision"},{"from":"p5_review","to":"exception_action","kind":"sequence","label":"Exception response"},{"from":"exception_action","to":"exception_review","kind":"sequence","label":""},{"from":"exception_review","to":"p2_work1","kind":"feedback","label":"Confirmed re-review"}]}'::jsonb),
('data-delivery-advanced','fa553e5cd1dffecb686661d13ae8e854','{"nodes":[{"id":"p1_work1","name":"业务问题与使用场景","phase":"问题与口径","kind":"activity","responsibility":"访谈业务使用者，明确需要回答的问题、决策用途和交付形式。交付：问题与使用场景清单。"},{"id":"p1_work2","name":"指标与语义口径","phase":"问题与口径","kind":"activity","responsibility":"定义指标、维度、时间窗口和解释范围，标注存在争议的口径。交付：指标与语义字典。"},{"id":"p1_review","name":"问题与口径评审","phase":"问题与口径","kind":"decision","responsibility":"核对业务问题、指标与交付口径并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p2_work1","name":"来源与依赖登记","phase":"来源与质量","kind":"activity","responsibility":"登记数据系统、负责人、访问方式和刷新依赖，核对使用范围。交付：来源和依赖登记。"},{"id":"p2_work2","name":"数据画像与问题盘点","phase":"来源与质量","kind":"activity","responsibility":"检验缺失、异常、重复、时序及标识关联，明确修复和接受的范围。交付：数据质量盘点。"},{"id":"p2_review","name":"来源与质量评审","phase":"来源与质量","kind":"decision","responsibility":"核对来源可信性与质量范围并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p3_work1","name":"采集与转换管道","phase":"采集与模型建设","kind":"activity","responsibility":"成员建设可追溯的采集与转换，记录来源版本、重放和失败处理方式。交付：采集转换与血缘记录。"},{"id":"p3_work2","name":"数据模型与校验","phase":"采集与模型建设","kind":"activity","responsibility":"按确认口径建设模型，核对主键、聚合、关联和增量计算结果。交付：数据模型与校验结果。"},{"id":"p3_review","name":"采集与模型建设评审","phase":"采集与模型建设","kind":"decision","responsibility":"核对管道、语义模型和测试依据并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p4_work1","name":"分析与结果生成","phase":"分析与复核","kind":"activity","responsibility":"基于固定数据版本完成分析，保留方法、代码、参数和中间结果。交付：分析结果与可复现材料。"},{"id":"p4_work2","name":"口径与结果复核","phase":"分析与复核","kind":"activity","responsibility":"独立核对关键结果、样本和口径，区分事实、估计与推断。交付：复核记录与限制说明。"},{"id":"p4_review","name":"分析与复核评审","phase":"分析与复核","kind":"decision","responsibility":"核对分析依据与解释限制并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p5_work1","name":"报表与数据产品呈现","phase":"产品与使用验收","kind":"activity","responsibility":"制作面向使用者的报表或数据接口，说明含义、更新频率和适用范围。交付：数据产品与使用说明。"},{"id":"p5_work2","name":"权限与刷新验证","phase":"产品与使用验收","kind":"activity","responsibility":"核对访问范围、刷新失败处理、告警与负责人安排。交付：运行与访问验证记录。"},{"id":"p5_review","name":"产品与使用验收评审","phase":"产品与使用验收","kind":"decision","responsibility":"核对业务可用性与运行条件并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p6_work1","name":"交付接收与培训","phase":"交付与维护","kind":"activity","responsibility":"由业务和维护人员核对成果与资料，记录接收和使用问题。交付：交付接收与培训记录。"},{"id":"p6_work2","name":"质量跟踪与口径变更","phase":"交付与维护","kind":"activity","responsibility":"持续登记质量与口径变化，评估影响后提出版本或流程调整。交付：维护与变更记录。"},{"id":"p6_review","name":"交付与维护评审","phase":"交付与维护","kind":"decision","responsibility":"核对接收、问题跟踪与维护责任并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"exception_action","name":"口径偏差与数据重建","phase":"异常处置与恢复","kind":"activity","responsibility":"定位错误口径和受影响下游，隔离结果，重建经确认的数据版本并记录影响。"},{"id":"exception_review","name":"恢复与重新准入","phase":"异常处置与恢复","kind":"decision","responsibility":"核对异常影响、处置证据与恢复状态，明确哪些工作需要重新评审；获得有权人确认后再进入正常推进路径。"}],"edges":[{"from":"p1_work1","to":"p1_review","kind":"sequence","label":""},{"from":"p1_work2","to":"p1_review","kind":"sequence","label":""},{"from":"p1_review","to":"p1_work1","kind":"feedback","label":"未通过：修订"},{"from":"p1_review","to":"p2_work1","kind":"sequence","label":"通过"},{"from":"p1_review","to":"p2_work2","kind":"sequence","label":"通过"},{"from":"p2_work1","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work2","to":"p2_review","kind":"sequence","label":""},{"from":"p2_review","to":"p2_work1","kind":"feedback","label":"未通过：修订"},{"from":"p2_review","to":"p3_work1","kind":"sequence","label":"通过"},{"from":"p2_review","to":"p3_work2","kind":"sequence","label":"通过"},{"from":"p3_work1","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work2","to":"p3_review","kind":"sequence","label":""},{"from":"p3_review","to":"p3_work1","kind":"feedback","label":"未通过：修订"},{"from":"p3_review","to":"p4_work1","kind":"sequence","label":"通过"},{"from":"p4_work1","to":"p4_work2","kind":"sequence","label":""},{"from":"p4_work2","to":"p4_review","kind":"sequence","label":""},{"from":"p4_review","to":"p4_work1","kind":"feedback","label":"未通过：修订"},{"from":"p4_review","to":"p5_work1","kind":"sequence","label"