('data-delivery-advanced','3231c946015d3848ff83bd086c84ba67','{"nodes":[{"id":"p1_work1","name":"Business questions and use cases","phase":"Questions and definitions","kind":"activity","responsibility":"Interview users to define questions, decision use and delivery formats. Deliver: question and use-case list."},{"id":"p1_work2","name":"Metric and semantic definitions","phase":"Questions and definitions","kind":"activity","responsibility":"Define metrics, dimensions, time windows and interpretation boundaries and flag disputed definitions. Deliver: metric and semantic dictionary."},{"id":"p1_review","name":"Questions and definitions review","phase":"Questions and definitions","kind":"decision","responsibility":"Review business questions, metrics and delivery definitions and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p2_work1","name":"Source and dependency registration","phase":"Sources and quality","kind":"activity","responsibility":"Register source systems, ownership, access, refresh dependencies and permitted use. Deliver: source and dependency register."},{"id":"p2_work2","name":"Profiling and issue assessment","phase":"Sources and quality","kind":"activity","responsibility":"Profile missing values, outliers, duplicates, timing and identifiers and define treatment boundaries. Deliver: data quality assessment."},{"id":"p2_review","name":"Sources and quality review","phase":"Sources and quality","kind":"decision","responsibility":"Review source reliability and quality boundaries and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p3_work1","name":"Collection and transformation pipeline","phase":"Collection and modeling","kind":"activity","responsibility":"Build traceable collection and transformation with source versions, replay and failure handling. Deliver: pipeline and lineage evidence."},{"id":"p3_work2","nam