e":"Product and use acceptance","kind":"decision","responsibility":"Review business usability and operational conditions and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p6_work1","name":"Receipt and user training","phase":"Delivery and maintenance","kind":"activity","responsibility":"Business and maintenance staff review deliverables and record receipt and usage issues. Deliver: delivery receipt and training record."},{"id":"p6_work2","name":"Quality tracking and definition changes","phase":"Delivery and maintenance","kind":"activity","responsibility":"Track quality and definition changes and propose version updates after impact review. Deliver: maintenance and change record."},{"id":"p6_review","name":"Delivery and maintenance review","phase":"Delivery and maintenance","kind":"decision","responsibility":"Review receipt, issue tracking and maintenance ownership and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"exception_action","name":"Definition mismatch and data rebuild","phase":"Exceptions and recovery","kind":"activity","responsibility":"Identify incorrect definitions and downstream impact, isolate results and rebuild approved data versions."},{"id":"exception_review","name":"Recovery and readiness review","phase":"Exceptions and recovery","kind":"decision","responsibility":"Check impact, response evidence and recovery status. Identify reviews to repeat and obtain authorized confirmation before resuming."}],"edges":[{"from":"p1_work1","to":"p1_review","kind":"sequence","label":""},{"from":"p1_work2","to":"p1_review","kind":"sequence","label":""},{"from":"p1_review","to":"p1_work1","kind":"feedback","label":"Needs revision"},{"from":"p1_review","to":"p2_work1","kind":"sequence","label":"Accepted"},{"from":"p1_review","to":"p2_work2","kind":"sequence","label":"Accepted"},{"from":"p2_work1","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work2","to":"p2_review","kind":"sequence","label":""},{"from":"p2_review","to":"p2_work1","kind":"feedback","label":"Needs revision"},{"from":"p2_review","to":"p3_work1","kind":"sequence","label":"Accepted"},{"from":"p2_review","to":"p3_work2","kind":"sequence","label":"Accepted"},{"from":"p3_work1","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work2","to":"p3_review","kind":"sequence","label":""},{"from":"p3_review","to":"p3_work1","kind":"feedback","label":"Needs revision"},{"from":"p3_review","to":"p4_work1","kind":"sequence","label":"Accepted"},{"from":"p4_work1","to":"p4_work2","kind":"sequence","label":""},{"from":"p4_work2","to":"p4_review","kind":"sequence","label":""},{"from":"p4_review","to":"p4_work1","kind":"feedback","label":"Needs revision"},{"from":"p4_review","to":"p5_work1","kind":"sequence","label":"Accepted"},{"from":"p4_review","to":"p5_work2","kind":"sequence","label":"Accepted"},{"from":"p5_work1","to":"p5_review","kind":"sequence","label":""},{"from":"p5_work2","to":"p5_review","kind":"sequence","label":""},{"from":"p5_review","to":"p5_work1","kind":"feedback","label":"Needs revision"},{"from":"p5_review","to":"p6_work1","kind":"sequence","label":"Accepted"},{"from":"p5_review","to":"p6_work2","kind":"sequence","label":"Accepted"},{"from":"p6_work1","to":"p6_review","kind":"sequence","label":""},{"from":"p6_work2","to":"p6_review","kind":"sequence","label":""},{"from":"p6_review","to":"p6_work1","kind":"feedback","label":"Needs revision"},{"from":"p4_review","to":"exception_action","kind":"sequence","label":"Exception response"},{"from":"exception_action","to":"exception_review","kind":"sequence","label":""},{"from":"exception_review","to":"p2_work1","kind":"feedback","label":"Confirmed re-review"}]}'::jsonb),
('infrastructure-migration-advanced','30692aa0b6fe9ab36b3d571702deee11','{"nodes":[{"id":"p1_work1","name":"资产与系统盘点","phase":"现状与依赖","kind":"activity","responsibility":"登记系统、版本、数据、负责人和运行方式，标明需要保留的历史与服务。交付：资产与责任清单。"},{"id":"p1_work2","name":"业务连续性与依赖","phase":"现状与依赖","kind":"activity","responsibility":"评估接口、流量、窗口和恢复目标，确认系统间的割接先后与限制。交付：依赖图与连续性要求。"},{"id":"p1_review","name":"现状与依赖评审","phase":"现状与依赖","kind":"decision","responsibility":"核对资产、依赖与业务约束并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p2_work1","name":"迁移策略与目标环境","phase":"迁移设计","kind":"activity","responsibility":"选择分批、同步或替代方案，说明目标环境、迁移范围和限制。交付：迁移策略与目标设计。"},{"id":"p2_work2","name":"数据与回退边界","phase":"迁移设计","kind":"activity","responsibility":"定义数据迁移、写入切换、回退边界和无法直接回退时的恢复办法。交付：数据与恢复设计。"},{"id":"p2_review","name":"迁移设计评审","phase":"迁移设计","kind":"decision","responsibility":"核对目标架构与迁移取舍并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p3_work1","name":"基础设施与访问准备","phase":"并行准备","kind":"activity","responsibility":"成员配置网络、资源、访问和监控，核对目标服务可用性。交付：目标环境与访问检查。"},{"id":"p3_work2","name":"迁移工具与数据验证","phase":"并行准备","kind":"activity","responsibility":"验证迁移工具、映射、同步和一致性检查，保留可核对的源版本。交付：迁移工具与一致性证据。"},{"id":"p3_work3","name":"沟通与运行手册","phase":"并行准备","kind":"activity","responsibility":"明确窗口、步骤、验证、观察和恢复的负责人及通知方式。交付：割接运行手册。"},{"id":"p3_review","name":"并行准备评审","phase":"并行准备","kind":"decision","responsibility":"核对环境、数据与协作准备并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p4_work1","name":"全流程迁移演练","phase":"演练与准入","kind":"activity","responsibility":"在隔离范围演练迁移和验证，记录耗时、偏差与依赖问题。交付：迁移演练记录。"},{"id":"p4_work2","name":"回退与恢复演练","phase":"演练与准入","kind":"activity","responsibility":"验证可恢复条件、工具和数据状态，确认超窗或故障时的人工决策依据。交付：恢复演练与准入依据。"},{"id":"p4_review","name":"演练与准入评审","phase":"演练与准入","kind":"decision","responsibility":"核对演练时间、验证与恢复能力并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p5_work1","name":"执行割接与同步核对","phase":"割接与核验","kind":"activity","responsibility":"按确认方案切换服务或数据，逐步登记实际时间、变更和数据边界。交付：实际割接记录。"},{"id":"p5_work2","name":"技术与业务验证","phase":"割接与核验","kind":"activity","responsibility":"共同核对功能、性能、接口、数据和业务场景，判断恢复或继续的依据。交付：联合割接验证报告。"},{"id":"p5_review","name":"割接与核验评审","phase":"割接与核验","kind":"decision","responsibility":"核对实际割接与业务核验并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p6_work1","name":"运维接收与观察","phase":"接收与后续治理","kind":"activity","responsibility":"确认值守、监控、资料、备份和恢复安排，记录接收与观察结果。交付：运维接收资料。"},{"id":"p6_work2","name":"遗留处置与迁移复盘","phase":"接收与后续治理","kind":"activity","responsibility":"核对可退役范围、保留数据和剩余问题，取得确认后安排后续处置。交付：迁移复盘与后续计划。"},{"id":"p6_review","name":"接收与后续治理评审","phase":"接收与后续治理","kind":"decision","responsibility":"核对运维接收与遗留系统处理并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"exception_action","name":"割接失败与业务恢复","phase":"异常处置与恢复","kind":"activity","responsibility":"由成员按已确认的回退或向前恢复方案处置，核对数据写入边界、依赖服务和业务恢复证据。"},{"id":"exception_review","name":"恢复与重新准入","phase":"异常处置与恢复","kind":"decision","responsibility":"核对异常影响、处置证据与恢复状态，明确哪些工作需要重新评审；获得有权人确认后再进入正常推进路径。"}],"edges":[{"from":"p1_work1","to":"p1_review","kind":"sequence","label":""},{"from":"p1_work2","to":"p1_review","kind":"sequence","label":""},{"from":"p1_review","to":"p1_work1","kind":"feedback","label":"未通过：修订"},{"from":"p1_review","to":"p2_work1","kind":"sequence","label":"通过"},{"from":"p1_review","to":"p2_work2","kind":"sequence","label":"通过"},{"from":"p2_work1","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work2","to":"p2_review","kind":"sequence","label":""},{"from":"p2_review","to":"p2_work1","kind":"feedback","label":"未通过：修订"},{"from":"p2_review","to":"p3_work1","kind":"sequence","label":"通过"},{"from":"p2_review","to":"p3_work2","kind":"sequence","label":"通过"},{"from":"p2_review","to":"p3_work3","kind":"sequence","label":"通过"},{"from":"p3_work1","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work2","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work3","to":"p3_review","kind":"sequence","label":""},{"from":"p3_review","to":"p3_work1","kind":"feedback","label":"未通过：修订"},{"from":"p3_review","to":"p4_work1","kind":"sequence","label":"通过"},{"from":"p4_work1","to":"p4_work2","kind":"sequence","label":""},{"from":"p4_work2","to":"p4_review","kind":"sequence","label":""},{"from":"p4_review","to":"p4_work1","kind":"feedback","label":"未通过：修订"},{"from":"p4_review","to":"p5_work1","kind":"sequence","label":"通过"},{"from":"p5_work1","to":"p5_work2","kind":"sequence","label":""},{"from":"p5_work2","to":"p5_review","kind":"sequence","label":""},{"from":"p5_review","to":"p5_work1","kind":"feedback","label":"未通过：修订"},{"from":"p5_review","to":"p6_work1","kind":"sequence","label":"通过"},{"from":"p5_review","to":"p6_work2","kind":"sequence","label":"通过"},{"from":"p6_work1","to":"p6_review","kind":"sequence","label":""},{"from":"p6_work2","to":"p6_review","kind":"sequence","label":""},{"from":"p6_review","to":"p6_work1","kind":"feedback","label":"未通过：修订"},{"from":"p5_review","to":"exception_action","kind":"sequence","label":"异常：专项处置"},{"from":"exception_action","to":"exception_review","kind":"sequence","label":""},{"from":"exception_review","to":"p4_work1","kind":"feedback","label":"确认后重新评审"}]}'::jsonb),
('infrastructure-migration-advanced','b597464dd577ec8df85de1dea9edee8c','{"nodes":[{"id":"p1_work1","name":"Asset and system inventory","phase":"Current state and dependencies","kind":"activity","responsibility":"Inventory systems, versions, data, ownership and operations and identify history and services to preserve. Deliver: asset and ownership inventory."},{"id":"p1_work2","name":"Continuity and dependency analysis","phase":"Current state and dependencies","kind":"activity","responsibility":"Assess interfaces, traffic, windows and recovery goals and identify cutover ordering constraints. Deliver: dependency map and continuity requirements."},{"id":"p1_review","name":"Current state and dependencies review","phase":"Current state and dependencies","kind":"decision","responsibility":"Review assets, dependencies and business constraints and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p2_work1","name":"Migration strategy and target environment","phase":"Migration design","kind":"activity","responsibility":"Select staged, synchronized or replacement approaches and define target scope and limits. Deliver: migration strategy and target design."},{"id":"p2_work2","name":"Data and rollback boundaries","phase":"Migration design","kind":"activity","responsibility":"Define data migration, write cutover, rollback boundaries and recovery when direct rollback is unsuitable. Deliver: data and recovery design."},{"id":"p2_review","name":"Migration design review","phase":"Migration design","kind":"decision","responsibility":"Review target architecture and migration decisions and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p3_work1","name":"Infrastructure and access preparation","phase":"Parallel preparation","kind":"activity","responsibility":"Members prepare networking, resources, access and monitoring and verify target services. Deliver: target environment and access checks."},{"id":"p3_work2","name":"Migration tooling and data verification","phase":"Parallel preparation","kind":"activity","responsibility":"Validate tools, mapping, synchronization and consistency checks against identifiable source versions. Deliver: migration tooling and consistency evidence."},{"id":"p3_work3","name":"Communication and runbook","phase":"Parallel preparation","kind":"activity","responsibility":"Define owners and communication for the window, steps, checks, observation and recovery. Deliver: cutover runbook."},{"id":"p3_review","name":"Parallel preparation review","phase":"Parallel preparation","kind":"decision","responsibility":"Review environment, data and coordination readiness and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p4_work1","name":"End-to-end migration rehearsal","phase":"Rehearsal and readiness","kind":"activity","responsibility":"Rehearse migration and verification in isolation and record timing, deviations and dependencies. Deliver: migration rehearsal record."},{"id":"p4_work2","name":"Rollback and recovery rehearsal","phase":"Rehearsal and readiness","kind":"activity","responsibility":"Verify recovery conditions, tools and data state and document decisions for outages or window overruns. Deliver: recovery rehearsal and readiness evidence."},{"id":"p4_review","name":"Rehearsal and readiness review","phase":"Rehearsal and readiness","kind":"decision","responsibility":"Review rehearsal timing, checks and recovery capability and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p5_work1","name":"Execute cutover and synchronization checks","phase":"Cutover and verification","kind":"activity","responsibility":"Execute approved service or data cutover and record timing, changes and data boundaries. Deliver: actual cutover record."},{"id":"p5_work2","name":"Technical and business verification","phase":"Cutover and verification","kind":"activity","responsibility":"Jointly check functions, performance, interfaces, data and business scenarios to support recovery or continuation. Deliver: joint cutover verification report."},{"id":"p5_review","name":"Cutover and verification review","phase":"Cutover and verification","kind":"decision","responsibility":"Review actual cutover and business verification and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p6_work1","name":"Operations receipt and observation","phase":"Receipt and ongoing governance","kind":"activity","responsibility":"Confirm monitoring, materials, backups, recovery and ownership and record receipt and observation. Deliver: operations receipt materials."},{"id":"p6_work2","name":"Legacy treatment and migration retrospective","phase":"Receipt and ongoing governance","kind":"activity","responsibility":"Review retirement scope, retained data and remaining issues before proposing follow-up treatment. Deliver: migration retrospective and follow-up plan."},{"id":"p6_review","name":"Receipt and ongoing governance review","phase":"Receipt and ongoing governance","kind":"decision","responsibility":"Review operations receipt and legacy-system treatment and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"exception_action","name":"Cutover failure and business recovery","phase":"Exceptions and recovery","kind":"activity","responsibility":"Members apply approved rollback or recovery, verify data-write boundaries, dependent services and business recovery evidence."},{"id":"exception_review","name":"Recovery and readiness review","phase":"Exceptions and recovery","kind":"decision","responsibility":"Check impact, response evidence and recovery status. Identify reviews to repeat and obtain authorized confirmation before resuming."}],"edges":[{"from":"p1_work1","to":"p1_review","kind":"sequence","label":""},{"from":"p1_work2","to":"p1_review","kind":"sequence","label":""},{"from":"p1_review","to":"p1_work1","kind":"feedback","label":"Needs revision"},{"from":"p1_review","to":"p2_work1","kind":"sequence","label":"Accepted"},{"from":"p1_review","to":"p2_work2","kind":"sequence","label":"Accepted"},{"from":"p2_work1","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work2","to":"p2_review","kind":"sequence","label":""},{"from":"p2_review","to":"p2_work1","kind":"feedback","label":"Needs revision"},{"from":"p2_review","to":"p3_work1","kind":"sequence","label":"Accepted"},{"from":"p2_review","to":"p3_work2","kind":"sequence","label":"Accepted"},{"from":"p2_review","to":"p3_work3","kind":"sequence","label":"Accepted"},{"from":"p3_work1","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work2","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work3","to":"p3_review","kind":"sequence","label":""},{"from":"p3_review","to":"p3_work1","kind":"feedback","label":"Needs revision"},{"from":"p3_review","to":"p4_work1","kind":"sequence","label":"Accepted"},{"from":"p4_work1","to":"p4_work2","kind":"sequence","label":""},{"from":"p4_work2","to":"p4_review","kind":"sequence","label":""},{"from":"p4_review","to":"p4_work1","kind":"feedback","label":"Needs revision"},{"from":"p4_review","to":"p5_work1","kind":"sequence","label":"Accepted"},{"from":"p5_work1","to":"p5_work2","kind":"sequence","label":""},{"from":"p5_work2","to":"p5_review","kind":"sequence","label":""},{"from":"p5_review","to":"p5_work1","kind":"feedback","label":"Needs revision"},{"from":"p5_review","to":"p6_work1","kind":"sequence","label":"Accepted"},{"from":"p5_review","to":"p6_work2","kind":"sequence","label":"Accepted"},{"from":"p6_work1","to":"p6_review","kind":"sequence","label":""},{"from":"p6_work2","to":"p6_review","kind":"sequence","label":""},{"from":"p6_review","to":"p6_work1","kind":"feedback","label":"Needs revision"},{"from":"p5_review","to":"exception_action","kind":"sequence","label":"Exception response"},{"from":"exception_action","to":"exception_review","kind":"sequence","label":""},{"from":"exception_review","to":"p4_work1","kind":"feedback","label":"Confirmed re-review"}]}'::jsonb),
('product-design-advanced','c3c8e2c99f121e1405d85d8c4f2d9eb7','{"nodes":[{"id":"p1_work1","name":"研究目标与招募","phase":"发现与研究","kind":"activity","responsibility":"确定研究问题、目标用户、样本范围和访谈安排，核对研究材料使用方式。交付：研究计划与样本说明。"},{"id":"p1_work2","name":"访谈与使用观察","phase":"发现与研究","kind":"activity","responsibility":"收集使用过程、行为与痛点，区分原始记录和团队解释。交付：原始证据与观察记录。"},{"id":"p1_review","name":"发现与研究评审","phase":"发现与研究","kind":"decision","responsibility":"核对研究问题与可追溯用户证据并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p2_work1","name":"洞察与机会归纳","phase":"问题定义","kind":"activity","responsibility":"整理重复问题、矛盾和机会，建立可追溯到材料的判断依据。交付：洞察与机会地图。"},{"id":"p2_work2","name":"范围与成功指标","phase":"问题定义","kind":"activity","responsibility":"把问题转成目标、适用范围、优先级和可验证的体验指标。交付：问题陈述与成功指标。"},{"id":"p2_review","name":"问题定义评审","phase":"问题定义","kind":"decision","responsibility":"核对用户洞察与成功指标并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p3_work1","name":"信息结构与交互原型","phase":"并行设计探索","kind":"activity","responsibility":"设计用户路径、信息结构及异常状态，准备可用于验证的原型。交付：交互结构与原型。"},{"id":"p3_work2","name":"视觉与组件规则","phase":"并行设计探索","kind":"activity","responsibility":"建立视觉层次、组件状态和统一样式，核对既有设计系统。交付：视觉规范与组件说明。"},{"id":"p3_review","name":"并行设计探索评审","phase":"并行设计探索","kind":"decision","responsibility":"核对方案取舍与关键体验覆盖并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p4_work1","name":"原型整合与任务脚本","phase":"原型与实施可行性","kind":"activity","responsibility":"整合方案，设计用户测试任务、观察点和记录方式。交付：测试原型与任务脚本。"},{"id":"p4_work2","name":"研发与无障碍检查","phase":"原型与实施可行性","kind":"activity","responsibility":"与研发核对实现成本、数据依赖、交互边界和无障碍可实现性。交付：实施约束与调整建议。"},{"id":"p4_review","name":"原型与实施可行性评审","phase":"原型与实施可行性","kind":"decision","responsibility":"核对可验证原型和实施约束并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p5_work1","name":"用户任务测试","phase":"体验验证","kind":"activity","responsibility":"观察关键任务完成、错误和理解偏差，收集与指标对应的证据。交付：可用性测试记录。"},{"id":"p5_work2","name":"结果归因与设计修订","phase":"体验验证","kind":"activity","responsibility":"核对假设是否成立，标注需要修改的路径、文案或组件。交付：验证结论与修订清单。"},{"id":"p5_review","name":"体验验证评审","phase":"体验验证","kind":"decision","responsibility":"核对任务表现与假设验证并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p6_work1","name":"设计资料与验收标准","phase":"设计交付与反馈","kind":"activity","responsibility":"整理组件、交互、资源和验收依据，明确设计接收责任。交付：设计交付包。"},{"id":"p6_work2","name":"实施反馈与体验复盘","phase":"设计交付与反馈","kind":"activity","responsibility":"跟进实现偏差和用户反馈，形成后续验证与体验改进事项。交付：体验复盘与改进事项。"},{"id":"p6_review","name":"设计交付与反馈评审","phase":"设计交付与反馈","kind":"decision","responsibility":"核对交付完整性与后续验证安排并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"exception_action","name":"验证失败与方案重构","phase":"异常处置与恢复","kind":"activity","responsibility":"记录未达标的任务、用户反馈和根因，重新检查问题定义及设计假设，提出改版范围。"},{"id":"exception_review","name":"恢复与重新准入","phase":"异常处置与恢复","kind":"decision","responsibility":"核对异常影响、处置证据与恢复状态，明确哪些工作需要重新评审；获得有权人确认后再进入正常推进路径。"}],"edges":[{"from":"p1_work1","to":"p1_review","kind":"sequence","label":""},{"from":"p1_work2","to":"p1_review","kind":"sequence","label":""},{"from":"p1_review","to":"p1_work1","kind":"feedback","label":"未通过：修订"},{"from":"p1_review","to":"p2_work1","kind":"sequence","label":"通过"},{"from":"p1_review","to":"p2_work2","kind":"sequence","label":"通过"},{"from":"p2_work1","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work2","to":"p2_review","kind":"sequence","label":""},{"from":"p2_review","to":"p2_work1","kind":"feedback","label":"未通过：修订"},{"from":"p2_review","to":"p3_work1","kind":"sequence","label":"通过"},{"from":"p2_review","to":"p3_work2","kind":"sequence","label":"通过"},{"from":"p3_work1","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work2","to":"p3_review","kind":"sequence","label":""},{"from":"p3_review","to":"p3_work1","kind":"feedback","label":"未通过：修订"},{"from":"p3_review","to":"p4_work1","kind":"sequence","label":"通过"},{"from":"p3_review","to":"p4_work2","kind":"sequence","label":"通过"},{"from":"p4_work1","to":"p4_review","kind":"sequence","label":""},{"from":"p4_work2","to":"p4_review","kind":"sequence","label":""},{"from":"p4_review","to":"p4_work1","kind":"feedback","label":"未通过：修订"},{"from":"p4_review","to":"p5_work1","kind":"sequence","label":"通过"},{"from":"p5_work1","to":"p5_work2","kind":"sequence","label":""},{"from":"p5_work2","to":"p5_review","kind":"sequence","label":""},{"from":"p5_review","to":"p5_work1","kind":"feedback","label":"未通过：修订"},{"from":"p5_review","to":"p6_work1","kind":"sequence","label":"通过"},{"from":"p5_review","to":"p6_work2","kind":"sequence","label":"通过"},{"from":"p6_work1","to":"p6_review","kind":"sequence","label":""},{"from":"p6_work2","to":"p6_review","kind":"sequence","label":""},{"from":"p6_review","to":"p6_work1","kind":"feedback","label":"未通过：修订"},{"from":"p5_review","to":"exception_action","kind":"sequence","label":"异常：专项处置"},{"from":"exception_action","to":"exception_review","kind":"sequence","label":""},{"from":"exception_review","to":"p2_work1","kind":"feedback","label":"确认后重新评审"}]}'::jsonb),
('product-design-advanced','d2d9d740fe8348c56a33639e98fcc0ff','{"nodes":[{"id":"p1_work1","name":"Research goals and recruitment","phase":"Discovery and research","kind":"activity","responsibility":"Define research questions, user groups, sample boundaries and interview arrangements. Deliver: research plan and sample rationale."},{"id":"p1_work2","name":"Interviews and observation","phase":"Discovery and research","kind":"activity","responsibility":"Collect usage, behavior and pain points and distinguish observations from interpretation. Deliver: source evidence and observation notes."},{"id":"p1_review","name":"Discovery and research review","phase":"Discovery and research","kind":"decision","responsibility":"Review research questions and traceable user evidence and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p2_work1","name":"Insights and opportunity synthesis","phase":"Problem definition","kind":"activity","responsibility":"Synthesize repeated problems, contradictions and opportunities with traceable evidence. Deliver: insight and opportunity map."},{"id":"p2_work2","name":"Scope and success metrics","phase":"Problem definition","kind":"activity","responsibility":"Translate problems into goals, scope, priorities and testable experience measures. Deliver: problem statement and success measures."},{"id":"p2_review","name":"Problem definition review","phase":"Problem definition","kind":"decision","responsibility":"Review user insights and success measures and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p3_work1","name":"Information structure and prototype","phase":"Parallel design exploration","kind":"activity","responsibility":"Design journeys, information structure and exceptional states in a testable prototype. Deliver: interaction structure and prototype."},{"id":"p3_work2","name":"Visual and component rules","phase":"Parallel design exploration","kind":"activity","responsibility":"Define hierarchy, component states and consistent styling against the existing design system. Deliver: visual standards and component notes."},{"id":"p3_review","name":"Parallel design exploration review","phase":"Parallel design exploration","kind":"decision","responsibility":"Review design tradeoffs and coverage of key experiences and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p4_work1","name":"Prototype integration and task scripts","phase":"Prototype and feasibility","kind":"activity","responsibility":"Integrate designs and prepare user-test tasks, observation points and recording methods. Deliver: test prototype and task script."},{"id":"p4_work2","name":"Engineering and accessibility checks","phase":"Prototype and feasibility","kind":"activity","responsibility":"Review implementation cost, data dependencies, interaction boundaries and accessibility feasibility with engineering. Deliver: implementation constraints and adjustments."},{"id":"p4_review","name":"Prototype and feasibility review","phase":"Prototype and feasibility","kind":"decision","responsibility":"Review testable prototypes and implementation constraints and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p5_work1","name":"User task testing","phase":"Experience validation","kind":"activity","responsibility":"Observe task completion, errors and comprehension and collect evidence against the measures. Deliver: usability testing record."},{"id":"p5_work2","name":"Findings and design revisions","phase":"Experience validation","kind":"activity","responsibility":"Assess assumptions and identify journeys, copy or components needing revision. Deliver: validation findings and revision list."},{"id":"p5_review","name":"Experience validation review","phase":"Experience validation","kind":"decision","responsibility":"Review task performance and validated assumptions and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p6_work1","name":"Design materials and acceptance criteria","phase":"Design handoff and feedback","kind":"activity","responsibility":"Package components, interactions, assets and acceptance evidence with handoff ownership. Deliver: design handoff package."},{"id":"p6_work2","name":"Implementation feedback and retrospective","phase":"Design handoff and feedback","kind":"activity","responsibility":"Track implementation deviations and user feedback and propose further experience checks. Deliver: experience retrospective and improvements."},{"id":"p6_review","name":"Design handoff and feedback review","phase":"Design handoff and feedback","kind":"decision","responsibility":"Review handoff completeness and further validation and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"exception_action","name":"Failed validation and redesign","phase":"Exceptions and recovery","kind":"activity","responsibility":"Record failed tasks, feedback and causes, revisit problem definitions and assumptions, and propose redesign scope."},{"id":"exception_review","name":"Recovery and readiness review","phase":"Exceptions and recovery","kind":"decision","responsibility":"Check impact, response evidence and recovery status. Identify reviews to repeat and obtain authorized confirmation before resuming."}],"edges":[{"from":"p1_work1","to":"p1_review","kind":"sequence","label":""},{"from":"p1_work2","to":"p1_review","kind":"sequence","label":""},{"from":"p1_review","to":"p1_work1","kind":"feedback","label":"Needs revision"},{"from":"p1_review","to":"p2_work1","kind":"sequence","label":"Accepted"},{"from":"p1_review","to":"p2_work2","kind":"sequence","label":"Accepted"},{"from":"p2_work1","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work2","to":"p2_review","kind":"sequence","label":""},{"from":"p2_review","to":"p2_work1","kind":"feedback","label":"Needs revision"},{"from":"p2_review","to":"p3_work1","kind":"sequence","label":"Accepted"},{"from":"p2_review","to":"p3_work2","kind":"sequence","label":"Accepted"},{"from":"p3_work1","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work2","to":"p3_review","kind":"sequence","label":""},{"from":"p3_review","to":"p3_work1","kind":"feedback","label":"Needs revision"},{"from":"p3_review","to":"p4_work1","kind":"sequence","label":"Accepted"},{"from":"p3_review","to":"p4_work2","kind":"sequence","label":"Accepted"},{"from":"p4_work1","to":"p4_review","kind":"sequence","label":""},{"from":"p4_work2","to":"p4_review","kind":"sequence","label":""},{"from":"p4_review","to":"p4_work1","kind":"feedback","label":"Needs revision"},{"from":"p4_review","to":"p5_work1","kind":"sequence","label":"Accepted"},{"from":"p5_work1","to":"p5_work2","kind":"sequence","label":""},{"from":"p5_work2","to":"p5_review","kind":"sequence","label":""},{"from":"p5_review","to":"p5_work1","kind":"feedback","label":"Needs revision"},{"from":"p5_review","to":"p6_work1","kind":"sequence","label":"Accepted"},{"from":"p5_review","to":"p6_work2","kind":"sequence","label":"Accepted"},{"from":"p6_work1","to":"p6_review","kind":"sequence","label":""},{"from":"p6_work2","to":"p6_review","kind":"sequence","label":""},{"from":"p6_review","to":"p6_work1","kind":"feedback","label":"Needs revision"},{"from":"p5_review","to":"exception_action","kind":"sequence","label":"Exception response"},{"from":"exception_action","to":"exception_review","kind":"sequence","label":""},{"from":"exception_review","to":"p2_work1","kind":"feedback","label":"Confirmed re-review"}]}'::jsonb),
('brand-production-advanced','db586dcecb02ab8fe362fc02a7febbe5','{"nodes":[{"id":"p1_work1","name":"品牌与受众研究","phase":"品牌定位","kind":"activity","responsibility":"整理品牌现状、受众反馈和竞争表达，确认核心沟通问题。交付：品牌研究与洞察。"},{"id":"p1_work2","name":"创意任务与约束","phase":"品牌定位","kind":"activity","responsibility":"确认用途、渠道、预算、交付规格和适用素材使用要求。交付：创意任务书。"},{"id":"p1_review","name":"品牌定位评审","phase":"品牌定位","kind":"decision","responsibility":"核对受众、定位与使用范围并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p2_work1","name":"创意路线与概念比较","phase":"创意与系统方案","kind":"activity","responsibility":"提出多种概念，说明各自与定位、受众和渠道的关系。交付：创意概念与取舍依据。"},{"id":"p2_work2","name":"视觉系统与应用规则","phase":"创意与系统方案","kind":"activity","responsibility":"定义标识、色彩、字体、构图和基础应用的统一关系。交付：视觉系统草案。"},{"id":"p2_review","name":"创意与系统方案评审","phase":"创意与系统方案","kind":"decision","responsibility":"核对创意方向与系统一致性并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p3_work1","name":"主视觉与图形资产","phase":"并行资产制作","kind":"activity","responsibility":"制作主视觉、图形与可编辑母版，登记素材与版本。交付：可编辑视觉母版。"},{"id":"p3_work2","name":"文案与渠道适配","phase":"并行资产制作","kind":"activity","responsibility":"完成文案与不同渠道版式，核对信息层次和内容一致性。交付：渠道文案与适配稿。"},{"id":"p3_review","name":"并行资产制作评审","phase":"并行资产制作","kind":"decision","responsibility":"核对母版、文案与媒介适配并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p4_work1","name":"品牌一致性核对","phase":"品牌与使用审核","kind":"activity","responsibility":"检查视觉、语气、组件使用和渠道表现是否符合已确认方向。交付：品牌核对与修改清单。"},{"id":"p4_work2","name":"内容与素材使用核对","phase":"品牌与使用审核","kind":"activity","responsibility":"核对信息准确性、素材来源和适用使用范围，登记未解决事项。交付：素材与内容核对记录。"},{"id":"p4_review","name":"品牌与使用审核评审","phase":"品牌与使用审核","kind":"decision","responsibility":"核对品牌一致性与素材可用性并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p5_work1","name":"打样与媒介验证","phase":"打样与制作验收","kind":"activity","responsibility":"在实际媒介或样品上核对色彩、尺寸、清晰度与显示效果。交付：打样与媒介检查。"},{"id":"p5_work2","name":"制作文件与规格复核","phase":"打样与制作验收","kind":"activity","responsibility":"检查导出、字体、分辨率、版本和供应商交付规格。交付：制作文件与规格确认。"},{"id":"p5_review","name":"打样与制作验收评审","phase":"打样与制作验收","kind":"decision","responsibility":"核对实物或媒介效果与规格并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p6_work1","name":"交付包与使用规范","phase":"交付与资产管理","kind":"activity","responsibility":"归档母版、导出稿和使用规范，明确修改与分发的责任人。交付：品牌交付与使用包。"},{"id":"p6_work2","name":"接收与应用反馈","phase":"交付与资产管理","kind":"activity","responsibility":"确认接收并观察实际应用，记录偏差和后续素材需求。交付：接收与应用反馈。"},{"id":"p6_review","name":"交付与资产管理评审","phase":"交付与资产管理","kind":"decision","responsibility":"核对接收、使用规范与资产版本并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"exception_action","name":"打样偏差与资产纠偏","phase":"异常处置与恢复","kind":"activity","responsibility":"定位色彩、尺寸、字体或授权问题，确认受影响素材，修正母版并重新核验。"},{"id":"exception_review","name":"恢复与重新准入","phase":"异常处置与恢复","kind":"decision","responsibility":"核对异常影响、处置证据与恢复状态，明确哪些工作需要重新评审；获得有权人确认后再进入正常推进路径。"}],"edges":[{"from":"p1_work1","to":"p1_review","kind":"sequence","label":""},{"from":"p1_work2","to":"p1_review","kind":"sequence","label":""},{"from":"p1_review","to":"p1_work1","kind":"feedback","label":"未通过：修订"},{"from":"p1_review","to":"p2_work1","kind":"sequence","label":"通过"},{"from":"p1_review","to":"p2_work2","kind":"sequence","label":"通过"},{"from":"p2_work1","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work2","to":"p2_review","kind":"sequence","label":""},{"from":"p2_review","to":"p2_work1","kind":"feedback","label":"未通过：修订"},{"from":"p2_review","to":"p3_work1","kind":"sequence","label":"通过"},{"from":"p2_review","to":"p3_work2","kind":"sequence","label":"通过"},{"from":"p3_work1","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work2","to":"p3_review","kind":"sequence","label":""},{"from":"p3_review","to":"p3_work1","kind":"feedback","label":"未通过：修订"},{"from":"p3_review","to":"p4_work1","kind":"sequence","label":"通过"},{"from":"p3_review","to":"p4_work2","kind":"sequence","label":"通过"},{"from":"p4_work1","to":"p4_review","kind":"sequence","label":""},{"from":"p4_work2","to":"p4_review","kind":"sequence","label":""},{"from":"p4_review","to":"p4_work1","kind":"feedback","label":"未通过：修订"},{"from":"p4_review","to":"p5_work1","kind":"sequence","label":"通过"},{"from":"p5_work1","to":"p5_work2","kind":"sequence","label":""},{"from":"p5_work2","to":"p5_review","kind":"sequence","label":""},{"from":"p5_review","to":"p5_work1","kind":"feedback","label":"未通过：修订"},{"from":"p5_review","to":"p6_work1","kind":"sequence","label":"通过"},{"from":"p5_review","to":"p6_work2","kind":"sequence","label":"通过"},{"from":"p6_work1","to":"p6_review","kind":"sequence","label":""},{"from":"p6_work2","to":"p6_review","kind":"sequence","label":""},{"from":"p6_review","to":"p6_work1","kind":"feedback","label":"未通过：修订"},{"from":"p5_review","to":"exception_action","kind":"sequence","label":"异常：专项处置"},{"from":"exception_action","to":"exception_review","kind":"sequence","label":""},{"from":"exception_review","to":"p3_work1","kind":"feedback","label":"确认后重新评审"}]}'::jsonb),
('brand-production-advanced','41f068c929fd8b29344e9c3bd79a24f8','{"nodes":[{"id":"p1_work1","name":"Brand and audience research","phase":"Brand positioning","kind":"activity","responsibility":"Review the brand, audience feedback and competing expressions to define communication problems. Deliver: brand research and insights."},{"id":"p1_work2","name":"Creative brief and constraints","phase":"Brand positioning","kind":"activity","responsibility":"Confirm purpose, channels, budget, delivery specifications and asset-use requirements. Deliver: creative brief."},{"id":"p1_review","name":"Brand positioning review","phase":"Brand positioning","kind":"decision","responsibility":"Review audience, positioning and usage scope and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p2_work1","name":"Creative routes and concept comparison","phase":"Creative and system design","kind":"activity","responsibility":"Develop alternatives and explain alignment with positioning, audience and channels. Deliver: creative concepts and tradeoffs."},{"id":"p2_work2","name":"Visual system and usage rules","phase":"Creative and system design","kind":"activity","responsibility":"Define consistent logo, color, typography, composition and basic applications. Deliver: visual system draft."},{"id":"p2_review","name":"Creative and system design review","phase":"Creative and system design","kind":"decision","responsibility":"Review creative direction and system consistency and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p3_work1","name":"Key visuals and graphics","phase":"Parallel asset production","kind":"activity","responsibility":"Produce key visuals, graphics and editable masters with source and version records. Deliver: editable visual masters."},{"id":"p3_work2","name":"Copy and channel adaptation","phase":"Parallel asset production","kind":"activity","responsibility":"Develop copy and channel layouts and check hierarchy and consistency. Deliver: channel copy and adaptations."},{"id":"p3_review","name":"Parallel asset production review","phase":"Parallel asset production","kind":"decision","responsibility":"Review master assets, copy and media adaptation and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p4_work1","name":"Brand consistency verification","phase":"Brand and usage review","kind":"activity","responsibility":"Check visuals, voice, component usage and channel presentation against approved direction. Deliver: brand checks and revision list."},{"id":"p4_work2","name":"Content and asset-use checks","phase":"Brand and usage review","kind":"activity","responsibility":"Verify content accuracy, asset sources and permitted usage and record unresolved issues. Deliver: asset and content verification."},{"id":"p4_review","name":"Brand and usage review review","phase":"Brand and usage review","kind":"decision","responsibility":"Review brand consistency and usable assets and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p5_work1","name":"Proofing and media verification","phase":"Proofing and production acceptance","kind":"activity","responsibility":"Verify color, size, clarity and rendering on actual media or proofs. Deliver: proofing and media checks."},{"id":"p5_work2","name":"Production file and specification review","phase":"Proofing and production acceptance","kind":"activity","responsibility":"Review exports, fonts, resolution, versions and supplier delivery requirements. Deliver: production files and confirmed specifications."},{"id":"p5_review","name":"Proofing and production acceptance review","phase":"Proofing and production acceptance","kind":"decision","responsibility":"Review physical or media results and specifications and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p6_work1","name":"Delivery package and usage guide","phase":"Delivery and asset management","kind":"activity","responsibility":"Archive masters, exports and usage guidance with revision and distribution ownership. Deliver: brand delivery and usage package."},{"id":"p6_work2","name":"Receipt and application feedback","phase":"Delivery and asset management","kind":"activity","responsibility":"Confirm receipt and observe applications to record deviations and future asset needs. Deliver: receipt and application feedback."},{"id":"p6_review","name":"Delivery and asset management review","phase":"Delivery and asset management","kind":"decision","responsibility":"Review receipt, usage guidance and asset versions and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"exception_action","name":"Proofing discrepancies and asset correction","phase":"Exceptions and recovery","kind":"activity","responsibility":"Identify color, size, typography or usage issues, correct master assets and repeat verification."},{"id":"exception_review","name":"Recovery and readiness review","phase":"Exceptions and recovery","kind":"decision","responsibility":"Check impact, response evidence and recovery status. Identify reviews to repeat and obtain authorized confirmation before resuming."}],"edges":[{"from":"p1_work1","to":"p1_review","kind":"sequence","label":""},{"from":"p1_work2","to":"p1_review","kind":"sequence","label":""},{"from":"p1_review","to":"p1_work1","kind":"feedback","label":"Needs revision"},{"from":"p1_review","to":"p2_work1","kind":"sequence","label":"Accepted"},{"from":"p1_review","to":"p2_work2","kind":"sequence","label":"Accepted"},{"from":"p2_work1","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work2","to":"p2_review","kind":"sequence","label":""},{"from":"p2_review","to":"p2_work1","kind":"feedback","label":"Needs revision"},{"from":"p2_review","to":"p3_work1","kind":"sequence","label":"Accepted"},{"from":"p2_review","to":"p3_work2","kind":"sequence","label":"Accepted"},{"from":"p3_work1","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work2","to":"p3_review","kind":"sequence","label":""},{"from":"p3_review","to":"p3_work1","kind":"feedback","label":"Needs revision"},{"from":"p3_review","to":"p4_work1","kind":"sequence","label":"Accepted"},{"from":"p3_review","to":"p4_work2","kind":"sequence","label":"Accepted"},{"from":"p4_work1","to":"p4_review","kind":"sequence","label":""},{"from":"p4_work2","to":"p4_review","kind":"sequence","label":""},{"from":"p4_review","to":"p4_work1","kind":"feedback","label":"Needs revision"},{"from":"p4_review","to":"p5_work1","kind":"sequence","label":"Accepted"},{"from":"p5_work1","to":"p5_work2","kind":"sequence","label":""},{"from":"p5_work2","to":"p5_review","kind":"sequence","label":""},{"from":"p5_review","to":"p5_work1","kind":"feedback","label":"Needs revision"},{"from":"p5_review","to":"p6_work1","kind":"sequence","label":"Accepted"},{"from":"p5_review","to":"p6_work2","kind":"sequence","label":"Accepted"},{"from":"p6_work1","to":"p6_review","kind":"sequence","label":""},{"from":"p6_work2","to":"p6_review","kind":"sequence","label":""},{"from":"p6_review","to":"p6_work1","kind":"feedback","label":"Needs revision"},{"from":"p5_review","to":"exception_action","kind":"sequence","label":"Exception response"},{"from":"exception_action","to":"exception_review","kind":"sequence","label":""},{"from":"exception_review","to":"p3_work1","kind":"feedback","label":"Confirmed re-review"}]}'::jsonb),
('editorial-publishing-advanced','0aeb88e5b35a5274efe0ac0bb11a5777','{"nodes":[{"id":"p1_work1","name":"读者与选题定位","phase":"选题与制作计划","kind":"activity","responsibility":"明确读者、主题、篇幅和内容价值，检查与既有内容的关系。交付：选题说明与内容目标。"},{"id":"p1_work2","name":"制作节奏与稿件规范","phase":"选题与制作计划","kind":"activity","responsibility":"约定稿件结构、交稿、审阅、素材和出版格式要求。交付：制作计划与稿件规范。"},{"id":"p1_review","name":"选题与制作计划评审","phase":"选题与制作计划","kind":"decision","responsibility":"核对读者目标、选题与制作条件并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p2_work1","name":"资料核对与素材准备","phase":"资料与内容建设","kind":"activity","responsibility":"核对引用与素材来源，记录缺口、适用使用范围和事实依据。交付：引用与素材登记。"},{"id":"p2_work2","name":"结构设计与初稿写作","phase":"资料与内容建设","kind":"activity","responsibility":"依据内容目标建立结构与论述，标出待核实内容和缺失材料。交付：可审阅初稿。"},{"id":"p2_review","name":"资料与内容建设评审","phase":"资料与内容建设","kind":"decision","responsibility":"核对可追溯资料与完整初稿并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p3_work1","name":"结构与语言编辑","phase":"编辑与事实复核","kind":"activity","responsibility":"编辑核对论述、可读性与风格，记录修改依据与作者确认事项。交付：编辑稿与修改记录。"},{"id":"p3_work2","name":"事实与引用复核","phase":"编辑与事实复核","kind":"activity","responsibility":"独立复核关键事实、引用、表格与图注，标注需作者说明的问题。交付：事实复核与问题清单。"},{"id":"p3_review","name":"编辑与事实复核评审","phase":"编辑与事实复核","kind":"decision","responsibility":"核对结构、表达与事实准确性并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p4_work1","name":"排版与版式制作","phase":"制作与排版","kind":"activity","responsibility":"按确认样式排版，核对标题、注释、目录、图表和跨页关系。交付：版式样稿。"},{"id":"p4_work2","name":"封面与发布素材","phase":"制作与排版","kind":"activity","responsibility":"制作封面、简介与发行素材，核对内容定位和稿件版本。交付：封面与发布素材。"},{"id":"p4_review","name":"制作与排版评审","phase":"制作与排版","kind":"decision","responsibility":"核对文稿、视觉与格式一致性并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p5_work1","name":"作者与校对审阅","phase":"校对与出版准入","kind":"activity","responsibility":"作者和校对人员检查排版后的文字、图表与更正，区分必要改动和范围扩张。交付：校对意见与作者确认。"},{"id":"p5_work2","name":"更正汇总与成品核验","phase":"校对与出版准入","kind":"activity","responsibility":"核对所有更正是否落实，验证出版文件、链接和发行版本。交付：最终成品与核验记录。"},{"id":"p5_review","name":"校对与出版准入评审","phase":"校对与出版准入","kind":"decision","responsibility":"核对最终样稿、修订闭合与版本并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p6_work1","name":"发布与成果归档","phase":"发布与更正维护","kind":"activity","responsibility":"成员完成确认的发布，归档最终稿、制作文件和实际发布依据。交付：发布与成果归档。"},{"id":"p6_work2","name":"反馈与更正登记","phase":"发布与更正维护","kind":"activity","responsibility":"收集读者和使用反馈，登记更正、版本变化及后续修订建议。交付：反馈与更正记录。"},{"id":"p6_review","name":"发布与更正维护评审","phase":"发布与更正维护","kind":"decision","responsibility":"核对实际发布、归档与后续更正并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"exception_action","name":"重大差错与内容更正","phase":"异常处置与恢复","kind":"activity","responsibility":"确认差错及影响版本，冻结受影响稿件，按项目安排修订、更正与再次校对。"},{"id":"exception_review","name":"恢复与重新准入","phase":"异常处置与恢复","kind":"decision","responsibility":"核对异常影响、处置证据与恢复状态，明确哪些工作需要重新评审；获得有权人确认后再进入正常推进路径。"}],"edges":[{"from":"p1_work1","to":"p1_review","kind":"sequence","label":""},{"from":"p1_work2","to":"p1_review","kind":"sequence","label":""},{"from":"p1_review","to":"p1_work1","kind":"feedback","label":"未通过：修订"},{"from":"p1_review","to":"p2_work1","kind":"sequence","label":"通过"},{"from":"p1_review","to":"p2_work2","kind":"sequence","label":"通过"},{"from":"p2_work1","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work2","to":"p2_review","kind":"sequence","label":""},{"from":"p2_review","to":"p2_work1","kind":"feedback","label":"未通过：修订"},{"from":"p2_review","to":"p3_work1","kind":"sequence","label":"通过"},{"from":"p2_review","to":"p3_work2","kind":"sequence","label":"通过"},{"from":"p3_work1","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work2","to":"p3_review","kind":"sequence","label":""},{"from":"p3_review","to":"p3_work1","kind":"feedback","label":"未通过：修订"},{"from":"p3_review","to":"p4_work1","kind":"sequence","label":"通过"},{"from":"p3_review","to":"p4_work2","kind":"sequence","label":"通过"},{"from":"p4_work1","to":"p4_review","kind":"sequence","label":""},{"from":"p4_work2","to":"p4_review","kind":"sequence","label":""},{"from":"p4_review","to":"p4_work1","kind":"feedback","label":"未通过：修订"},{"from":"p4_review","to":"p5_work1","kind":"sequence","label":"通过"},{"from":"p5_work1","to":"p5_work2","kind":"sequence","label":""},{"from":"p5_work2","to":"p5_review","kind":"sequence","label":""},{"from":"p5_review","to":"p5_work1","kind":"feedback","label":"未通过：修订"},{"from":"p5_review","to":"p6_work1","kind":"sequence","label":"通过"},{"from":"p5_review","to":"p6_work2","kind":"sequence","label":"通过"},{"from":"p6_work1","to":"p6_review","kind":"sequence","label":""},{"from":"p6_work2","to":"p6_review","kind":"sequence","label":""},{"from":"p6_review","to":"p6_work1","kind":"feedback","label":"未通过：修订"},{"from":"p5_review","to":"exception_action","kind":"sequence","label":"异常：专项处置"},{"from":"exception_action","to":"exception_review","kind":"sequence","label":""},{"from":"exception_review","to":"p3_work1","kind":"feedback","label":"确认后重新评审"}]}'::jsonb),
('editorial-publishing-advanced','9a4814a54a81b579d2eed6c6c1480307','{"nodes":[{"id":"p1_work1","name":"Reader and topic positioning","phase":"Commissioning and production planning","kind":"activity","responsibility":"Define readers, topic, length and value and review related existing content. Deliver: commissioning brief and content goals."},{"id":"p1_work2","name":"Schedule and manuscript requirements","phase":"Commissioning and production planning","kind":"activity","responsibility":"Agree manuscript structure, handoff, reviews, assets and publication formats. Deliver: production plan and manuscript requirements."},{"id":"p1_review","name":"Commissioning and production planning review","phase":"Commissioning and production planning","kind":"decision","responsibility":"Review reader goals, topic and production conditions and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p2_work1","name":"Source verification and asset preparation","phase":"Sources and content development","kind":"activity","responsibility":"Verify sources and assets and record gaps, usage boundaries and evidence. Deliver: source and asset register."},{"id":"p2_work2","name":"Structure and first draft","phase":"Sources and content development","kind":"activity","responsibility":"Build structure and argument against the content goals and flag uncertain statements or missing material. Deliver: reviewable first draft."},{"id":"p2_review","name":"Sources and content development review","phase":"Sources and content development","kind":"decision","responsibility":"Review traceable sources and a complete draft and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p3_work1","name":"Structural and language editing","phase":"Editing and fact review","kind":"activity","responsibility":"Editors review argument, readability and style and record revision reasons and author queries. Deliver: edited draft and revision record."},{"id":"p3_work2","name":"Fact and citation verification","phase":"Editing and fact review","kind":"activity","responsibility":"Independently verify key facts, citations, tables and captions and flag author queries. Deliver: fact review and query list."},{"id":"p3_review","name":"Editing and fact review review","phase":"Editing and fact review","kind":"decision","responsibility":"Review structure, expression and factual accuracy and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p4_work1","name":"Typesetting and layout production","phase":"Production and layout","kind":"activity","responsibility":"Typeset against approved styles and check headings, notes, contents, figures and pagination. Deliver: layout proof."},{"id":"p4_work2","name":"Cover and publication assets","phase":"Production and layout","kind":"activity","responsibility":"Prepare cover, description and publication assets and check alignment with content and version. Deliver: cover and publication assets."},{"id":"p4_review","name":"Production and layout review","phase":"Production and layout","kind":"decision","responsibility":"Review text, visuals and formatting consistency and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p5_work1","name":"Author and proofreader review","phase":"Proofing and publication readiness","kind":"activity","responsibility":"Authors and proofreaders inspect text, figures and corrections and distinguish necessary edits from scope expansion. Deliver: proofreading findings and author confirmation."},{"id":"p5_work2","name":"Corrections and final-file verification","phase":"Proofing and publication readiness","kind":"activity","responsibility":"Confirm corrections are applied and verify publication files, links and release versions. Deliver: final files and verification evidence."},{"id":"p5_review","name":"Proofing and publication readiness review","phase":"Proofing and publication readiness","kind":"decision","responsibility":"Review final proofs, closed revisions and versions and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p6_work1","name":"Publication and archive","phase":"Publication and correction maintenance","kind":"activity","responsibility":"Members complete approved publication and archive final manuscripts, production files and release evidence. Deliver: publication and result archive."},{"id":"p6_work2","name":"Feedback and correction register","phase":"Publication and correction maintenance","kind":"activity","responsibility":"Collect reader and usage feedback and record corrections, version changes and future revisions. Deliver: feedback and correction record."},{"id":"p6_review","name":"Publication and correction maintenance review","phase":"Publication and correction maintenance","kind":"decision","responsibility":"Review actual release, archives and subsequent corrections and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"exception_action","name":"Material errors and content correction","phase":"Exceptions and recovery","kind":"activity","responsibility":"Confirm errors and affected versions, hold the material and perform approved correction and re-proofing."},{"id":"exception_review","name":"Recovery and readiness review","phase":"Exceptions and recovery","kind":"decision","responsibility":"Check impact, response evidence and recovery status. Identify reviews to repeat and obtain authorized confirmation before resuming."}],"edges":[{"from":"p1_work1","to":"p1_review","kind":"sequence","label":""},{"from":"p1_work2","to":"p1_review","kind":"sequence","label":""},{"from":"p1_review","to":"p1_work1","kind":"feedback","label":"Needs revision"},{"from":"p1_review","to":"p2_work1","kind":"sequence","label":"Accepted"},{"from":"p1_review","to":"p2_work2","kind":"sequence","label":"Accepted"},{"from":"p2_work1","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work2","to":"p2_review","kind":"sequence","label":""},{"from":"p2_review","to":"p2_work1","kind":"feedback","label":"Needs revision"},{"from":"p2_review","to":"p3_work1","kind":"sequence","label":"Accepted"},{"from":"p2_review","to":"p3_work2","kind":"sequence","label":"Accepted"},{"from":"p3_work1","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work2","to":"p3_review","kind":"sequence","label":""},{"from":"p3_review","to":"p3_work1","kind":"feedback","label":"Needs revision"},{"from":"p3_review","to":"p4_work1","kind":"sequence","label":"Accepted"},{"from":"p3_review","to":"p4_work2","kind":"sequence","label":"Accepted"},{"from":"p4_work1","to":"p4_review","kind":"sequence","label":""},{"from":"p4_work2","to":"p4_review","kind":"sequence","label":""},{"from":"p4_review","to":"p4_work1","kind":"feedback","label":"Needs revision"},{"from":"p4_review","to":"p5_work1","kind":"sequence","label":"Accepted"},{"from":"p5_work1","to":"p5_work2","kind":"sequence","label":""},{"from":"p5_work2","to":"p5_review","kind":"sequence","label":""},{"from":"p5_review","to":"p5_work1","kind":"feedback","label":"Needs revision"},{"from":"p5_review","to":"p6_work1","kind":"sequence","label":"Accepted"},{"from":"p5_review","to":"p6_work2","kind":"sequence","label":"Accepted"},{"from":"p6_work1","to":"p6_review","kind":"sequence","label":""},{"from":"p6_work2","to":"p6_review","kind":"sequence","label":""},{"from":"p6_review","to":"p6_work1","kind":"feedback","label":"Needs revision"},{"from":"p5_review","to":"exception_action","kind":"sequence","label":"Exception response"},{"from":"exception_action","to":"exception_review","kind":"sequence","label":""},{"from":"exception_review","to":"p3_work1","kind":"feedback","label":"Confirmed re-review"}]}'::jsonb),
('content-campaign-advanced','0785a8fcf9bf320bf7e2ce67b226a7d9','{"nodes":[{"id":"p1_work1","name":"主题与受众定义","phase":"主题与渠道","kind":"activity","responsibility":"明确受众、关键信息和期望行动，记录需要验证的表达假设。交付：主题与受众任务书。"},{"id":"p1_work2","name":"渠道与规格盘点","phase":"主题与渠道","kind":"activity","responsibility":"确认渠道、格式、尺寸、发布时间和渠道之间的内容关系。交付：渠道与规格清单。"},{"id":"p1_review","name":"主题与渠道评审","phase":"主题与渠道","kind":"decision","responsibility":"核对传播目标与内容约束并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p2_work1","name":"事实与素材核对","phase":"素材与结构","kind":"activity","responsibility":"整理事实、引用、图片与素材使用依据，列出缺口和需确认内容。交付：内容与素材登记。"},{"id":"p2_work2","name":"叙事与系列结构","phase":"素材与结构","kind":"activity","responsibility":"设计内容结构、系列关系和信息层次，避免渠道间信息矛盾。交付：内容结构与系列计划。"},{"id":"p2_review","name":"素材与结构评审","phase":"素材与结构","kind":"decision","responsibility":"核对事实依据与叙事结构并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p3_work1","name":"文案与渠道变体","phase":"并行图文生产","kind":"activity","responsibility":"创作文案和渠道变体，标记共同事实、渠道差异和需要配图的位置。交付：文案与渠道变体。"},{"id":"p3_work2","name":"视觉与素材制作","phase":"并行图文生产","kind":"activity","responsibility":"按叙事需要制作图形、图片与模板，登记与文案版本的关联。交付：视觉稿与版本对应。"},{"id":"p3_review","name":"并行图文生产评审","phase":"并行图文生产","kind":"decision","responsibility":"核对文案、视觉与版本关联并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p4_work1","name":"编辑与事实审阅","phase":"联合审核","kind":"activity","responsibility":"核对核心信息、数据、引用和文案语气，确认需更正的内容。交付：编辑审阅与更正清单。"},{"id":"p4_work2","name":"品牌与视觉审阅","phase":"联合审核","kind":"activity","responsibility":"核对视觉规范、图文关系和渠道风格，记录审阅反馈与取舍。交付：联合图文审阅记录。"},{"id":"p4_review","name":"联合审核评审","phase":"联合审核","kind":"decision","responsibility":"核对图文一致性与表达准确性并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p5_work1","name":"渠道预览与链接校验","phase":"渠道验证与发布","kind":"activity","responsibility":"在目标渠道预览文字、图像、链接和交互，核对版本与适配。交付：渠道预览与核验。"},{"id":"p5_work2","name":"发布安排与实际执行","phase":"渠道验证与发布","kind":"activity","responsibility":"确认发布节奏和责任人，由成员完成发布并登记实际渠道和版本。交付：实际发布清单。"},{"id":"p5_review","name":"渠道验证与发布评审","phase":"渠道验证与发布","kind":"decision","responsibility":"核对渠道实测、最终稿与发布记录并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p6_work1","name":"效果与反馈整理","phase":"效果与内容维护","kind":"activity","responsibility":"按目标收集访问、互动与受众反馈，说明指标来源和解释范围。交付：内容效果与反馈报告。"},{"id":"p6_work2","name":"资产与修订维护","phase":"效果与内容维护","kind":"activity","responsibility":"归档可复用素材、稿件和更正，整理后续选题与修订建议。交付：内容资产与维护记录。"},{"id":"p6_review","name":"效果与内容维护评审","phase":"效果与内容维护","kind":"decision","responsibility":"核对反馈、效果与版本维护并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"exception_action","name":"跨渠道差错与撤回修订","phase":"异常处置与恢复","kind":"activity","responsibility":"核对受影响内容与渠道，由成员按确认方案更正或撤回，保持稿件和发布版本可追溯。"},{"id":"exception_review","name":"恢复与重新准入","phase":"异常处置与恢复","kind":"decision","responsibility":"核对异常影响、处置证据与恢复状态，明确哪些工作需要重新评审；获得有权人确认后再进入正常推进路径。"}],"edges":[{"from":"p1_work1","to":"p1_review","kind":"sequence","label":""},{"from":"p1_work2","to":"p1_review","kind":"sequence","label":""},{"from":"p1_review","to":"p1_work1","kind":"feedback","label":"未通过：修订"},{"from":"p1_review","to":"p2_work1","kind":"sequence","label":"通过"},{"from":"p1_review","to":"p2_work2","kind":"sequence","label":"通过"},{"from":"p2_work1","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work2","to":"p2_review","kind":"sequence","label":""},{"from":"p2_review","to":"p2_work1","kind":"feedback","label":"未通过：修订"},{"from":"p2_review","to":"p3_work1","kind":"sequence","label":"通过"},{"from":"p2_review","to":"p3_work2","kind":"sequence","label":"通过"},{"from":"p3_work1","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work2","to":"p3_review","kind":"sequence","label":""},{"from":"p3_review","to":"p3_work1","kind":"feedback","label":"未通过：修订"},{"from":"p3_review","to":"p4_work1","kind":"sequence","label":"通过"},{"from":"p3_review","to":"p4_work2","kind":"sequence","label":"通过"},{"from":"p4_work1","to":"p4_review","kind":"sequence","label":""},{"from":"p4_work2","to":"p4_review","kind":"sequence","label":""},{"from":"p4_review","to":"p4_work1","kind":"feedback","label":"未通过：修订"},{"from":"p4_review","to":"p5_work1","kind":"sequence","label":"通过"},{"from":"p5_work1","to":"p5_work2","kind":"sequence","label":""},{"from":"p5_work2","to":"p5_review","kind":"sequence","label":""},{"from":"p5_review","to":"p5_work1","kind":"feedback","label":"未通过：修订"},{"from":"p5_review","to":"p6_work1","kind":"sequence","label":"通过"},{"from":"p5_review","to":"p6_work2","kind":"sequence","label":"通过"},{"from":"p6_work1","to":"p6_review","kind":"sequence","label":""},{"from":"p6_work2","to":"p6_review","kind":"sequence","label":""},{"from":"p6_review","to":"p6_work1","kind":"feedback","label":"未通过：修订"},{"from":"p5_review","to":"exception_action","kind":"sequence","label":"异常：专项处置"},{"from":"exception_action","to":"exception_review","kind":"sequence","label":""},{"from":"exception_review","to":"p3_work1","kind":"feedback","label":"确认后重新评审"}]}'::jsonb),
('content-campaign-advanced','9484693e17770f2c88024b728b616ead','{"nodes":[{"id":"p1_work1","name":"Theme and audience definition","phase":"Theme and channels","kind":"activity","responsibility":"Define audiences, key messages and desired actions and record communication assumptions. Deliver: theme and audience brief."},{"id":"p1_work2","name":"Channel and specification inventory","phase":"Theme and channels","kind":"activity","responsibility":"Confirm channels, formats, sizes, timing and relationships between content versions. Deliver: channel and specification list."},{"id":"p1_review","name":"Theme and channels review","phase":"Theme and channels","kind":"decision","responsibility":"Review communication goals and content constraints and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p2_work1","name":"Fact and asset verification","phase":"Sources and structure","kind":"activity","responsibility":"Collect facts, citations, images and usage evidence and flag gaps and queries. Deliver: content and asset register."},{"id":"p2_work2","name":"Narrative and series structure","phase":"Sources and structure","kind":"activity","responsibility":"Design structure, series relationships and hierarchy and prevent conflicting channel messages. Deliver: content structure and series plan."},{"id":"p2_review","name":"Sources and structure review","phase":"Sources and structure","kind":"decision","responsibility":"Review factual evidence and narrative structure and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p3_work1","name":"Copy and channel variants","phase":"Parallel text and visual production","kind":"activity","responsibility":"Create copy and channel variants and mark shared facts, channel differences and visual requirements. Deliver: copy and channel variants."},{"id":"p3_work2","name":"Visual and asset production","phase":"Parallel text and visual production","kind":"activity","responsibility":"Create visuals and templates for the narrative and track their relationship to copy versions. Deliver: visual drafts and version mapping."},{"id":"p3_review","name":"Parallel text and visual production review","phase":"Parallel text and visual production","kind":"decision","responsibility":"Review copy, visuals and linked versions and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p4_work1","name":"Editorial and fact review","phase":"Joint review","kind":"activity","responsibility":"Review key messages, data, citations and tone and identify required corrections. Deliver: editorial review and correction list."},{"id":"p4_work2","name":"Brand and visual review","phase":"Joint review","kind":"activity","responsibility":"Review visual standards, text-visual relationships and channel style and record feedback and choices. Deliver: joint text and visual review."},{"id":"p4_review","name":"Joint review review","phase":"Joint review","kind":"decision","responsibility":"Review text-visual consistency and accuracy and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p5_work1","name":"Channel previews and link checks","phase":"Channel checks and publication","kind":"activity","responsibility":"Preview text, images, links and interactions on target channels and check versions and adaptation. Deliver: channel previews and verification."},{"id":"p5_work2","name":"Publication plan and execution","phase":"Channel checks and publication","kind":"activity","responsibility":"Confirm publication timing and ownership, then publish and record actual channels and versions. Deliver: actual publication list."},{"id":"p5_review","name":"Channel checks and publication review","phase":"Channel checks and publication","kind":"decision","responsibility":"Review channel checks, final content and release evidence and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p6_work1","name":"Results and feedback synthesis","phase":"Results and content maintenance","kind":"activity","responsibility":"Collect reach, engagement and audience feedback against goals and explain measurement limits. Deliver: content results and feedback report."},{"id":"p6_work2","name":"Asset and revision maintenance","phase":"Results and content maintenance","kind":"activity","responsibility":"Archive reusable assets, content and corrections and propose future topics and revisions. Deliver: content assets and maintenance record."},{"id":"p6_review","name":"Results and content maintenance review","phase":"Results and content maintenance","kind":"decision","responsibility":"Review feedback, results and version maintenance and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"exception_action","name":"Cross-channel errors and corrective revision","phase":"Exceptions and recovery","kind":"activity","responsibility":"Identify affected content and channels and apply approved correction or withdrawal with traceable versions."},{"id":"exception_review","name":"Recovery and readiness review","phase":"Exceptions and recovery","kind":"decision","responsibility":"Check impact, response evidence and recovery status. Identify reviews to repeat and obtain authorized confirmation before resuming."}],"edges":[{"from":"p1_work1","to":"p1_review","kind":"sequence","label":""},{"from":"p1_work2","to":"p1_review","kind":"sequence","label":""},{"from":"p1_review","to":"p1_work1","kind":"feedback","label":"Needs revision"},{"from":"p1_review","to":"p2_work1","kind":"sequence","label":"Accepted"},{"from":"p1_review","to":"p2_work2","kind":"sequence","label":"Accepted"},{"from":"p2_work1","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work2","to":"p2_review","kind":"sequence","label":""},{"from":"p2_review","to":"p2_work1","kind":"feedback","label":"Needs revision"},{"from":"p2_review","to":"p3_work1","kind":"sequence","label":"Accepted"},{"from":"p2_review","to":"p3_work2","kind":"sequence","label":"Accepted"},{"from":"p3_work1","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work2","to":"p3_review","kind":"sequence","label":""},{"from":"p3_review","to":"p3_work1","kind":"feedback","label":"Needs revision"},{"from":"p3_review","to":"p4_work1","kind":"sequence","label":"Accepted"},{"from":"p3_review","to":"p4_work2","kind":"sequence","label":"Accepted"},{"from":"p4_work1","to":"p4_review","kind":"sequence","label":""},{"from":"p4_work2","to":"p4_review","kind":"sequence","label":""},{"from":"p4_review","to":"p4_work1","kind":"feedback","label":"Needs revision"},{"from":"p4_review","to":"p5_work1","kind":"sequence","label":"Accepted"},{"from":"p5_work1","to":"p5_work2","kind":"sequence","label":""},{"from":"p5_work2","to":"p5_review","kind":"sequence","label":""},{"from":"p5_review","to":"p5_work1","kind":"feedback","label":"Needs revision"},{"from":"p5_review","to":"p6_work1","kind":"sequence","label":"Accepted"},{"from":"p5_review","to":"p6_work2","kind":"sequence","label":"Accepted"},{"from":"p6_work1","to":"p6_review","kind":"sequence","label":""},{"from":"p6_work2","to":"p6_review","kind":"sequence","label":""},{"from":"p6_review","to":"p6_work1","kind":"feedback","label":"Needs revision"},{"from":"p5_review","to":"exception_action","kind":"sequence","label":"Exception response"},{"from":"exception_action","to":"exception_review","kind":"sequence","label":""},{"from":"exception_review","to":"p3_work1","kind":"feedback","label":"Confirmed re-review"}]}'::jsonb),
('video-production-advanced','1db54e7ada5a7469c2049ece51d2dac6','{"nodes":[{"id":"p1_work1","name":"剧本与叙事设计","phase":"创意与制作范围","kind":"activity","responsibility":"明确主题、叙事、脚本和镜头需求，检查与受众及交付目标的关系。交付：脚本与镜头需求。"},{"id":"p1_work2","name":"预算与制作安排","phase":"创意与制作范围","kind":"activity","responsibility":"核对预算、人员、地点、设备、排期和成片规格。交付：制作计划与预算。"},{"id":"p1_review","name":"创意与制作范围评审","phase":"创意与制作范围","kind":"decision","responsibility":"核对创意、预算与交付规格并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p2_work1","name":"分镜与拍摄计划","phase":"拍摄准备","kind":"activity","responsibility":"把脚本拆为场景、镜头、现场顺序和必要素材，登记替代方案。交付：分镜与拍摄计划。"},{"id":"p2_work2","name":"人员场地与设备确认","phase":"拍摄准备","kind":"activity","responsibility":"核对人员、场地、设备测试、素材使用安排和现场应急职责。交付：拍摄就绪检查。"},{"id":"p2_review","name":"拍摄准备评审","phase":"拍摄准备","kind":"decision","responsibility":"核对分镜、现场与录制条件并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p3_work1","name":"拍摄与现场记录","phase":"现场制作与素材管理","kind":"activity","responsibility":"完成镜头与音频采集，记录场次、版本、现场偏差和可用性。交付：现场素材与场记。"},{"id":"p3_work2","name":"素材核对与备份","phase":"现场制作与素材管理","kind":"activity","responsibility":"核对素材命名、数量、完整性和备份，登记无法补拍或缺失的问题。交付：素材清单与备份证据。"},{"id":"p3_review","name":"现场制作与素材管理评审","phase":"现场制作与素材管理","kind":"decision","responsibility":"核对现场成果、素材完整性与备份并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p4_work1","name":"粗剪与叙事核对","phase":"剪辑与叙事确认","kind":"activity","responsibility":"按主题与脚本整理粗剪，核对节奏、信息和缺失镜头。交付：粗剪与修改记录。"},{"id":"p4_work2","name":"精剪与画面锁定","phase":"剪辑与叙事确认","kind":"activity","responsibility":"落实审阅修改，记录进入后期的画面版本和未解决事项。交付：锁定画面与后期交接。"},{"id":"p4_review","name":"剪辑与叙事确认评审","phase":"剪辑与叙事确认","kind":"decision","responsibility":"核对剪辑结构与画面锁定依据并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p5_work1","name":"调色与视觉后期","phase":"并行后期制作","kind":"activity","responsibility":"完成调色、图形和视觉修整，核对与锁定画面的版本关系。交付：视觉后期成果。"},{"id":"p5_work2","name":"声音字幕与信息","phase":"并行后期制作","kind":"activity","responsibility":"完成混音、字幕和片尾信息，核对时序、语言与素材使用记录。交付：声音与文字后期成果。"},{"id":"p5_review","name":"并行后期制作评审","phase":"并行后期制作","kind":"decision","responsibility":"核对画面、声音与文字一致性并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p6_work1","name":"创意与客户审阅","phase":"成片审阅与质检","kind":"activity","responsibility":"对照制作目标审阅成片，集中记录意见、确认人与修改范围。交付：成片审阅与确认。"},{"id":"p6_work2","name":"技术质检与格式导出","phase":"成片审阅与质检","kind":"activity","responsibility":"检查画音同步、字幕、色彩、响度与格式，核对交付版本。交付：技术质检与导出文件。"},{"id":"p6_review","name":"成片审阅与质检评审","phase":"成片审阅与质检","kind":"decision","responsibility":"核对成片内容、技术规格与可交付性并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p7_work1","name":"成片交付与接收","phase":"交付与素材归档","kind":"activity","responsibility":"交付批准成片、格式和使用说明，记录实际接收与遗漏事项。交付：成片交付与接收记录。"},{"id":"p7_work2","name":"项目素材与复盘","phase":"交付与素材归档","kind":"activity","responsibility":"归档工程、素材、版本和使用记录，复盘制作与后期协作问题。交付：素材归档与制作复盘。"},{"id":"p7_review","name":"交付与素材归档评审","phase":"交付与素材归档","kind":"decision","responsibility":"核对客户接收与可追溯素材并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"exception_action","name":"补拍与素材恢复","phase":"异常处置与恢复","kind":"activity","responsibility":"确认缺失或不合格镜头、音频及影响范围，按确认计划补拍、恢复或替换素材。"},{"id":"exception_review","name":"恢复与重新准入","phase":"异常处置与恢复","kind":"decision","responsibility":"核对异常影响、处置证据与恢复状态，明确哪些工作需要重新评审；获得有权人确认后再进入正常推进路径。"}],"edges":[{"from":"p1_work1","to":"p1_review","kind":"sequence","label":""},{"from":"p1_work2","to":"p1_review","kind":"sequence","label":""},{"from":"p1_review","to":"p1_work1","kind":"feedback","label":"未通过：修订"},{"from":"p1_review","to":"p2_work1","kind":"sequence","label":"通过"},{"from":"p1_review","to":"p2_work2","kind":"sequence","label":"通过"},{"from":"p2_work1","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work2","to":"p2_review","kind":"sequence","label":""},{"from":"p2_review","to":"p2_work1","kind":"feedback","label":"未通过：修订"},{"from":"p2_review","to":"p3_work1","kind":"sequence","label":"通过"},{"from":"p2_review","to":"p3_work2","kind":"sequence","label":"通过"},{"from":"p3_work1","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work2","to":"p3_review","kind":"sequence","label":""},{"from":"p3_review","to":"p3_work1","kind":"feedback","label":"未通过：修订"},{"from":"p3_review","to":"p4_work1","kind":"sequence","label":"通过"},{"from":"p4_work1","to":"p4_work2","kind":"sequence","label":""},{"from":"p4_work2","to":"p4_review","kind":"sequence","label":""},{"from":"p4_review","to":"p4_work1","kind":"feedback","label":"未通过：修订"},{"from":"p4_review","to":"p5_work1","kind":"sequence","label":"通过"},{"from":"p4_review","to":"p5_work2","kind":"sequence","label":"通过"},{"from":"p5_work1","to":"p5_review","kind":"sequence","label":""},{"from":"p5_work2","to":"p5_review","kind":"sequence","label":""},{"from":"p5_review","to":"p5_work1","kind":"feedback","label":"未通过：修订"},{"from":"p5_review","to":"p6_work1","kind":"sequence","label":"通过"},{"from":"p5_review","to":"p6_work2","kind":"sequence","label":"通过"},{"from":"p6_work1","to":"p6_review","kind":"sequence","label":""},{"from":"p6_work2","to":"p6_review","kind":"sequence","label":""},{"from":"p6_review","to":"p6_work1","kind":"feedback","label":"未通过：修订"},{"from":"p6_review","to":"p7_work1","kind":"sequence","label":"通过"},{"from":"p6_review","to":"p7_work2","kind":"sequence","label":"通过"},{"from":"p7_work1","to":"p7_review","kind":"sequence","label":""},{"from":"p7_work2","to":"p7_review","kind":"sequence","label":""},{"from":"p7_review","to":"p7_work1","kind":"feedback","label":"未通过：修订"},{"from":"p6_review","to":"exception_action","kind":"sequence","label":"异常：专项处置"},{"from":"exception_action","to":"exception_review","kind":"sequence","label":""},{"from":"exception_review","to":"p3_work1","kind":"feedback","label":"确认后重新评审"}]}'::jsonb),
('video-production-advanced','1144ec9bf9cccd42ae7afb50231ff68a','{"nodes":[{"id":"p1_work1","name":"Script and narrative design","phase":"Creative and production scope","kind":"activity","responsibility":"Define theme, narrative, script and shot requirements against audience and delivery goals. Deliver: script and shot requirements."},{"id":"p1_work2","name":"Budget and production plan","phase":"Creative and production scope","kind":"activity","responsibility":"Review budget, people, locations, equipment, schedule and final formats. Deliver: production plan and budget."},{"id":"p1_review","name":"Creative and production scope review","phase":"Creative and production scope","kind":"decision","responsibility":"Review creative direction, budget and delivery specifications and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p2_work1","name":"Storyboard and shooting plan","phase":"Production preparation","kind":"activity","responsibility":"Break the script into scenes, shots, filming order and required materials with alternatives. Deliver: storyboard and shooting plan."},{"id":"p2_work2","name":"People, locations and equipment","phase":"Production preparation","kind":"activity","responsibility":"Confirm people, locations, equipment tests, usage arrangements and site response ownership. Deliver: shooting readiness checks."},{"id":"p2_review","name":"Production preparation review","phase":"Production preparation","kind":"decision","responsibility":"Review storyboards, site and recording readiness and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p3_work1","name":"Filming and production notes","phase":"Production and media management","kind":"activity","responsibility":"Capture shots and audio and record scenes, versions, deviations and usability. Deliver: captured media and production notes."},{"id":"p3_work2","name":"Media checks and backup","phase":"Production and media management","kind":"activity","responsibility":"Check naming, quantity, integrity and backups and record missing or unrecoverable media. Deliver: media inventory and backup evidence."},{"id":"p3_review","name":"Production and media management review","phase":"Production and media management","kind":"decision","responsibility":"Review captured results, media completeness and backups and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p4_work1","name":"Rough cut and narrative review","phase":"Editing and narrative confirmation","kind":"activity","responsibility":"Assemble a rough cut and check pace, information and missing shots against the script. Deliver: rough cut and revision record."},{"id":"p4_work2","name":"Fine cut and picture lock","phase":"Editing and narrative confirmation","kind":"activity","responsibility":"Apply review changes and record the picture version and unresolved items for post-production. Deliver: picture lock and post-production handoff."},{"id":"p4_review","name":"Editing and narrative confirmation review","phase":"Editing and narrative confirmation","kind":"decision","responsibility":"Review edit structure and picture-lock evidence and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p5_work1","name":"Color and visual finishing","phase":"Parallel post-production","kind":"activity","responsibility":"Complete color, graphics and visual finishing against the locked picture version. Deliver: visual finishing result."},{"id":"p5_work2","name":"Audio, captions and information","phase":"Parallel post-production","kind":"activity","responsibility":"Finish mixing, captions and credits and verify timing, language and usage records. Deliver: audio and text finishing result."},{"id":"p5_review","name":"Parallel post-production review","phase":"Parallel post-production","kind":"decision","responsibility":"Review picture, audio and text consistency and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p6_work1","name":"Creative and client review","phase":"Final review and quality checks","kind":"activity","responsibility":"Review the final cut against production goals and record findings, decision owners and revision scope. Deliver: final review and confirmation."},{"id":"p6_work2","name":"Technical QC and exports","phase":"Final review and quality checks","kind":"activity","responsibility":"Check synchronization, captions, color, audio levels and formats against delivery versions. Deliver: technical QC and exported files."},{"id":"p6_review","name":"Final review and quality checks review","phase":"Final review and quality checks","kind":"decision","responsibility":"Review content, technical formats and deliverability and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p7_work1","name":"Final delivery and receipt","phase":"Delivery and media archive","kind":"activity","responsibility":"Deliver approved files, formats and usage guidance and record receipt and omissions. Deliver: final delivery and receipt record."},{"id":"p7_work2","name":"Media archive and retrospective","phase":"Delivery and media archive","kind":"activity","responsibility":"Archive projects, media, versions and usage evidence and review production collaboration. Deliver: media archive and production retrospective."},{"id":"p7_review","name":"Delivery and media archive review","phase":"Delivery and media archive","kind":"decision","responsibility":"Review client receipt and traceable media and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"exception_action","name":"Reshoot and media recovery","phase":"Exceptions and recovery","kind":"activity","responsibility":"Identify missing or unsuitable shots and audio and perform approved reshoots, recovery or replacement."},{"id":"exception_review","name":"Recovery and readiness review","phase":"Exceptions and recovery","kind":"decision","responsibility":"Check impact, response evidence and recovery status. Identify reviews to repeat and obtain authorized confirmation before resuming."}],"edges":[{"from":"p1_work1","to":"p1_review","kind":"sequence","label":""},{"from":"p1_work2","to":"p1_review","kind":"sequence","label":""},{"from":"p1_review","to":"p1_work1","kind":"feedback","label":"Needs revision"},{"from":"p1_review","to":"p2_work1","kind":"sequence","label":"Accepted"},{"from":"p1_review","to":"p2_work2","kind":"sequence","label":"Accepted"},{"from":"p2_work1","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work2","to":"p2_review","kind":"sequence","label":""},{"from":"p2_review","to":"p2_work1","kind":"feedback","label":"Needs revision"},{"from":"p2_review","to":"p3_work1","kind":"sequence","label":"Accepted"},{"from":"p2_review","to":"p3_work2","kind":"sequence","label":"Accepted"},{"from":"p3_work1","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work2","to":"p3_review","kind":"sequence","label":""},{"from":"p3_review","to":"p3_work1","kind":"feedback","label":"Needs revision"},{"from":"p3_review","to":"p4_work1","kind":"sequence","label":"Accepted"},{"from":"p4_work1","to":"p4_work2","kind":"sequence","label":""},{"from":"p4_work2","to":"p4_review","kind":"sequence","label":""},{"from":"p4_review","to":"p4_work1","kind":"feedback","label":"Needs revision"},{"from":"p4_review","to":"p5_work1","kind":"sequence","label":"Accepted"},{"from":"p4_review","to":"p5_work2","kind":"sequence","label":"Accepted"},{"from":"p5_work1","to":"p5_review","kind":"sequence","label":""},{"from":"p5_work2","to":"p5_review","kind":"sequence","label":""},{"from":"p5_review","to":"p5_work1","kind":"feedback","label":"Needs revision"},{"from":"p5_review","to":"p6_work1","kind":"sequence","label":"Accepted"},{"from":"p5_review","to":"p6_work2","kind":"sequence","label":"Accepted"},{"from":"p6_work1","to":"p6_review","kind":"sequence","label":""},{"from":"p6_work2","to":"p6_review","kind":"sequence","label":""},{"from":"p6_review","to":"p6_work1","kind":"feedback","label":"Needs revision"},{"from":"p6_review","to":"p7_work1","kind":"sequence","label":"Accepted"},{"from":"p6_review","to":"p7_work2","kind":"sequence","label":"Accepted"},{"from":"p7_work1","to":"p7_review","kind":"sequence","label":""},{"from":"p7_work2","to":"p7_review","kind":"sequence","label":""},{"from":"p7_review","to":"p7_work1","kind":"feedback","label":"Needs revision"},{"from":"p6_review","to":"exception_action","kind":"sequence","label":"Exception response"},{"from":"exception_action","to":"exception_review","kind":"sequence","label":""},{"from":"exception_review","to":"p3_work1","kind":"feedback","label":"Confirmed re-review"}]}'::jsonb),
('marketing-campaign-advanced','986d21170d3d90cd50f562bfe594a929','{"nodes":[{"id":"p1_work1","name":"受众与市场洞察","phase":"目标与市场","kind":"activity","responsibility":"整理受众需求、竞争信息与购买路径，说明定位和细分依据。交付：受众与市场分析。"},{"id":"p1_work2","name":"目标与指标定义","phase":"目标与市场","kind":"activity","responsibility":"明确传播、获客或转化目标，约定指标口径、时间和解释范围。交付：营销目标与指标口径。"},{"id":"p1_review","name":"目标与市场评审","phase":"目标与市场","kind":"decision","responsibility":"核对市场证据、受众与成功指标并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p2_work1","name":"渠道与内容策略","phase":"策略与预算","kind":"activity","responsibility":"选择渠道、信息和内容组合，说明各渠道的作用与关联。交付：渠道与内容策略。"},{"id":"p2_work2","name":"预算排期与实验计划","phase":"策略与预算","kind":"activity","responsibility":"分配预算、排期和测试范围，明确控制条件与调整责任人。交付：预算与实验计划。"},{"id":"p2_review","name":"策略与预算评审","phase":"策略与预算","kind":"decision","responsibility":"核对渠道组合、预算与实验依据并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p3_work1","name":"文案视觉与渠道素材","phase":"并行素材与承接","kind":"activity","responsibility":"制作信息、视觉和渠道变体，登记版本与素材使用依据。交付：可审阅营销素材。"},{"id":"p3_work2","name":"承接页面与跟踪配置","phase":"并行素材与承接","kind":"activity","responsibility":"准备页面、表单、链接和跟踪口径，核对内容与营销目标一致。交付：承接路径与跟踪检查。"},{"id":"p3_review","name":"并行素材与承接评审","phase":"并行素材与承接","kind":"decision","responsibility":"核对素材、页面与跟踪一致性并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p4_work1","name":"内容品牌与使用审阅","phase":"上线准入","kind":"activity","responsibility":"核对品牌、事实、承诺、素材来源和适用发布安排，登记确认意见。交付：上线审阅记录。"},{"id":"p4_work2","name":"投放与转化链路实测","phase":"上线准入","kind":"activity","responsibility":"实测渠道设置、预算限制、链接、表单和数据回流，确认责任人。交付：投放与链路验证。"},{"id":"p4_review","name":"上线准入评审","phase":"上线准入","kind":"decision","responsibility":"核对素材准入、预算和渠道就绪并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p5_work1","name":"投放执行与日常观察","phase":"执行与归因","kind":"activity","responsibility":"成员执行确认方案，跟踪花费、覆盖、问题和调整记录。交付：活动执行与观察记录。"},{"id":"p5_work2","name":"数据核对与效果归因","phase":"执行与归因","kind":"activity","responsibility":"对照指标口径核对数据、转化质量和外部影响，区分相关与因果解释。交付：效果与归因报告。"},{"id":"p5_review","name":"执行与归因评审","phase":"执行与归因","kind":"decision","responsibility":"核对实际执行、数据质量与效果并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p6_work1","name":"优化实验与策略调整","phase":"优化与资产复盘","kind":"activity","responsibility":"根据证据提出素材、渠道或预算调整，明确实验条件与预期效果。交付：优化建议与实验结果。"},{"id":"p6_work2","name":"营销复盘与资产归档","phase":"优化与资产复盘","kind":"activity","responsibility":"归档有效素材、版本、成本和经验，整理下一轮活动的待确认事项。交付：营销复盘与资产清单。"},{"id":"p6_review","name":"优化与资产复盘评审","phase":"优化与资产复盘","kind":"decision","responsibility":"核对优化依据与可复用成果并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"exception_action","name":"投放异常与策略修正","phase":"异常处置与恢复","kind":"activity","responsibility":"核对预算异常、错误素材或渠道故障，暂停受影响活动，记录修正方案与恢复条件。"},{"id":"exception_review","name":"恢复与重新准入","phase":"异常处置与恢复","kind":"decision","responsibility":"核对异常影响、处置证据与恢复状态，明确哪些工作需要重新评审；获得有权人确认后再进入正常推进路径。"}],"edges":[{"from":"p1_work1","to":"p1_review","kind":"sequence","label":""},{"from":"p1_work2","to":"p1_review","kind":"sequence","label":""},{"from":"p1_review","to":"p1_work1","kind":"feedback","label":"未通过：修订"},{"from":"p1_review","to":"p2_work1","kind":"sequence","label":"通过"},{"from":"p1_review","to":"p2_work2","kind":"sequence","label":"通过"},{"from":"p2_work1","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work2","to":"p2_review","kind":"sequence","label":""},{"from":"p2_review","to":"p2_work1","kind":"feedback","label":"未通过：修订"},{"from":"p2_review","to":"p3_work1","kind":"sequence","label":"通过"},{"from":"p2_review","to":"p3_work2","kind":"sequence","label":"通过"},{"from":"p3_work1","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work2","to":"p3_review","kind":"sequence","label":""},{"from":"p3_review","to":"p3_work1","kind":"feedback","label":"未通过：修订"},{"from":"p3_review","to":"p4_work1","kind":"sequence","label":"通过"},{"from":"p3_review","to":"p4_work2","kind":"sequence","label":"通过"},{"from":"p4_work1","to":"p4_review","kind":"sequence","label":""},{"from":"p4_work2","to":"p4_review","kind":"sequence","label":""},{"from":"p4_review","to":"p4_work1","kind":"feedback","label":"未通过：修订"},{"from":"p4_review","to":"p5_work1","kind":"sequence","label":"通过"},{"from":"p4_review","to":"p5_work2","kind":"sequence","label":"通过"},{"from":"p5_work1","to":"p5_review","kind":"sequence","label":""},{"from":"p5_work2","to":"p5_review","kind":"sequence","label":""},{"from":"p5_review","to":"p5_work1","kind":"feedback","label":"未通过：修订"},{"from":"p5_review","to":"p6_work1","kind":"sequence","label":"通过"},{"from":"p5_review","to":"p6_work2","kind":"sequence","label":"通过"},{"from":"p6_work1","to":"p6_review","kind":"sequence","label":""},{"from":"p6_work2","to":"p6_review","kind":"sequence","label":""},{"from":"p6_review","to":"p6_work1","kind":"feedback","label":"未通过：修订"},{"from":"p5_review","to":"exception_action","kind":"sequence","label":"异常：专项处置"},{"from":"exception_action","to":"exception_review","kind":"sequence","label":""},{"from":"exception_review","to":"p3_work1","kind":"feedback","label":"确认后重新评审"}]}'::jsonb),
('marketing-campaign-advanced','745b6eece17b04ebc8883e09effe91f0','{"nodes":[{"id":"p1_work1","name":"Audience and market insights","phase":"Goals and market","kind":"activity","responsibility":"Review audience needs, competitors and customer journeys to support positioning and segmentation. Deliver: audience and market analysis."},{"id":"p1_work2","name":"Goals and measurement definitions","phase":"Goals and market","kind":"activity","responsibility":"Define awareness, acquisition or conversion goals and agree measures, timing and interpretation limits. Deliver: campaign goals and measurement definitions."},{"id":"p1_review","name":"Goals and market review","phase":"Goals and market","kind":"decision","responsibility":"Review market evidence, audiences and success measures and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p2_work1","name":"Channel and content strategy","phase":"Strategy and budget","kind":"activity","responsibility":"Choose channels, messages and content and explain their roles and relationships. Deliver: channel and content strategy."},{"id":"p2_work2","name":"Budget, schedule and experiment plan","phase":"Strategy and budget","kind":"activity","responsibility":"Allocate budget, schedule and experiments and define controls and adjustment ownership. Deliver: budget and experiment plan."},{"id":"p2_review","name":"Strategy and budget review","phase":"Strategy and budget","kind":"decision","responsibility":"Review channel mix, budget and experiment rationale and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p3_work1","name":"Copy, visuals and campaign assets","phase":"Parallel assets and conversion paths","kind":"activity","responsibility":"Produce messages, visuals and channel variants with versions and usage evidence. Deliver: reviewable campaign assets."},{"id":"p3_work2","name":"Destination pages and tracking","phase":"Parallel assets and conversion paths","kind":"activity","responsibility":"Prepare pages, forms, links and measurement settings aligned with campaign goals. Deliver: conversion paths and tracking checks."},{"id":"p3_review","name":"Parallel assets and conversion paths review","phase":"Parallel assets and conversion paths","kind":"decision","responsibility":"Review assets, destination pages and tracking consistency and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p4_work1","name":"Content, brand and usage review","phase":"Launch readiness","kind":"activity","responsibility":"Review brand, facts, claims, sources and publication arrangements and record decisions. Deliver: launch review record."},{"id":"p4_work2","name":"Delivery and conversion testing","phase":"Launch readiness","kind":"activity","responsibility":"Test channel settings, budget limits, links, forms and data return with assigned ownership. Deliver: campaign and conversion-path checks."},{"id":"p4_review","name":"Launch readiness review","phase":"Launch readiness","kind":"decision","responsibility":"Review asset approval, budget and channel readiness and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p5_work1","name":"Execution and ongoing observation","phase":"Execution and attribution","kind":"activity","responsibility":"Members execute the approved plan and track spending, reach, issues and adjustments. Deliver: campaign execution and observation."},{"id":"p5_work2","name":"Measurement checks and attribution","phase":"Execution and attribution","kind":"activity","responsibility":"Check data, conversion quality and external effects against definitions and distinguish correlation from causal claims. Deliver: performance and attribution report."},{"id":"p5_review","name":"Execution and attribution review","phase":"Execution and attribution","kind":"decision","responsibility":"Review execution, measurement quality and outcomes and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p6_work1","name":"Optimization experiments and adjustments","phase":"Optimization and asset retrospective","kind":"activity","responsibility":"Use evidence to propose asset, channel or budget changes with clear experiment conditions. Deliver: optimization proposals and experiment results."},{"id":"p6_work2","name":"Campaign retrospective and archive","phase":"Optimization and asset retrospective","kind":"activity","responsibility":"Archive effective assets, versions, costs and lessons and propose next-cycle work. Deliver: campaign retrospective and asset list."},{"id":"p6_review","name":"Optimization and asset retrospective review","phase":"Optimization and asset retrospective","kind":"decision","responsibility":"Review optimization evidence and reusable results and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"exception_action","name":"Campaign exceptions and strategy correction","phase":"Exceptions and recovery","kind":"activity","responsibility":"Investigate budget, asset or channel failures, pause affected activity and document corrections and recovery criteria."},{"id":"exception_review","name":"Recovery and readiness review","phase":"Exceptions and recovery","kind":"decision","responsibility":"Check impact, response evidence and recovery status. Identify reviews to repeat and obtain authorized confirmation before resuming."}],"edges":[{"from":"p1_work1","to":"p1_review","kind":"sequence","label":""},{"from":"p1_work2","to":"p1_review","kind":"sequence","label":""},{"from":"p1_review","to":"p1_work1","kind":"feedback","label":"Needs revision"},{"from":"p1_review","to":"p2_work1","kind":"sequence","label":"Accepted"},{"from":"p1_review","to":"p2_work2","kind":"sequence","label":"Accepted"},{"from":"p2_work1","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work2","to":"p2_review","kind":"sequence","label":""},{"from":"p2_review","to":"p2_work1","kind":"feedback","label":"Needs revision"},{"from":"p2_review","to":"p3_work1","kind":"sequence","label":"Accepted"},{"from":"p2_review","to":"p3_work2","kind":"sequence","label":"Accepted"},{"from":"p3_work1","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work2","to":"p3_review","kind":"sequence","label":""},{"from":"p3_review","to":"p3_work1","kind":"feedback","label":"Needs revision"},{"from":"p3_review","to":"p4_work1","kind":"sequence","label":"Accepted"},{"from":"p3_review","to":"p4_work2","kind":"sequence","label":"Accepted"},{"from":"p4_work1","to":"p4_review","kind":"sequence","label":""},{"from":"p4_work2","to":"p4_review","kind":"sequence","label":""},{"from":"p4_review","to":"p4_work1","kind":"feedback","label":"Needs revision"},{"from":"p4_review","to":"p5_work1","kind":"sequence","label":"Accepted"},{"from":"p4_review","to":"p5_work2","kind":"sequence","label":"Accepted"},{"from":"p5_work1","to":"p5_review","kind":"sequence","label":""},{"from":"p5_work2","to":"p5_review","kind":"sequence","label":""},{"from":"p5_review","to":"p5_work1","kind":"feedback","label":"Needs revision"},{"from":"p5_review","to":"p6_work1","kind":"sequence","label":"Accepted"},{"from":"p5_review","to":"p6_work2","kind":"sequence","label":"Accepted"},{"from":"p6_work1","to":"p6_review","kind":"sequence","label":""},{"from":"p6_work2","to":"p6_review","kind":"sequence","label":""},{"from":"p6_review","to":"p6_work1","kind":"feedback","label":"Needs revision"},{"from":"p5_review","to":"exception_action","kind":"sequence","label":"Exception response"},{"from":"exception_action","to":"exception_review","kind":"sequence","label":""},{"from":"exception_review","to":"p3_work1","kind":"feedback","label":"Confirmed re-review"}]}'::jsonb),
('commerce-operations-advanced','ede49cf2c47133722d24a450a3978445','{"nodes":[{"id":"p1_work1","name":"客群与经营目标","phase":"经营目标与商品","kind":"activity","responsibility":"明确客群、商品定位与阶段目标，定义评价口径和运营边界。交付：经营目标与客群说明。"},{"id":"p1_work2","name":"选品与商品计划","phase":"经营目标与商品","kind":"activity","responsibility":"核对商品需求、供给、成本和差异化，提出选品与上架范围。交付：选品与商品计划。"},{"id":"p1_review","name":"经营目标与商品评审","phase":"经营目标与商品","kind":"decision","responsibility":"核对经营目标与商品策略并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p2_work1","name":"商品资料与价格口径","phase":"库存与供应准备","kind":"activity","responsibility":"核对规格、图片、价格、服务承诺与素材使用，统一商品口径。交付：商品资料与价格清单。"},{"id":"p2_work2","name":"备货与供应协调","phase":"库存与供应准备","kind":"activity","responsibility":"核对库存、补货、供应时间和仓储容量，明确缺货及调整的责任人。交付：库存与供应计划。"},{"id":"p2_review","name":"库存与供应准备评审","phase":"库存与供应准备","kind":"decision","responsibility":"核对商品资料、库存与供应条件并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p3_work1","name":"店铺页面与活动配置","phase":"页面与活动建设","kind":"activity","responsibility":"制作商品与活动页面，核对优惠、库存提示和购买路径。交付：店铺与活动配置。"},{"id":"p3_work2","name":"客服与履约准备","phase":"页面与活动建设","kind":"activity","responsibility":"准备咨询、售后、仓储和运输信息，核对跨团队处理路径。交付：服务与履约准备清单。"},{"id":"p3_review","name":"页面与活动建设评审","phase":"页面与活动建设","kind":"decision","responsibility":"核对页面、活动与服务准备并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p4_work1","name":"店铺上线与链路检查","phase":"上线与订单核验","kind":"activity","responsibility":"成员完成确认的上线，实测商品、优惠、支付和信息展示。交付：上线与交易链路验证。"},{"id":"p4_work2","name":"支付与订单风险审阅","phase":"上线与订单核验","kind":"activity","responsibility":"核对订单、支付和风险标记，对异常情况按项目规则人工审阅。交付：订单核验与处理意见。"},{"id":"p4_review","name":"上线与订单核验评审","phase":"上线与订单核验","kind":"decision","responsibility":"核对上线结果、支付与订单风险并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p5_work1","name":"配货包装与发运","phase":"仓储与配送","kind":"activity","responsibility":"仓储按确认订单配货，核对商品、数量、包装及发运信息。交付：出库与发运记录。"},{"id":"p5_work2","name":"配送跟踪与签收","phase":"仓储与配送","kind":"activity","responsibility":"跟踪运输和签收，记录延误、损坏或差错并与客服交接。交付：配送与签收记录。"},{"id":"p5_review","name":"仓储与配送评审","phase":"仓储与配送","kind":"decision","responsibility":"核对配货、发货和配送证据并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p6_work1","name":"退换与客户问题","phase":"售后与对账","kind":"activity","responsibility":"核对客户诉求、商品状态与处理依据，执行经确认的退换或退款安排。交付：售后处理与客户记录。"},{"id":"p6_work2","name":"库存账务与费用对账","phase":"售后与对账","kind":"activity","responsibility":"核对订单、库存、退款、运输和平台费用，登记差异与责任人。交付：运营对账与差异清单。"},{"id":"p6_review","name":"售后与对账评审","phase":"售后与对账","kind":"decision","responsibility":"核对售后依据与业务数据一致性并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p7_work1","name":"经营与用户反馈","phase":"运营与服务改进","kind":"activity","responsibility":"对照目标核对商品表现、流量、交易及客户反馈，说明限制。交付：经营与用户反馈报告。"},{"id":"p7_work2","name":"商品服务与供应复盘","phase":"运营与服务改进","kind":"activity","responsibility":"复盘库存、服务、履约和售后问题，提出需确认的下一轮改进。交付：运营改进与行动建议。"},{"id":"p7_review","name":"运营与服务改进评审","phase":"运营与服务改进","kind":"decision","responsibility":"核对收益、服务和供应反馈并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"exception_action","name":"库存与履约异常处理","phase":"异常处置与恢复","kind":"activity","responsibility":"核对缺货、错发、延迟或高风险订单，协调客户和仓储，记录经确认的处理及恢复。"},{"id":"exception_review","name":"恢复与重新准入","phase":"异常处置与恢复","kind":"decision","responsibility":"核对异常影响、处置证据与恢复状态，明确哪些工作需要重新评审；获得有权人确认后再进入正常推进路径。"}],"edges":[{"from":"p1_work1","to":"p1_review","kind":"sequence","label":""},{"from":"p1_work2","to":"p1_review","kind":"sequence","label":""},{"from":"p1_review","to":"p1_work1","kind":"feedback","label":"未通过：修订"},{"from":"p1_review","to":"p2_work1","kind":"sequence","label":"通过"},{"from":"p1_review","to":"p2_work2","kind":"sequence","label":"通过"},{"from":"p2_work1","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work2","to":"p2_review","kind":"sequence","label":""},{"from":"p2_review","to":"p2_work1","kind":"feedback","label":"未通过：修订"},{"from":"p2_review","to":"p3_work1","kind":"sequence","label":"通过"},{"from":"p2_review","to":"p3_work2","kind":"sequence","label":"通过"},{"from":"p3_work1","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work2","to":"p3_review","kind":"sequence","label":""},{"from":"p3_review","to":"p3_work1","kind":"feedback","label":"未通过：修订"},{"from":"p3_review","to":"p4_work1","kind":"sequence","label":"通过"},{"from":"p4_work1","to":"p4_work2","kind":"sequence","label":""},{"from":"p4_work2","to":"p4_review","kind":"sequence","label":""},{"from":"p4_review","to":"p4_work1","kind":"feedback","label":"未通过：修订"},{"from":"p4_review","to":"p5_work1","kind":"sequence","label":"通过"},{"from":"p5_work1","to":"p5_work2","kind":"sequence","label":""},{"from":"p5_work2","to":"p5_review","kind":"sequence","label":""},{"from":"p5_review","to":"p5_work1","kind":"feedback","label":"未通过：修订"},{"from":"p5_review","to":"p6_work1","kind":"sequence","label":"通过"},{"from":"p5_review","to":"p6_work2","kind":"sequence","label":"通过"},{"from":"p6_work1","to":"p6_review","kind":"sequence","label":""},{"from":"p6_work2","to":"p6_review","kind":"sequence","label":""},{"from":"p6_review","to":"p6_work1","kind":"feedback","label":"未通过：修订"},{"from":"p6_review","to":"p7_work1","kind":"sequence","label":"通过"},{"from":"p6_review","to":"p7_work2","kind":"sequence","label":"通过"},{"from":"p7_work1","to":"p7_review","kind":"sequence","label":""},{"from":"p7_work2","to":"p7_review","kind":"sequence","label":""},{"from":"p7_review","to":"p7_work1","kind":"feedback","label":"未通过：修订"},{"from":"p5_review","to":"exception_action","kind":"sequence","label":"异常：专项处置"},{"from":"exception_action","to":"exception_review","kind":"sequence","label":""},{"from":"exception_review","to":"p2_work1","kind":"feedback","label":"确认后重新评审"}]}'::jsonb),
('commerce-operations-advanced','707241a2a4a80d12f44a7e8fdf4609db','{"nodes":[{"id":"p1_work1","name":"Customers and business goals","phase":"Business goals and products","kind":"activity","responsibility":"Define customers, product positioning, milestones and measurement boundaries. Deliver: business goals and customer definition."},{"id":"p1_work2","name":"Merchandising and product plan","phase":"Business goals and products","kind":"activity","responsibility":"Review demand, supply, costs and differentiation and propose the product range. Deliver: merchandising and product plan."},{"id":"p1_review","name":"Business goals and products review","phase":"Business goals and products","kind":"decision","responsibility":"Review business goals and product strategy and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p2_work1","name":"Product information and pricing definitions","phase":"Inventory and supply readiness","kind":"activity","responsibility":"Verify specifications, images, prices, service commitments and usage to keep product definitions consistent. Deliver: product information and pricing list."},{"id":"p2_work2","name":"Stock and supply coordination","phase":"Inventory and supply readiness","kind":"activity","responsibility":"Check stock, replenishment, supply timing and warehouse capacity with exception ownership. Deliver: inventory and supply plan."},{"id":"p2_review","name":"Inventory and supply readiness review","phase":"Inventory and supply readiness","kind":"decision","responsibility":"Review product information, stock and supply conditions and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p3_work1","name":"Store pages and campaigns","phase":"Store and campaign development","kind":"activity","responsibility":"Prepare product and campaign pages and verify offers, availability and purchasing journeys. Deliver: store and campaign setup."},{"id":"p3_work2","name":"Support and fulfilment preparation","phase":"Store and campaign development","kind":"activity","responsibility":"Prepare support, returns, warehouse and shipping information with cross-team handoffs. Deliver: service and fulfilment checklist."},{"id":"p3_review","name":"Store and campaign development review","phase":"Store and campaign development","kind":"decision","responsibility":"Review pages, campaigns and service readiness and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p4_work1","name":"Publish store and verify journeys","phase":"Publication and order review","kind":"activity","responsibility":"Members publish approved changes and test products, offers, payment and displayed information. Deliver: publication and transaction-path checks."},{"id":"p4_work2","name":"Payment and order risk review","phase":"Publication and order review","kind":"activity","responsibility":"Check orders, payment and risk flags and route exceptions for human review. Deliver: order checks and disposition."},{"id":"p4_review","name":"Publication and order review review","phase":"Publication and order review","kind":"decision","responsibility":"Review publication, payment and order risks and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p5_work1","name":"Picking, packing and dispatch","phase":"Warehouse and delivery","kind":"activity","responsibility":"Warehouse staff pick approved orders and verify products, quantities, packaging and dispatch details. Deliver: warehouse and dispatch record."},{"id":"p5_work2","name":"Shipment tracking and receipt","phase":"Warehouse and delivery","kind":"activity","responsibility":"Track shipping and receipt and hand delays, damage or errors to support. Deliver: delivery and receipt record."},{"id":"p5_review","name":"Warehouse and delivery review","phase":"Warehouse and delivery","kind":"decision","responsibility":"Review picking, shipping and delivery evidence and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p6_work1","name":"Returns, exchanges and customer issues","phase":"Returns and reconciliation","kind":"activity","responsibility":"Review customer requests, item condition and evidence before applying approved return or refund decisions. Deliver: returns disposition and customer record."},{"id":"p6_work2","name":"Inventory and fee reconciliation","phase":"Returns and reconciliation","kind":"activity","responsibility":"Reconcile orders, stock, refunds, shipping and platform fees and assign discrepancies. Deliver: operations reconciliation and discrepancy list."},{"id":"p6_review","name":"Returns and reconciliation review","phase":"Returns and reconciliation","kind":"decision","responsibility":"Review returns evidence and business-data consistency and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p7_work1","name":"Business results and user feedback","phase":"Operations and service improvement","kind":"activity","responsibility":"Review product performance, traffic, transactions and customer feedback against goals. Deliver: business and user feedback report."},{"id":"p7_work2","name":"Product, service and supply review","phase":"Operations and service improvement","kind":"activity","responsibility":"Review inventory, service, fulfilment and returns and propose next-cycle improvements. Deliver: operations improvements and action proposals."},{"id":"p7_review","name":"Operations and service improvement review","phase":"Operations and service improvement","kind":"decision","responsibility":"Review business results, service and supply feedback and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"exception_action","name":"Inventory and fulfilment exceptions","phase":"Exceptions and recovery","kind":"activity","responsibility":"Investigate stockouts, delivery errors, delays or high-risk orders and coordinate approved customer and warehouse responses."},{"id":"exception_review","name":"Recovery and readiness review","phase":"Exceptions and recovery","kind":"decision","responsibility":"Check impact, response evidence and recovery status. Identify reviews to repeat and obtain authorized confirmation before resuming."}],"edges":[{"from":"p1_work1","to":"p1_review","kind":"sequence","label":""},{"from":"p1_work2","to":"p1_review","kind":"sequence","label":""},{"from":"p1_review","to":"p1_work1","kind":"feedback","label":"Needs revision"},{"from":"p1_review","to":"p2_work1","kind":"sequence","label":"Accepted"},{"from":"p1_review","to":"p2_work2","kind":"sequence","label":"Accepted"},{"from":"p2_work1","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work2","to":"p2_review","kind":"sequence","label":""},{"from":"p2_review","to":"p2_work1","kind":"feedback","label":"Needs revision"},{"from":"p2_review","to":"p3_work1","kind":"sequence","label":"Accepted"},{"from":"p2_review","to":"p3_work2","kind":"sequence","label":"Accepted"},{"from":"p3_work1","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work2","to":"p3_review","kind":"sequence","label":""},{"from":"p3_review","to":"p3_work1","kind":"feedback","label":"Needs revision"},{"from":"p3_review","to":"p4_work1","kind":"sequence","label":"Accepted"},{"from":"p4_work1","to":"p4_work2","kind":"sequence","label":""},{"from":"p4_work2","to":"p4_review","kind":"sequence","label":""},{"from":"p4_review","to":"p4_work1","kind":"feedback","label":"Needs revision"},{"from":"p4_review","to":"p5_work1","kind":"sequence","label":"Accepted"},{"from":"p5_work1","to":"p5_work2","kind":"sequence","label":""},{"from":"p5_work2","to":"p5_review","kind":"sequence","label":""},{"from":"p5_review","to":"p5_work1","kind":"feedback","label":"Needs revision"},{"from":"p5_review","to":"p6_work1","kind":"sequence","label":"Accepted"},{"from":"p5_review","to":"p6_work2","kind":"sequence","label":"Accepted"},{"from":"p6_work1","to":"p6_review","kind":"sequence","label":""},{"from":"p6_work2","to":"p6_review","kind":"sequence","label":""},{"from":"p6_review","to":"p6_work1","kind":"feedback","label":"Needs revision"},{"from":"p6_review","to":"p7_work1","kind":"sequence","label":"Accepted"},{"from":"p6_review","to":"p7_work2","kind":"sequence","label":"Accepted"},{"from":"p7_work1","to":"p7_review","kind":"sequence","label":""},{"from":"p7_work2","to":"p7_review","kind":"sequence","label":""},{"from":"p7_review","to":"p7_work1","kind":"feedback","label":"Needs revision"},{"from":"p5_review","to":"exception_action","kind":"sequence","label":"Exception response"},{"from":"exception_action","to":"exception_review","kind":"sequence","label":""},{"from":"exception_review","to":"p2_work1","kind":"feedback","label":"Confirmed re-review"}]}'::jsonb),
('research-study-advanced','e95e302c14149abb511ee3d284980eb9','{"nodes":[{"id":"p1_work1","name":"研究问题与假设","phase":"问题与证据","kind":"activity","responsibility":"明确研究问题、假设、价值和可检验范围，区分探索与验证目标。交付：问题与假设说明。"},{"id":"p1_work2","name":"文献与证据梳理","phase":"问题与证据","kind":"activity","responsibility":"整理相关研究和材料，记录方法、证据不足及需要解决的差异。交付：文献与证据地图。"},{"id":"p1_review","name":"问题与证据评审","phase":"问题与证据","kind":"decision","responsibility":"核对研究问题与既有证据并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p2_work1","name":"方法与分析计划","phase":"研究方案与准入","kind":"activity","responsibility":"确定样本、变量、测量、对照与分析方法，记录推断范围和偏差控制。交付：研究与分析方案。"},{"id":"p2_work2","name":"资源与适用评审","phase":"研究方案与准入","kind":"activity","responsibility":"核对资源、人员、数据使用和适用审阅安排，确认准备条件。交付：研究准入与资源记录。"},{"id":"p2_review","name":"研究方案与准入评审","phase":"研究方案与准入","kind":"decision","responsibility":"核对方法、分析方案和适用审阅并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p3_work1","name":"研究实施与过程记录","phase":"并行准备与实施","kind":"activity","responsibility":"按确认方法开展研究，登记偏差、环境、参数和实际执行过程。交付：研究过程与实验记录。"},{"id":"p3_work2","name":"数据管理与质量检查","phase":"并行准备与实施","kind":"activity","responsibility":"保留原始数据与变换记录，检查完整性、标识和异常处理。交付：数据版本与质量报告。"},{"id":"p3_review","name":"并行准备与实施评审","phase":"并行准备与实施","kind":"decision","responsibility":"核对研究记录与可核对数据并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p4_work1","name":"分析与结果解释","phase":"分析与复现","kind":"activity","responsibility":"执行确认的分析，说明不确定性、假设和结论的适用范围。交付：分析结果与解释。"},{"id":"p4_work2","name":"独立核验与复现","phase":"分析与复现","kind":"activity","responsibility":"由不同人员复核关键结果和分析材料，登记无法复现的差异。交付：复现与核验记录。"},{"id":"p4_review","name":"分析与复现评审","phase":"分析与复现","kind":"decision","responsibility":"核对分析正确性与可复现性并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p5_work1","name":"报告与论证制作","phase":"成果与同行审阅","kind":"activity","responsibility":"整理研究问题、方法、数据与限制，将事实和推断清晰区分。交付：研究成果稿。"},{"id":"p5_work2","name":"同行与课题审阅","phase":"成果与同行审阅","kind":"activity","responsibility":"审阅方法、结论、材料和限制，记录质疑、回应及修改依据。交付：审阅与回应记录。"},{"id":"p5_review","name":"成果与同行审阅评审","phase":"成果与同行审阅","kind":"decision","responsibility":"核对结论、论证与材料一致性并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p6_work1","name":"成果交付与资料归档","phase":"交付与资料维护","kind":"activity","responsibility":"交付确认成果，按适用范围归档数据、代码、方法和版本。交付：成果与可复现资料包。"},{"id":"p6_work2","name":"后续问题与研究复盘","phase":"交付与资料维护","kind":"activity","responsibility":"记录未解决问题、复现反馈和后续研究建议，保持成果变更可追溯。交付：研究复盘与后续问题。"},{"id":"p6_review","name":"交付与资料维护评审","phase":"交付与资料维护","kind":"decision","responsibility":"核对成果接收与可复用资料并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"exception_action","name":"数据偏差与研究修订","phase":"异常处置与恢复","kind":"activity","responsibility":"登记异常数据、分析偏差和受影响结论，核对方法与资料后提出修订或补充研究。"},{"id":"exception_review","name":"恢复与重新准入","phase":"异常处置与恢复","kind":"decision","responsibility":"核对异常影响、处置证据与恢复状态，明确哪些工作需要重新评审；获得有权人确认后再进入正常推进路径。"}],"edges":[{"from":"p1_work1","to":"p1_review","kind":"sequence","label":""},{"from":"p1_work2","to":"p1_review","kind":"sequence","label":""},{"from":"p1_review","to":"p1_work1","kind":"feedback","label":"未通过：修订"},{"from":"p1_review","to":"p2_work1","kind":"sequence","label":"通过"},{"from":"p1_review","to":"p2_work2","kind":"sequence","label":"通过"},{"from":"p2_work1","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work2","to":"p2_review","kind":"sequence","label":""},{"from":"p2_review","to":"p2_work1","kind":"feedback","label":"未通过：修订"},{"from":"p2_review","to":"p3_work1","kind":"sequence","label":"通过"},{"from":"p2_review","to":"p3_work2","kind":"sequence","label":"通过"},{"from":"p3_work1","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work2","to":"p3_review","kind":"sequence","label":""},{"from":"p3_review","to":"p3_work1","kind":"feedback","label":"未通过：修订"},{"from":"p3_review","to":"p4_work1","kind":"sequence","label":"通过"},{"from":"p4_work1","to":"p4_work2","kind":"sequence","label":""},{"from":"p4_work2","to":"p4_review","kind":"sequence","label":""},{"from":"p4_review","to":"p4_work1","kind":"feedback","label":"未通过：修订"},{"from":"p4_review","to":"p5_work1","kind":"sequence","label":"通过"},{"from":"p4_review","to":"p5_work2","kind":"sequence","label":"通过"},{"from":"p5_work1","to":"p5_review","kind":"sequence","label":""},{"from":"p5_work2","to":"p5_review","kind":"sequence","label":""},{"from":"p5_review","to":"p5_work1","kind":"feedback","label":"未通过：修订"},{"from":"p5_review","to":"p6_work1","kind":"sequence","label":"通过"},{"from":"p5_review","to":"p6_work2","kind":"sequence","label":"通过"},{"from":"p6_work1","to":"p6_review","kind":"sequence","label":""},{"from":"p6_work2","to":"p6_review","kind":"sequence","label":""},{"from":"p6_review","to":"p6_work1","kind":"feedback","label":"未通过：修订"},{"from":"p4_review","to":"exception_action","kind":"sequence","label":"异常：专项处置"},{"from":"exception_action","to":"exception_review","kind":"sequence","label":""},{"from":"exception_review","to":"p2_work1","kind":"feedback","label":"确认后重新评审"}]}'::jsonb),
('research-study-advanced','47922ddeb4ab25be5b8bed0c8c7e9ba9','{"nodes":[{"id":"p1_work1","name":"Questions and hypotheses","phase":"Questions and evidence","kind":"activity","responsibility":"Define questions, hypotheses, value and testable boundaries and distinguish exploration from confirmation. Deliver: question and hypothesis statement."},{"id":"p1_work2","name":"Literature and evidence review","phase":"Questions and evidence","kind":"activity","responsibility":"Review relevant studies and materials and identify methods, evidence gaps and unresolved differences. Deliver: literature and evidence map."},{"id":"p1_review","name":"Questions and evidence review","phase":"Questions and evidence","kind":"decision","responsibility":"Review research questions and existing evidence and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p2_work1","name":"Methods and analysis plan","phase":"Study design and readiness","kind":"activity","responsibility":"Define samples, variables, measures, comparisons and analysis with inference limits and bias controls. Deliver: study and analysis plan."},{"id":"p2_work2","name":"Resources and applicable review","phase":"Study design and readiness","kind":"activity","responsibility":"Check resources, people, data use and applicable review arrangements for readiness. Deliver: study readiness and resource record."},{"id":"p2_review","name":"Study design and readiness review","phase":"Study design and readiness","kind":"decision","responsibility":"Review methods, analysis plans and applicable review and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p3_work1","name":"Study execution and process records","phase":"Parallel preparation and execution","kind":"activity","responsibility":"Conduct the study using approved methods and record deviations, environments, parameters and execution. Deliver: study process and experimental records."},{"id":"p3_work2","name":"Data management and quality checks","phase":"Parallel preparation and execution","kind":"activity","responsibility":"Preserve source data and transformations and verify completeness, identifiers and anomaly treatment. Deliver: data versions and quality report."},{"id":"p3_review","name":"Parallel preparation and execution review","phase":"Parallel preparation and execution","kind":"decision","responsibility":"Review study records and verifiable data and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p4_work1","name":"Analysis and interpretation","phase":"Analysis and reproduction","kind":"activity","responsibility":"Execute the agreed analysis and explain uncertainty, assumptions and applicability. Deliver: analysis results and interpretation."},{"id":"p4_work2","name":"Independent verification and reproduction","phase":"Analysis and reproduction","kind":"activity","responsibility":"Different staff verify key results and analysis materials and record reproducibility differences. Deliver: reproduction and verification record."},{"id":"p4_review","name":"Analysis and reproduction review","phase":"Analysis and reproduction","kind":"decision","responsibility":"Review analytical correctness and reproducibility and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p5_work1","name":"Reporting and argument development","phase":"Results and peer review","kind":"activity","responsibility":"Report questions, methods, data and limits and clearly separate observations from inferences. Deliver: research result draft."},{"id":"p5_work2","name":"Peer and project review","phase":"Results and peer review","kind":"activity","responsibility":"Review methods, conclusions, materials and limits and record questions, responses and revisions. Deliver: review and response record."},{"id":"p5_review","name":"Results and peer review review","phase":"Results and peer review","kind":"decision","responsibility":"Review conclusions, arguments and material consistency and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p6_work1","name":"Deliver results and archive materials","phase":"Delivery and material maintenance","kind":"activity","responsibility":"Deliver approved results and archive permitted data, code, methods and versions. Deliver: results and reproducible-material package."},{"id":"p6_work2","name":"Follow-up questions and retrospective","phase":"Delivery and material maintenance","kind":"activity","responsibility":"Record open questions, reproduction feedback and future research proposals with traceable changes. Deliver: study retrospective and future questions."},{"id":"p6_review","name":"Delivery and material maintenance review","phase":"Delivery and material maintenance","kind":"decision","responsibility":"Review accepted results and reusable materials and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"exception_action","name":"Data bias and study revision","phase":"Exceptions and recovery","kind":"activity","responsibility":"Record data anomalies, analytical bias and affected conclusions and propose corrections or additional work."},{"id":"exception_review","name":"Recovery and readiness review","phase":"Exceptions and recovery","kind":"decision","responsibility":"Check impact, response evidence and recovery status. Identify reviews to repeat and obtain authorized confirmation before resuming."}],"edges":[{"from":"p1_work1","to":"p1_review","kind":"sequence","label":""},{"from":"p1_work2","to":"p1_review","kind":"sequence","label":""},{"from":"p1_review","to":"p1_work1","kind":"feedback","label":"Needs revision"},{"from":"p1_review","to":"p2_work1","kind":"sequence","label":"Accepted"},{"from":"p1_review","to":"p2_work2","kind":"sequence","label":"Accepted"},{"from":"p2_work1","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work2","to":"p2_review","kind":"sequence","label":""},{"from":"p2_review","to":"p2_work1","kind":"feedback","label":"Needs revision"},{"from":"p2_review","to":"p3_work1","kind":"sequence","label":"Accepted"},{"from":"p2_review","to":"p3_work2","kind":"sequence","label":"Accepted"},{"from":"p3_work1","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work2","to":"p3_review","kind":"sequence","label":""},{"from":"p3_review","to":"p3_work1","kind":"feedback","label":"Needs revision"},{"from":"p3_review","to":"p4_work1","kind":"sequence","label":"Accepted"},{"from":"p4_work1","to":"p4_work2","kind":"sequence","label":""},{"from":"p4_work2","to":"p4_review","kind":"sequence","label":""},{"from":"p4_review","to":"p4_work1","kind":"feedback","label":"Needs revision"},{"from":"p4_review","to":"p5_work1","kind":"sequence","label":"Accepted"},{"from":"p4_review","to":"p5_work2","kind":"sequence","label":"Accepted"},{"from":"p5_work1","to":"p5_review","kind":"sequence","label":""},{"from":"p5_work2","to":"p5_review","kind":"sequence","label":""},{"from":"p5_review","to":"p5_work1","kind":"feedback","label":"Needs revision"},{"from":"p5_review","to":"p6_work1","kind":"sequence","label":"Accepted"},{"from":"p5_review","to":"p6_work2","kind":"sequence","label":"Accepted"},{"from":"p6_work1","to":"p6_review","kind":"sequence","label":""},{"from":"p6_work2","to":"p6_review","kind":"sequence","label":""},{"from":"p6_review","to":"p6_work1","kind":"feedback","label":"Needs revision"},{"from":"p4_review","to":"exception_action","kind":"sequence","label":"Exception response"},{"from":"exception_action","to":"exception_review","kind":"sequence","label":""},{"from":"exception_review","to":"p2_work1","kind":"feedback","label":"Confirmed re-review"}]}'::jsonb),
('course-delivery-advanced','f8c846d12147aeee178f99f16b757e85','{"nodes":[{"id":"p1_work1","name":"能力与需求分析","phase":"需求与学习者","kind":"activity","responsibility":"确认需要改善的实际表现、能力缺口和培训是否适合解决该问题。交付：培训需求与能力缺口。"},{"id":"p1_work2","name":"学习者与条件盘点","phase":"需求与学习者","kind":"activity","responsibility":"核对学习者基础、时间、语言、设备和支持需求。交付：学习者与条件分析。"},{"id":"p1_review","name":"需求与学习者评审","phase":"需求与学习者","kind":"decision","responsibility":"核对能力缺口与学习条件并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p2_work1","name":"目标与课程结构","phase":"教学设计","kind":"activity","responsibility":"建立可验证目标、课程次序和前置知识，说明目标之间的关系。交付：目标与课程结构。"},{"id":"p2_work2","name":"教学与评价策略","phase":"教学设计","kind":"activity","responsibility":"设计练习、教学活动、评估与反馈方式，确保与目标对应。交付：教学与评价方案。"},{"id":"p2_review","name":"教学设计评审","phase":"教学设计","kind":"decision","responsibility":"核对目标、活动与评价一致性并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p3_work1","name":"课件与学习材料","phase":"并行内容开发","kind":"activity","responsibility":"制作课件、案例、练习和学习指南，标注来源与版本。交付：课程与学习材料。"},{"id":"p3_work2","name":"评价工具与教师准备","phase":"并行内容开发","kind":"activity","responsibility":"制作评价任务、评分依据和教师指南，验证使用方式与支持条件。交付：评价工具与教师指南。"},{"id":"p3_review","name":"并行内容开发评审","phase":"并行内容开发","kind":"decision","responsibility":"核对材料、评估与教学支持并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p4_work1","name":"小范围试讲与观察","phase":"试讲与质量审阅","kind":"activity","responsibility":"在代表性范围试讲，观察时间、理解、练习和工具的使用。交付：试讲与观察记录。"},{"id":"p4_work2","name":"内容与活动修订","phase":"试讲与质量审阅","kind":"activity","responsibility":"整理试讲反馈，修订难点、材料、节奏与评价任务。交付：质量审阅与修订记录。"},{"id":"p4_review","name":"试讲与质量审阅评审","phase":"试讲与质量审阅","kind":"decision","responsibility":"核对试讲结果与材料可用性并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p5_work1","name":"教学执行与学习支持","phase":"教学与过程支持","kind":"activity","responsibility":"教师按确认安排授课，记录学习进展、困难和必要的过程调整。交付：教学与学习支持记录。"},{"id":"p5_work2","name":"学习评价与即时反馈","phase":"教学与过程支持","kind":"activity","responsibility":"实施目标相关评价，提供可行动反馈并记录未达到目标的情况。交付：学习评价与反馈。"},{"id":"p5_review","name":"教学与过程支持评审","phase":"教学与过程支持","kind":"decision","responsibility":"核对实际教学与学习反馈并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p6_work1","name":"效果与应用验证","phase":"效果与课程维护","kind":"activity","responsibility":"核对能力改善和实际应用证据，说明评价口径和观察限制。交付：学习效果与应用报告。"},{"id":"p6_work2","name":"课程更新与教学复盘","phase":"效果与课程维护","kind":"activity","responsibility":"归档版本与经验，提出材料、活动和教师支持的后续改进。交付：课程维护与改进计划。"},{"id":"p6_review","name":"效果与课程维护评审","phase":"效果与课程维护","kind":"decision","responsibility":"核对学习效果与后续应用并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"exception_action","name":"学习困难与教学调整","phase":"异常处置与恢复","kind":"activity","responsibility":"识别未达到目标的任务和群体，检查前置知识、教材和授课方式，提出补充训练与修订。"},{"id":"exception_review","name":"恢复与重新准入","phase":"异常处置与恢复","kind":"decision","responsibility":"核对异常影响、处置证据与恢复状态，明确哪些工作需要重新评审；获得有权人确认后再进入正常推进路径。"}],"edges":[{"from":"p1_work1","to":"p1_review","kind":"sequence","label":""},{"from":"p1_work2","to":"p1_review","kind":"sequence","label":""},{"from":"p1_review","to":"p1_work1","kind":"feedback","label":"未通过：修订"},{"from":"p1_review","to":"p2_work1","kind":"sequence","label":"通过"},{"from":"p1_review","to":"p2_work2","kind":"sequence","label":"通过"},{"from":"p2_work1","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work2","to":"p2_review","kind":"sequence","label":""},{"from":"p2_review","to":"p2_work1","kind":"feedback","label":"未通过：修订"},{"from":"p2_review","to":"p3_work1","kind":"sequence","label":"通过"},{"from":"p2_review","to":"p3_work2","kind":"sequence","label":"通过"},{"from":"p3_work1","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work2","to":"p3_review","kind":"sequence","label":""},{"from":"p3_review","to":"p3_work1","kind":"feedback","label":"未通过：修订"},{"from":"p3_review","to":"p4_work1","kind":"sequence","label":"通过"},{"from":"p4_work1","to":"p4_work2","kind":"sequence","label":""},{"from":"p4_work2","to":"p4_review","kind":"sequence","label":""},{"from":"p4_review","to":"p4_work1","kind":"feedback","label":"未通过：修订"},{"from":"p4_review","to":"p5_work1","kind":"sequence","label":"通过"},{"from":"p4_review","to":"p5_work2","kind":"sequence","label":"通过"},{"from":"p5_work1","to":"p5_review","kind":"sequence","label":""},{"from":"p5_work2","to":"p5_review","kind":"sequence","label":""},{"from":"p5_review","to":"p5_work1","kind":"feedback","label":"未通过：修订"},{"from":"p5_review","to":"p6_work1","kind":"sequence","label":"通过"},{"from":"p5_review","to":"p6_work2","kind":"sequence","label":"通过"},{"from":"p6_work1","to":"p6_review","kind":"sequence","label":""},{"from":"p6_work2","to":"p6_review","kind":"sequence","label":""},{"from":"p6_review","to":"p6_work1","kind":"feedback","label":"未通过：修订"},{"from":"p5_review","to":"exception_action","kind":"sequence","label":"异常：专项处置"},{"from":"exception_action","to":"exception_review","kind":"sequence","label":""},{"from":"exception_review","to":"p2_work1","kind":"feedback","label":"确认后重新评审"}]}'::jsonb),
('course-delivery-advanced','b0a4f0d900c1d1c90e3c2e0dcdb1a1a4','{"nodes":[{"id":"p1_work1","name":"Competency and needs analysis","phase":"Needs and learners","kind":"activity","responsibility":"Identify performance gaps, missing competencies and whether training suits the problem. Deliver: training needs and competency gaps."},{"id":"p1_work2","name":"Learners and learning conditions","phase":"Needs and learners","kind":"activity","responsibility":"Review learners, prior knowledge, timing, language, equipment and support requirements. Deliver: learner and condition analysis."},{"id":"p1_review","name":"Needs and learners review","phase":"Needs and learners","kind":"decision","responsibility":"Review competency gaps and learning conditions and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p2_work1","name":"Objectives and course structure","phase":"Instructional design","kind":"activity","responsibility":"Define measurable objectives, course sequence and prerequisites and explain relationships. Deliver: objectives and course structure."},{"id":"p2_work2","name":"Instruction and assessment strategy","phase":"Instructional design","kind":"activity","responsibility":"Design practice, activities, assessment and feedback aligned with the objectives. Deliver: instruction and assessment strategy."},{"id":"p2_review","name":"Instructional design review","phase":"Instructional design","kind":"decision","responsibility":"Review alignment of goals, activities and assessment and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p3_work1","name":"Courseware and learning materials","phase":"Parallel content development","kind":"activity","responsibility":"Produce courseware, cases, practice and learning guides with sources and versions. Deliver: course and learning materials."},{"id":"p3_work2","name":"Assessment tools and instructor readiness","phase":"Parallel content development","kind":"activity","responsibility":"Prepare assessments, scoring evidence and instructor guides and verify delivery support. Deliver: assessment tools and instructor guides."},{"id":"p3_review","name":"Parallel content development review","phase":"Parallel content development","kind":"decision","responsibility":"Review materials, assessment and teaching support and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p4_work1","name":"Pilot delivery and observation","phase":"Pilot and quality review","kind":"activity","responsibility":"Pilot with representative learners and observe timing, comprehension, practice and tool use. Deliver: pilot and observation record."},{"id":"p4_work2","name":"Content and activity revision","phase":"Pilot and quality review","kind":"activity","responsibility":"Review pilot feedback and revise difficulties, materials, pacing and assessments. Deliver: quality review and revision record."},{"id":"p4_review","name":"Pilot and quality review review","phase":"Pilot and quality review","kind":"decision","responsibility":"Review pilot findings and material usability and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p5_work1","name":"Teaching execution and support","phase":"Teaching and learning support","kind":"activity","responsibility":"Instructors deliver the approved plan and record progress, difficulties and necessary adjustments. Deliver: teaching and learner-support record."},{"id":"p5_work2","name":"Assessment and timely feedback","phase":"Teaching and learning support","kind":"activity","responsibility":"Assess against objectives, provide actionable feedback and record unmet goals. Deliver: learning assessment and feedback."},{"id":"p5_review","name":"Teaching and learning support review","phase":"Teaching and learning support","kind":"decision","responsibility":"Review actual teaching and learner feedback and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p6_work1","name":"Outcome and application verification","phase":"Effectiveness and course maintenance","kind":"activity","responsibility":"Review competency and application evidence with measurement definitions and observation limits. Deliver: learning outcomes and application report."},{"id":"p6_work2","name":"Course updates and retrospective","phase":"Effectiveness and course maintenance","kind":"activity","responsibility":"Archive versions and lessons and propose improvements to materials, activities and instructor support. Deliver: course maintenance and improvement plan."},{"id":"p6_review","name":"Effectiveness and course maintenance review","phase":"Effectiveness and course maintenance","kind":"decision","responsibility":"Review learning outcomes and subsequent application and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"exception_action","name":"Learning difficulties and teaching adjustments","phase":"Exceptions and recovery","kind":"activity","responsibility":"Identify unmet learning goals and groups, review prerequisites, materials and delivery, and propose remedial practice and revisions."},{"id":"exception_review","name":"Recovery and readiness review","phase":"Exceptions and recovery","kind":"decision","responsibility":"Check impact, response evidence and recovery status. Identify reviews to repeat and obtain authorized confirmation before resuming."}],"edges":[{"from":"p1_work1","to":"p1_review","kind":"sequence","label":""},{"from":"p1_work2","to":"p1_review","kind":"sequence","label":""},{"from":"p1_review","to":"p1_work1","kind":"feedback","label":"Needs revision"},{"from":"p1_review","to":"p2_work1","kind":"sequence","label":"Accepted"},{"from":"p1_review","to":"p2_work2","kind":"sequence","label":"Accepted"},{"from":"p2_work1","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work2","to":"p2_review","kind":"sequence","label":""},{"from":"p2_review","to":"p2_work1","kind":"feedback","label":"Needs revision"},{"from":"p2_review","to":"p3_work1","kind":"sequence","label":"Accepted"},{"from":"p2_review","to":"p3_work2","kind":"sequence","label":"Accepted"},{"from":"p3_work1","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work2","to":"p3_review","kind":"sequence","label":""},{"from":"p3_review","to":"p3_work1","kind":"feedback","label":"Needs revision"},{"from":"p3_review","to":"p4_work1","kind":"sequence","label":"Accepted"},{"from":"p4_work1","to":"p4_work2","kind":"sequence","label":""},{"from":"p4_work2","to":"p4_review","kind":"sequence","label":""},{"from":"p4_review","to":"p4_work1","kind":"feedback","label":"Needs revision"},{"from":"p4_review","to":"p5_work1","kind":"sequence","label":"Accepted"},{"from":"p4_review","to":"p5_work2","kind":"sequence","label":"Accepted"},{"from":"p5_work1","to":"p5_review","kind":"sequence","label":""},{"from":"p5_work2","to":"p5_review","kind":"sequence","label":""},{"from":"p5_review","to":"p5_work1","kind":"feedback","label":"Needs revision"},{"from":"p5_review","to":"p6_work1","kind":"sequence","label":"Accepted"},{"from":"p5_review","to":"p6_work2","kind":"sequence","label":"Accepted"},{"from":"p6_work1","to":"p6_review","kind":"sequence","label":""},{"from":"p6_work2","to":"p6_review","kind":"sequence","label":""},{"from":"p6_review","to":"p6_work1","kind":"feedback","label":"Needs revision"},{"from":"p5_review","to":"exception_action","kind":"sequence","label":"Exception response"},{"from":"exception_action","to":"exception_review","kind":"sequence","label":""},{"from":"exception_review","to":"p2_work1","kind":"feedback","label":"Confirmed re-review"}]}'::jsonb),
('event-delivery-advanced','4dc63ee01d294180fc5ab6e898853e56','{"nodes":[{"id":"p1_work1","name":"活动目标与受众","phase":"目标与范围","kind":"activity","responsibility":"明确活动目的、参与者、规模和成果，约定衡量效果的方式。交付：活动目标与受众说明。"},{"id":"p1_work2","name":"预算与风险盘点","phase":"目标与范围","kind":"activity","responsibility":"核对预算、排期、场地条件和关键风险，明确组织责任。交付：预算与风险清单。"},{"id":"p1_review","name":"目标与范围评审","phase":"目标与范围","kind":"decision","responsibility":"核对活动价值、受众与资源边界并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p2_work1","name":"活动流程与内容策划","phase":"方案与协作","kind":"activity","responsibility":"设计活动内容、顺序、嘉宾与参与方式，标明关键切换和等待。交付：活动方案与流程表。"},{"id":"p2_work2","name":"团队与供应商安排","phase":"方案与协作","kind":"activity","responsibility":"落实场地、供应商、人员与交接职责，确认服务规格。交付：团队与供应资源安排。"},{"id":"p2_review","name":"方案与协作评审","phase":"方案与协作","kind":"decision","responsibility":"核对节目流程与人员分工并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p3_work1","name":"场地物料与技术准备","phase":"并行资源准备","kind":"activity","responsibility":"核对布置、设备、物料、标识和技术系统，记录就绪与缺项。交付：现场资源检查。"},{"id":"p3_work2","name":"嘉宾招募与参与服务","phase":"并行资源准备","kind":"activity","responsibility":"确认嘉宾、报名、接待、交通和参与说明，登记特殊需求。交付：参与者与服务清单。"},{"id":"p3_review","name":"并行资源准备评审","phase":"并行资源准备","kind":"decision","responsibility":"核对现场资源与参与者服务并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p4_work1","name":"全流程演练与问题修正","phase":"演练与开场准入","kind":"activity","responsibility":"演练切换、音视频、接待和现场职责，修正操作与信息差异。交付：演练记录与修正清单。"},{"id":"p4_work2","name":"现场检查与预案确认","phase":"演练与开场准入","kind":"activity","responsibility":"核对人员、场地、资源和已确认预案，明确异常时的联络与决策。交付：开场准入与预案记录。"},{"id":"p4_review","name":"演练与开场准入评审","phase":"演练与开场准入","kind":"decision","responsibility":"核对流程实测与应急协作并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p5_work1","name":"现场统筹与技术运行","phase":"现场执行","kind":"activity","responsibility":"统筹活动顺序、技术、嘉宾与供应，记录实际变更和事件。交付：现场运行与变更记录。"},{"id":"p5_work2","name":"参与服务与即时反馈","phase":"现场执行","kind":"activity","responsibility":"提供接待、支持和信息服务，登记参与反馈与需要升级的事项。交付：服务与参与反馈。"},{"id":"p5_review","name":"现场执行评审","phase":"现场执行","kind":"decision","responsibility":"核对实际流程、服务与问题处置并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p6_work1","name":"撤场接收与费用核对","phase":"撤场与结项","kind":"activity","responsibility":"核对设备、物料、场地交还与费用，记录未完成事项。交付：撤场与费用核对。"},{"id":"p6_work2","name":"成果与活动复盘","phase":"撤场与结项","kind":"activity","responsibility":"对照目标核对成果、参与反馈和事件，整理下一次改进建议。交付：活动成效与复盘。"},{"id":"p6_review","name":"撤场与结项评审","phase":"撤场与结项","kind":"decision","responsibility":"核对资源接收、结算与活动成效并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"exception_action","name":"现场应急与秩序恢复","phase":"异常处置与恢复","kind":"activity","responsibility":"现场责任人按已确认预案协调人员、场地和信息，记录处置及恢复状态；需要停办或调整时由有权人决定。"},{"id":"exception_review","name":"恢复与重新准入","phase":"异常处置与恢复","kind":"decision","responsibility":"核对异常影响、处置证据与恢复状态，明确哪些工作需要重新评审；获得有权人确认后再进入正常推进路径。"}],"edges":[{"from":"p1_work1","to":"p1_review","kind":"sequence","label":""},{"from":"p1_work2","to":"p1_review","kind":"sequence","label":""},{"from":"p1_review","to":"p1_work1","kind":"feedback","label":"未通过：修订"},{"from":"p1_review","to":"p2_work1","kind":"sequence","label":"通过"},{"from":"p1_review","to":"p2_work2","kind":"sequence","label":"通过"},{"from":"p2_work1","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work2","to":"p2_review","kind":"sequence","label":""},{"from":"p2_review","to":"p2_work1","kind":"feedback","label":"未通过：修订"},{"from":"p2_review","to":"p3_work1","kind":"sequence","label":"通过"},{"from":"p2_review","to":"p3_work2","kind":"sequence","label":"通过"},{"from":"p3_work1","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work2","to":"p3_review","kind":"sequence","label":""},{"from":"p3_review","to":"p3_work1","kind":"feedback","label":"未通过：修订"},{"from":"p3_review","to":"p4_work1","kind":"sequence","label":"通过"},{"from":"p4_work1","to":"p4_work2","kind":"sequence","label":""},{"from":"p4_work2","to":"p4_review","kind":"sequence","label":""},{"from":"p4_review","to":"p4_work1","kind":"feedback","label":"未通过：修订"},{"from":"p4_review","to":"p5_work1","kind":"sequence","label":"通过"},{"from":"p4_review","to":"p5_work2","kind":"sequence","label":"通过"},{"from":"p5_work1","to":"p5_review","kind":"sequence","label":""},{"from":"p5_work2","to":"p5_review","kind":"sequence","label":""},{"from":"p5_review","to":"p5_work1","kind":"feedback","label":"未通过：修订"},{"from":"p5_review","to":"p6_work1","kind":"sequence","label":"通过"},{"from":"p5_review","to":"p6_work2","kind":"sequence","label":"通过"},{"from":"p6_work1","to":"p6_review","kind":"sequence","label":""},{"from":"p6_work2","to":"p6_review","kind":"sequence","label":""},{"from":"p6_review","to":"p6_work1","kind":"feedback","label":"未通过：修订"},{"from":"p5_review","to":"exception_action","kind":"sequence","label":"异常：专项处置"},{"from":"exception_action","to":"exception_review","kind":"sequence","label":""},{"from":"exception_review","to":"p4_work1","kind":"feedback","label":"确认后重新评审"}]}'::jsonb),
('event-delivery-advanced','0657628fc498a8888996bdb635b57c8d','{"nodes":[{"id":"p1_work1","name":"Event goals and audience","phase":"Goals and scope","kind":"activity","responsibility":"Define purpose, participants, scale and outcomes with measures of success. Deliver: event goals and audience brief."},{"id":"p1_work2","name":"Budget and risk assessment","phase":"Goals and scope","kind":"activity","responsibility":"Review budget, schedule, venue conditions and risks with organizational ownership. Deliver: budget and risk register."},{"id":"p1_review","name":"Goals and scope review","phase":"Goals and scope","kind":"decision","responsibility":"Review event value, audience and resource boundaries and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p2_work1","name":"Program and content planning","phase":"Program and coordination","kind":"activity","responsibility":"Design content, sequence, guests and participation with key transitions and waits. Deliver: event program and running order."},{"id":"p2_work2","name":"Team and supplier coordination","phase":"Program and coordination","kind":"activity","responsibility":"Coordinate venue, suppliers, people and handoffs with service requirements. Deliver: team and supplier arrangements."},{"id":"p2_review","name":"Program and coordination review","phase":"Program and coordination","kind":"decision","responsibility":"Review program sequence and responsibilities and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p3_work1","name":"Venue, materials and technical preparation","phase":"Parallel resource preparation","kind":"activity","responsibility":"Check setup, equipment, materials, signage and technical systems and record readiness gaps. Deliver: site resource checks."},{"id":"p3_work2","name":"Guests and participant services","phase":"Parallel resource preparation","kind":"activity","responsibility":"Confirm guests, registration, reception, travel and participant information with special requirements. Deliver: participant and service checklist."},{"id":"p3_review","name":"Parallel resource preparation review","phase":"Parallel resource preparation","kind":"decision","responsibility":"Review site resources and participant services and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p4_work1","name":"Full rehearsal and corrections","phase":"Rehearsal and opening readiness","kind":"activity","responsibility":"Rehearse transitions, media, reception and responsibilities and correct operational discrepancies. Deliver: rehearsal record and corrections."},{"id":"p4_work2","name":"Site checks and response confirmation","phase":"Rehearsal and opening readiness","kind":"activity","responsibility":"Check people, venue, resources and response plans with communication and decision ownership. Deliver: opening readiness and response record."},{"id":"p4_review","name":"Rehearsal and opening readiness review","phase":"Rehearsal and opening readiness","kind":"decision","responsibility":"Review rehearsal evidence and response coordination and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p5_work1","name":"Site coordination and technical operation","phase":"On-site execution","kind":"activity","responsibility":"Coordinate program, technology, guests and suppliers and record changes and events. Deliver: site operation and change record."},{"id":"p5_work2","name":"Participant services and feedback","phase":"On-site execution","kind":"activity","responsibility":"Provide reception, support and information and record feedback and escalation needs. Deliver: service and participant feedback."},{"id":"p5_review","name":"On-site execution review","phase":"On-site execution","kind":"decision","responsibility":"Review actual program, services and issue handling and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p6_work1","name":"Demobilization and reconciliation","phase":"Demobilization and closure","kind":"activity","responsibility":"Verify equipment, materials, venue return and costs and record remaining items. Deliver: demobilization and reconciliation."},{"id":"p6_work2","name":"Results and event retrospective","phase":"Demobilization and closure","kind":"activity","responsibility":"Review results, participant feedback and incidents against goals and propose improvements. Deliver: event results and retrospective."},{"id":"p6_review","name":"Demobilization and closure review","phase":"Demobilization and closure","kind":"decision","responsibility":"Review resource receipt, reconciliation and event results and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"exception_action","name":"On-site response and recovery","phase":"Exceptions and recovery","kind":"activity","responsibility":"Assigned staff coordinate people, venue and information under the approved response plan and record recovery; authorized humans decide suspension or changes."},{"id":"exception_review","name":"Recovery and readiness review","phase":"Exceptions and recovery","kind":"decision","responsibility":"Check impact, response evidence and recovery status. Identify reviews to repeat and obtain authorized confirmation before resuming."}],"edges":[{"from":"p1_work1","to":"p1_review","kind":"sequence","label":""},{"from":"p1_work2","to":"p1_review","kind":"sequence","label":""},{"from":"p1_review","to":"p1_work1","kind":"feedback","label":"Needs revision"},{"from":"p1_review","to":"p2_work1","kind":"sequence","label":"Accepted"},{"from":"p1_review","to":"p2_work2","kind":"sequence","label":"Accepted"},{"from":"p2_work1","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work2","to":"p2_review","kind":"sequence","label":""},{"from":"p2_review","to":"p2_work1","kind":"feedback","label":"Needs revision"},{"from":"p2_review","to":"p3_work1","kind":"sequence","label":"Accepted"},{"from":"p2_review","to":"p3_work2","kind":"sequence","label":"Accepted"},{"from":"p3_work1","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work2","to":"p3_review","kind":"sequence","label":""},{"from":"p3_review","to":"p3_work1","kind":"feedback","label":"Needs revision"},{"from":"p3_review","to":"p4_work1","kind":"sequence","label":"Accepted"},{"from":"p4_work1","to":"p4_work2","kind":"sequence","label":""},{"from":"p4_work2","to":"p4_review","kind":"sequence","label":""},{"from":"p4_review","to":"p4_work1","kind":"feedback","label":"Needs revision"},{"from":"p4_review","to":"p5_work1","kind":"sequence","label":"Accepted"},{"from":"p4_review","to":"p5_work2","kind":"sequence","label":"Accepted"},{"from":"p5_work1","to":"p5_review","kind":"sequence","label":""},{"from":"p5_work2","to":"p5_review","kind":"sequence","label":""},{"from":"p5_review","to":"p5_work1","kind":"feedback","label":"Needs revision"},{"from":"p5_review","to":"p6_work1","kind":"sequence","label":"Accepted"},{"from":"p5_review","to":"p6_work2","kind":"sequence","label":"Accepted"},{"from":"p6_work1","to":"p6_review","kind":"sequence","label":""},{"from":"p6_work2","to":"p6_review","kind":"sequence","label":""},{"from":"p6_review","to":"p6_work1","kind":"feedback","label":"Needs revision"},{"from":"p5_review","to":"exception_action","kind":"sequence","label":"Exception response"},{"from":"exception_action","to":"exception_review","kind":"sequence","label":""},{"from":"exception_review","to":"p4_work1","kind":"feedback","label":"Confirmed re-review"}]}'::jsonb),
('consulting-delivery-advanced','5d20135ad5edc617629f81f829937c63','{"nodes":[{"id":"p1_work1","name":"客户问题与期望成果","phase":"委托与工作边界","kind":"activity","responsibility":"澄清客户问题、成果用途和验收方式，记录相关利益方与限制。交付：客户目标与成果说明。"},{"id":"p1_work2","name":"范围与协作约定","phase":"委托与工作边界","kind":"activity","responsibility":"约定范围、方法、资料、协作、交付和变更处理，明确双方责任。交付：可审阅工作约定。"},{"id":"p1_review","name":"委托与工作边界评审","phase":"委托与工作边界","kind":"decision","responsibility":"核对客户目标与双方职责并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p2_work1","name":"资料访谈与现场调查","phase":"诊断与证据","kind":"activity","responsibility":"收集资料、访谈及业务现状，保留来源、假设和相互矛盾的信息。交付：诊断材料与调查记录。"},{"id":"p2_work2","name":"现状与根因分析","phase":"诊断与证据","kind":"activity","responsibility":"整理流程、数据和组织问题，验证根因假设与问题影响。交付：现状诊断与根因说明。"},{"id":"p2_review","name":"诊断与证据评审","phase":"诊断与证据","kind":"decision","responsibility":"核对资料可信度与问题解释并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p3_work1","name":"方案路线与效果评估","phase":"方案与决策依据","kind":"activity","responsibility":"提出可比较方案，说明收益、限制、风险和对客户组织的影响。交付：候选方案与比较。"},{"id":"p3_work2","name":"实施路径与资源评估","phase":"方案与决策依据","kind":"activity","responsibility":"评估资源、依赖、分工和试点方式，说明实施中的关键假设。交付：实施路径与资源计划。"},{"id":"p3_review","name":"方案与决策依据评审","phase":"方案与决策依据","kind":"decision","responsibility":"核对方案比较与实施可行性并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p4_work1","name":"试点实施与观察","phase":"试点与调整","kind":"activity","responsibility":"客户与实施人员执行确认的试点，记录操作、结果和偏差。交付：试点与观察记录。"},{"id":"p4_work2","name":"试点验证与方案修订","phase":"试点与调整","kind":"activity","responsibility":"核对试点目标、客户反馈和适用范围，修订方案与后续实施计划。交付：试点验证与修订方案。"},{"id":"p4_review","name":"试点与调整评审","phase":"试点与调整","kind":"decision","responsibility":"核对试点证据与可执行改进并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p5_work1","name":"落地支持与成果核对","phase":"落地与客户验收","kind":"activity","responsibility":"支持客户落实确认方案，核对实际成果、剩余风险与变更。交付：实施成果与问题清单。"},{"id":"p5_work2","name":"客户审阅与验收依据","phase":"落地与客户验收","kind":"activity","responsibility":"与客户核对范围、成果和证据，列出需补充或另行安排的事项。交付：客户审阅与验收记录。"},{"id":"p5_review","name":"落地与客户验收评审","phase":"落地与客户验收","kind":"decision","responsibility":"核对客户成果与人员可接收性并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p6_work1","name":"资料培训与责任交接","phase":"知识转移与结项","kind":"activity","responsibility":"交付方法、资料、培训和维护责任，检查客户能否继续使用成果。交付：知识转移与接收记录。"},{"id":"p6_work2","name":"委托关闭与收益跟踪","phase":"知识转移与结项","kind":"activity","responsibility":"核对交付、未完成项与双方意见，确定后续收益观察和改进安排。交付：结项与收益观察计划。"},{"id":"p6_review","name":"知识转移与结项评审","phase":"知识转移与结项","kind":"decision","responsibility":"核对接收、使用能力与委托关闭并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"exception_action","name":"需求变更与范围重估","phase":"异常处置与恢复","kind":"activity","responsibility":"记录新增问题、影响和客户意见，重新评估范围、交付物与资源，由委托双方明确后续安排。"},{"id":"exception_review","name":"恢复与重新准入","phase":"异常处置与恢复","kind":"decision","responsibility":"核对异常影响、处置证据与恢复状态，明确哪些工作需要重新评审；获得有权人确认后再进入正常推进路径。"}],"edges":[{"from":"p1_work1","to":"p1_review","kind":"sequence","label":""},{"from":"p1_work2","to":"p1_review","kind":"sequence","label":""},{"from":"p1_review","to":"p1_work1","kind":"feedback","label":"未通过：修订"},{"from":"p1_review","to":"p2_work1","kind":"sequence","label":"通过"},{"from":"p1_review","to":"p2_work2","kind":"sequence","label":"通过"},{"from":"p2_work1","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work2","to":"p2_review","kind":"sequence","label":""},{"from":"p2_review","to":"p2_work1","kind":"feedback","label":"未通过：修订"},{"from":"p2_review","to":"p3_work1","kind":"sequence","label":"通过"},{"from":"p2_review","to":"p3_work2","kind":"sequence","label":"通过"},{"from":"p3_work1","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work2","to":"p3_review","kind":"sequence","label":""},{"from":"p3_review","to":"p3_work1","kind":"feedback","label":"未通过：修订"},{"from":"p3_review","to":"p4_work1","kind":"sequence","label":"通过"},{"from":"p4_work1","to":"p4_work2","kind":"sequence","label":""},{"from":"p4_work2","to":"p4_review","kind":"sequence","label":""},{"from":"p4_review","to":"p4_work1","kind":"feedback","label":"未通过：修订"},{"from":"p4_review","to":"p5_work1","kind":"sequence","label":"通过"},{"from":"p4_review","to":"p5_work2","kind":"sequence","label":"通过"},{"from":"p5_work1","to":"p5_review","kind":"sequence","label":""},{"from":"p5_work2","to":"p5_review","kind":"sequence","label":""},{"from":"p5_review","to":"p5_work1","kind":"feedback","label":"未通过：修订"},{"from":"p5_review","to":"p6_work1","kind":"sequence","label":"通过"},{"from":"p5_review","to":"p6_work2","kind":"sequence","label":"通过"},{"from":"p6_work1","to":"p6_review","kind":"sequence","label":""},{"from":"p6_work2","to":"p6_review","kind":"sequence","label":""},{"from":"p6_review","to":"p6_work1","kind":"feedback","label":"未通过：修订"},{"from":"p5_review","to":"exception_action","kind":"sequence","label":"异常：专项处置"},{"from":"exception_action","to":"exception_review","kind":"sequence","label":""},{"from":"exception_review","to":"p2_work1","kind":"feedback","label":"确认后重新评审"}]}'::jsonb),
('consulting-delivery-advanced','5de834e7e24fde0a60fedd598b72f959','{"nodes":[{"id":"p1_work1","name":"Client problem and expected outcomes","phase":"Engagement and boundaries","kind":"activity","responsibility":"Clarify the problem, intended use and acceptance with stakeholders and constraints. Deliver: client goals and outcomes."},{"id":"p1_work2","name":"Scope and working agreement","phase":"Engagement and boundaries","kind":"activity","responsibility":"Agree scope, methods, information, collaboration, delivery and change handling with ownership. Deliver: reviewable engagement agreement."},{"id":"p1_review","name":"Engagement and boundaries review","phase":"Engagement and boundaries","kind":"decision","responsibility":"Review client goals and agreed responsibilities and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p2_work1","name":"Information, interviews and observation","phase":"Diagnosis and evidence","kind":"activity","responsibility":"Collect materials, interviews and operational observations with sources, assumptions and contradictions. Deliver: diagnostic materials and investigation notes."},{"id":"p2_work2","name":"Current state and root-cause analysis","phase":"Diagnosis and evidence","kind":"activity","responsibility":"Analyze process, data and organizational issues and validate root-cause hypotheses and impact. Deliver: current-state diagnosis and root causes."},{"id":"p2_review","name":"Diagnosis and evidence review","phase":"Diagnosis and evidence","kind":"decision","responsibility":"Review evidence reliability and problem explanation and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p3_work1","name":"Options and expected outcomes","phase":"Options and decision evidence","kind":"activity","responsibility":"Develop comparable options with expected outcomes, limits, risks and organizational impact. Deliver: options and comparison."},{"id":"p3_work2","name":"Implementation and resource assessment","phase":"Options and decision evidence","kind":"activity","responsibility":"Assess resources, dependencies, responsibilities and pilots with implementation assumptions. Deliver: implementation and resource plan."},{"id":"p3_review","name":"Options and decision evidence review","phase":"Options and decision evidence","kind":"decision","responsibility":"Review option comparison and implementation feasibility and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p4_work1","name":"Pilot implementation and observation","phase":"Pilot and adjustments","kind":"activity","responsibility":"Client and delivery staff execute the approved pilot and record actions, results and deviations. Deliver: pilot and observation record."},{"id":"p4_work2","name":"Pilot verification and revision","phase":"Pilot and adjustments","kind":"activity","responsibility":"Verify pilot goals, client feedback and applicability and revise implementation plans. Deliver: pilot verification and revised proposal."},{"id":"p4_review","name":"Pilot and adjustments review","phase":"Pilot and adjustments","kind":"decision","responsibility":"Review pilot evidence and actionable adjustments and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p5_work1","name":"Implementation support and result checks","phase":"Implementation and client acceptance","kind":"activity","responsibility":"Support agreed implementation and verify results, remaining risks and changes. Deliver: implementation results and issues."},{"id":"p5_work2","name":"Client review and acceptance evidence","phase":"Implementation and client acceptance","kind":"activity","responsibility":"Review scope, results and evidence with the client and identify supplements and follow-up work. Deliver: client review and acceptance record."},{"id":"p5_review","name":"Implementation and client acceptance review","phase":"Implementation and client acceptance","kind":"decision","responsibility":"Review client results and receiving-team readiness and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p6_work1","name":"Materials, training and ownership handoff","phase":"Knowledge transfer and closure","kind":"activity","responsibility":"Transfer methods, materials, training and maintenance ownership and verify continued use. Deliver: knowledge transfer and receipt."},{"id":"p6_work2","name":"Closure and benefits review","phase":"Knowledge transfer and closure","kind":"activity","responsibility":"Review deliverables, open items and both parties’ findings and agree further benefits observation. Deliver: closure and benefits observation plan."},{"id":"p6_review","name":"Knowledge transfer and closure review","phase":"Knowledge transfer and closure","kind":"decision","responsibility":"Review receipt, usable knowledge and engagement closure and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"exception_action","name":"Requirements change and scope reassessment","phase":"Exceptions and recovery","kind":"activity","responsibility":"Record new issues and client feedback and reassess scope, deliverables and resources for agreed follow-up."},{"id":"exception_review","name":"Recovery and readiness review","phase":"Exceptions and recovery","kind":"decision","responsibility":"Check impact, response evidence and recovery status. Identify reviews to repeat and obtain authorized confirmation before resuming."}],"edges":[{"from":"p1_work1","to":"p1_review","kind":"sequence","label":""},{"from":"p1_work2","to":"p1_review","kind":"sequence","label":""},{"from":"p1_review","to":"p1_work1","kind":"feedback","label":"Needs revision"},{"from":"p1_review","to":"p2_work1","kind":"sequence","label":"Accepted"},{"from":"p1_review","to":"p2_work2","kind":"sequence","label":"Accepted"},{"from":"p2_work1","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work2","to":"p2_review","kind":"sequence","label":""},{"from":"p2_review","to":"p2_work1","kind":"feedback","label":"Needs revision"},{"from":"p2_review","to":"p3_work1","kind":"sequence","label":"Accepted"},{"from":"p2_review","to":"p3_work2","kind":"sequence","label":"Accepted"},{"from":"p3_work1","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work2","to":"p3_review","kind":"sequence","label":""},{"from":"p3_review","to":"p3_work1","kind":"feedback","label":"Needs revision"},{"from":"p3_review","to":"p4_work1","kind":"sequence","label":"Accepted"},{"from":"p4_work1","to":"p4_work2","kind":"sequence","label":""},{"from":"p4_work2","to":"p4_review","kind":"sequence","label":""},{"from":"p4_review","to":"p4_work1","kind":"feedback","label":"Needs revision"},{"from":"p4_review","to":"p5_work1","kind":"sequence","label":"Accepted"},{"from":"p4_review","to":"p5_work2","kind":"sequence","label":"Accepted"},{"from":"p5_work1","to":"p5_review","kind":"sequence","label":""},{"from":"p5_work2","to":"p5_review","kind":"sequence","label":""},{"from":"p5_review","to":"p5_work1","kind":"feedback","label":"Needs revision"},{"from":"p5_review","to":"p6_work1","kind":"sequence","label":"Accepted"},{"from":"p5_review","to":"p6_work2","kind":"sequence","label":"Accepted"},{"from":"p6_work1","to":"p6_review","kind":"sequence","label":""},{"from":"p6_work2","to":"p6_review","kind":"sequence","label":""},{"from":"p6_review","to":"p6_work1","kind":"feedback","label":"Needs revision"},{"from":"p5_review","to":"exception_action","kind":"sequence","label":"Exception response"},{"from":"exception_action","to":"exception_review","kind":"sequence","label":""},{"from":"exception_review","to":"p2_work1","kind":"feedback","label":"Confirmed re-review"}]}'::jsonb),
('hardware-development-advanced','1febda5b254d2507dce677cef4fd7af0','{"nodes":[{"id":"p1_work1","name":"使用场景与需求基线","phase":"需求与系统边界","kind":"activity","responsibility":"明确功能、使用环境、性能、约束和可验证要求，记录验收依据。交付：系统需求与验收基线。"},{"id":"p1_work2","name":"系统分解与接口","phase":"需求与系统边界","kind":"activity","responsibility":"分解子系统、接口和责任边界，核对外部系统及供应依赖。交付：系统分解与接口说明。"},{"id":"p1_review","name":"需求与系统边界评审","phase":"需求与系统边界","kind":"decision","responsibility":"核对需求、使用场景与接口边界并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p2_work1","name":"结构与工业设计","phase":"并行设计","kind":"activity","responsibility":"设计结构、材料、装配和使用体验，核对与电子及生产的接口。交付：结构与工业设计资料。"},{"id":"p2_work2","name":"电子与固件设计","phase":"并行设计","kind":"activity","responsibility":"设计电子与固件方案，核对接口、功耗、异常和调试策略。交付：电子与固件方案。"},{"id":"p2_review","name":"并行设计评审","phase":"并行设计","kind":"decision","responsibility":"核对设计方案、接口与风险并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p3_work1","name":"样机制作与配置登记","phase":"样机与集成","kind":"activity","responsibility":"按设计制作样机，登记部件、版本、装配和已知偏差。交付：样机配置与制作记录。"},{"id":"p3_work2","name":"子系统与接口集成","phase":"样机与集成","kind":"activity","responsibility":"按集成计划核对子系统接口、顺序、测试准备和实际连接结果。交付：系统集成与接口证据。"},{"id":"p3_review","name":"样机与集成评审","phase":"样机与集成","kind":"decision","responsibility":"核对样机、集成配置与接口结果并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p4_work1","name":"功能性能与可靠性验证","phase":"需求验证与使用确认","kind":"activity","responsibility":"对照需求验证功能、性能和相关失效风险，保留可核对的测试配置。交付：需求验证与失效记录。"},{"id":"p4_work2","name":"使用场景与人机验证","phase":"需求验证与使用确认","kind":"activity","responsibility":"在适用环境检查使用、维护和操作表现，记录需求以外的使用问题。交付：场景验证与使用反馈。"},{"id":"p4_review","name":"需求验证与使用确认评审","phase":"需求验证与使用确认","kind":"decision","responsibility":"核对要求满足情况与实际场景表现并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p5_work1","name":"工艺治具与生产准备","phase":"工艺与试产","kind":"activity","responsibility":"准备工艺、治具、操作资料及部件供应，核对可制造性。交付：生产工艺与准备资料。"},{"id":"p5_work2","name":"试产与质量验证","phase":"工艺与试产","kind":"activity","responsibility":"进行经确认的试产，核对良率、测量、装配和生产偏差。交付：试产与质量验证结果。"},{"id":"p5_review","name":"工艺与试产评审","phase":"工艺与试产","kind":"decision","responsibility":"核对可制造性、工艺与质量计划并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p6_work1","name":"制造资料与责任转移","phase":"制造转移与维护","kind":"activity","responsibility":"交付确认的设计、配置、工艺和质量资料，核对制造与服务接收。交付：制造转移与接收记录。"},{"id":"p6_work2","name":"失效反馈与设计维护","phase":"制造转移与维护","kind":"activity","responsibility":"登记使用和生产失效，核对影响后提出设计、测试或工艺改进。交付：设计维护与改进记录。"},{"id":"p6_review","name":"制造转移与维护评审","phase":"制造转移与维护","kind":"decision","responsibility":"核对制造接收与版本维护并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"exception_action","name":"样机失效与设计纠正","phase":"异常处置与恢复","kind":"activity","responsibility":"隔离故障样机，核对失效、接口和变更证据，确认需要调整的设计与重新验证范围。"},{"id":"exception_review","name":"恢复与重新准入","phase":"异常处置与恢复","kind":"decision","responsibility":"核对异常影响、处置证据与恢复状态，明确哪些工作需要重新评审；获得有权人确认后再进入正常推进路径。"}],"edges":[{"from":"p1_work1","to":"p1_review","kind":"sequence","label":""},{"from":"p1_work2","to":"p1_review","kind":"sequence","label":""},{"from":"p1_review","to":"p1_work1","kind":"feedback","label":"未通过：修订"},{"from":"p1_review","to":"p2_work1","kind":"sequence","label":"通过"},{"from":"p1_review","to":"p2_work2","kind":"sequence","label":"通过"},{"from":"p2_work1","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work2","to":"p2_review","kind":"sequence","label":""},{"from":"p2_review","to":"p2_work1","kind":"feedback","label":"未通过：修订"},{"from":"p2_review","to":"p3_work1","kind":"sequence","label":"通过"},{"from":"p2_review","to":"p3_work2","kind":"sequence","label":"通过"},{"from":"p3_work1","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work2","to":"p3_review","kind":"sequence","label":""},{"from":"p3_review","to":"p3_work1","kind":"feedback","label":"未通过：修订"},{"from":"p3_review","to":"p4_work1","kind":"sequence","label":"通过"},{"from":"p3_review","to":"p4_work2","kind":"sequence","label":"通过"},{"from":"p4_work1","to":"p4_review","kind":"sequence","label":""},{"from":"p4_work2","to":"p4_review","kind":"sequence","label":""},{"from":"p4_review","to":"p4_work1","kind":"feedback","label":"未通过：修订"},{"from":"p4_review","to":"p5_work1","kind":"sequence","label":"通过"},{"from":"p4_review","to":"p5_work2","kind":"sequence","label":"通过"},{"from":"p5_work1","to":"p5_review","kind":"sequence","label":""},{"from":"p5_work2","to":"p5_review","kind":"sequence","label":""},{"from":"p5_review","to":"p5_work1","kind":"feedback","label":"未通过：修订"},{"from":"p5_review","to":"p6_work1","kind":"sequence","label":"通过"},{"from":"p5_review","to":"p6_work2","kind":"sequence","label":"通过"},{"from":"p6_work1","to":"p6_review","kind":"sequence","label":""},{"from":"p6_work2","to":"p6_review","kind":"sequence","label":""},{"from":"p6_review","to":"p6_work1","kind":"feedback","label":"未通过：修订"},{"from":"p4_review","to":"exception_action","kind":"sequence","label":"异常：专项处置"},{"from":"exception_action","to":"exception_review","kind":"sequence","label":""},{"from":"exception_review","to":"p2_work1","kind":"feedback","label":"确认后重新评审"}]}'::jsonb),
('hardware-development-advanced','4afad2cc265b21fccf25f5cda4ee3eec','{"nodes":[{"id":"p1_work1","name":"Use cases and requirements baseline","phase":"Requirements and system boundaries","kind":"activity","responsibility":"Define functions, environments, performance, constraints and verifiable requirements with acceptance evidence. Deliver: system requirements and acceptance baseline."},{"id":"p1_work2","name":"System breakdown and interfaces","phase":"Requirements and system boundaries","kind":"activity","responsibility":"Break down subsystems, interfaces and ownership and assess external dependencies. Deliver: system decomposition and interface notes."},{"id":"p1_review","name":"Requirements and system boundaries review","phase":"Requirements and system boundaries","kind":"decision","responsibility":"Review requirements, use cases and interface boundaries and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p2_work1","name":"Mechanical and industrial design","phase":"Parallel design","kind":"activity","responsibility":"Design mechanics, materials, assembly and experience and verify electronic and manufacturing interfaces. Deliver: mechanical and industrial design."},{"id":"p2_work2","name":"Electronics and firmware design","phase":"Parallel design","kind":"activity","responsibility":"Design electronics and firmware with interfaces, power, failure handling and debugging strategies. Deliver: electronics and firmware proposal."},{"id":"p2_review","name":"Parallel design review","phase":"Parallel design","kind":"decision","responsibility":"Review design proposals, interfaces and risks and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p3_work1","name":"Prototype production and configuration","phase":"Prototypes and integration","kind":"activity","responsibility":"Produce prototypes and record components, versions, assembly and known deviations. Deliver: prototype configuration and production record."},{"id":"p3_work2","name":"Subsystem and interface integration","phase":"Prototypes and integration","kind":"activity","responsibility":"Check interfaces, order, testing readiness and integration results against the plan. Deliver: system integration and interface evidence."},{"id":"p3_review","name":"Prototypes and integration review","phase":"Prototypes and integration","kind":"decision","responsibility":"Review prototypes, integration configuration and interface results and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p4_work1","name":"Functional, performance and reliability checks","phase":"Verification and use validation","kind":"activity","responsibility":"Verify requirements, performance and failure risks with identifiable test configurations. Deliver: requirements verification and failure record."},{"id":"p4_work2","name":"Use-case and human validation","phase":"Verification and use validation","kind":"activity","responsibility":"Validate use, maintenance and operation in applicable environments and record unexpected usability issues. Deliver: use validation and feedback."},{"id":"p4_review","name":"Verification and use validation review","phase":"Verification and use validation","kind":"decision","responsibility":"Review requirements satisfaction and realistic use performance and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p5_work1","name":"Process, tooling and production readiness","phase":"Process and pilot production","kind":"activity","responsibility":"Prepare processes, tooling, work materials and component supply and review manufacturability. Deliver: production process and readiness materials."},{"id":"p5_work2","name":"Pilot production and quality validation","phase":"Process and pilot production","kind":"activity","responsibility":"Run approved pilot production and check yield, measurement, assembly and process deviations. Deliver: pilot production and quality evidence."},{"id":"p5_review","name":"Process and pilot production review","phase":"Process and pilot production","kind":"decision","responsibility":"Review manufacturability, process and quality plans and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p6_work1","name":"Manufacturing materials and ownership transfer","phase":"Manufacturing transfer and maintenance","kind":"activity","responsibility":"Transfer approved designs, configurations, processes and quality materials and confirm receipt. Deliver: manufacturing transfer and receipt."},{"id":"p6_work2","name":"Failure feedback and design maintenance","phase":"Manufacturing transfer and maintenance","kind":"activity","responsibility":"Track operational and production failures and propose design, testing or process improvements after impact review. Deliver: design maintenance and improvements."},{"id":"p6_review","name":"Manufacturing transfer and maintenance review","phase":"Manufacturing transfer and maintenance","kind":"decision","responsibility":"Review manufacturing receipt and version maintenance and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"exception_action","name":"Prototype failure and design correction","phase":"Exceptions and recovery","kind":"activity","responsibility":"Isolate failed prototypes, inspect failure and interface evidence, and define design corrections and repeat checks."},{"id":"exception_review","name":"Recovery and readiness review","phase":"Exceptions and recovery","kind":"decision","responsibility":"Check impact, response evidence and recovery status. Identify reviews to repeat and obtain authorized confirmation before resuming."}],"edges":[{"from":"p1_work1","to":"p1_review","kind":"sequence","label":""},{"from":"p1_work2","to":"p1_review","kind":"sequence","label":""},{"from":"p1_review","to":"p1_work1","kind":"feedback","label":"Needs revision"},{"from":"p1_review","to":"p2_work1","kind":"sequence","label":"Accepted"},{"from":"p1_review","to":"p2_work2","kind":"sequence","label":"Accepted"},{"from":"p2_work1","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work2","to":"p2_review","kind":"sequence","label":""},{"from":"p2_review","to":"p2_work1","kind":"feedback","label":"Needs revision"},{"from":"p2_review","to":"p3_work1","kind":"sequence","label":"Accepted"},{"from":"p2_review","to":"p3_work2","kind":"sequence","label":"Accepted"},{"from":"p3_work1","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work2","to":"p3_review","kind":"sequence","label":""},{"from":"p3_review","to":"p3_work1","kind":"feedback","label":"Needs revision"},{"from":"p3_review","to":"p4_work1","kind":"sequence","label":"Accepted"},{"from":"p3_review","to":"p4_work2","kind":"sequence","label":"Accepted"},{"from":"p4_work1","to":"p4_review","kind":"sequence","label":""},{"from":"p4_work2","to":"p4_review","kind":"sequence","label":""},{"from":"p4_review","to":"p4_work1","kind":"feedback","label":"Needs revision"},{"from":"p4_review","to":"p5_work1","kind":"sequence","label":"Accepted"},{"from":"p4_review","to":"p5_work2","kind":"sequence","label":"Accepted"},{"from":"p5_work1","to":"p5_review","kind":"sequence","label":""},{"from":"p5_work2","to":"p5_review","kind":"sequence","label":""},{"from":"p5_review","to":"p5_work1","kind":"feedback","label":"Needs revision"},{"from":"p5_review","to":"p6_work1","kind":"sequence","label":"Accepted"},{"from":"p5_review","to":"p6_work2","kind":"sequence","label":"Accepted"},{"from":"p6_work1","to":"p6_review","kind":"sequence","label":""},{"from":"p6_work2","to":"p6_review","kind":"sequence","label":""},{"from":"p6_review","to":"p6_work1","kind":"feedback","label":"Needs revision"},{"from":"p4_review","to":"exception_action","kind":"sequence","label":"Exception response"},{"from":"exception_action","to":"exception_review","kind":"sequence","label":""},{"from":"exception_review","to":"p2_work1","kind":"feedback","label":"Confirmed re-review"}]}'::jsonb),
('manufacturing-quality-advanced','2e6c510e5dc43db4215e873be9e24593','{"nodes":[{"id":"p1_work1","name":"生产需求与交付计划","phase":"生产需求与质量目标","kind":"activity","responsibility":"核对数量、产品版本、交期和产能，记录优先级与约束。交付：生产需求与交付计划。"},{"id":"p1_work2","name":"质量要求与风险分析","phase":"生产需求与质量目标","kind":"activity","responsibility":"明确质量特性、检验依据和过程风险，登记关键控制点。交付：质量目标与风险清单。"},{"id":"p1_review","name":"生产需求与质量目标评审","phase":"生产需求与质量目标","kind":"decision","responsibility":"核对需求、产能与质量要求并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p2_work1","name":"流程工艺与作业指导","phase":"工艺与控制设计","kind":"activity","responsibility":"设计工序、作业与交接方式，核对材料、设备和关键参数。交付：工艺流程与作业指导。"},{"id":"p2_work2","name":"测量与控制计划","phase":"工艺与控制设计","kind":"activity","responsibility":"确定测量、抽检、异常处理和记录要求，明确检验与放行责任。交付：测量与控制计划。"},{"id":"p2_review","name":"工艺与控制设计评审","phase":"工艺与控制设计","kind":"decision","responsibility":"核对工艺、测量与控制方案并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p3_work1","name":"供应与来料检查","phase":"并行生产准备","kind":"activity","responsibility":"核对材料与部件的版本、批次、数量和来料检验状态。交付：材料与来料检查。"},{"id":"p3_work2","name":"设备工装与人员准备","phase":"并行生产准备","kind":"activity","responsibility":"检查设备、工装、维护、校验和人员作业能力，登记缺项。交付：设备与人员就绪记录。"},{"id":"p3_review","name":"并行生产准备评审","phase":"并行生产准备","kind":"decision","responsibility":"核对材料、设备与人员就绪并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p4_work1","name":"试产与过程验证","phase":"试产与准入","kind":"activity","responsibility":"按确认流程试产，记录工序结果、测量、良率和异常。交付：试产与过程验证记录。"},{"id":"p4_work2","name":"质量复核与工艺修订","phase":"试产与准入","kind":"activity","responsibility":"核对关键质量与过程能力，落实工艺、控制计划和操作修订。交付：生产准入与修订记录。"},{"id":"p4_review","name":"试产与准入评审","phase":"试产与准入","kind":"decision","responsibility":"核对试产、能力与修订闭合并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p5_work1","name":"生产执行与过程记录","phase":"生产与检验","kind":"activity","responsibility":"成员按确认安排生产，记录批次、材料、参数、工序与偏差。交付：生产追溯与过程记录。"},{"id":"p5_work2","name":"过程与成品检验","phase":"生产与检验","kind":"activity","responsibility":"核对关键工序、产品和质量证据，对不合格项登记并升级处理。交付：检验结果与质量问题。"},{"id":"p5_review","name":"生产与检验评审","phase":"生产与检验","kind":"decision","responsibility":"核对生产追溯与检验结果并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p6_work1","name":"放行入库与交付","phase":"放行交付与改进","kind":"activity","responsibility":"由有权人确认放行依据，核对入库、交付与客户要求。交付：放行与交付记录。"},{"id":"p6_work2","name":"质量反馈与改进","phase":"放行交付与改进","kind":"activity","responsibility":"汇集客户、过程和不合格反馈，提出控制计划与工艺改进。交付：质量复盘与改进计划。"},{"id":"p6_review","name":"放行交付与改进评审","phase":"放行交付与改进","kind":"decision","responsibility":"核对放行依据、客户接收与质量反馈并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"exception_action","name":"不合格隔离与返工","phase":"异常处置与恢复","kind":"activity","responsibility":"隔离受影响批次，记录缺陷、根因和处置意见，执行确认的返工并重新检验。"},{"id":"exception_review","name":"恢复与重新准入","phase":"异常处置与恢复","kind":"decision","responsibility":"核对异常影响、处置证据与恢复状态，明确哪些工作需要重新评审；获得有权人确认后再进入正常推进路径。"}],"edges":[{"from":"p1_work1","to":"p1_review","kind":"sequence","label":""},{"from":"p1_work2","to":"p1_review","kind":"sequence","label":""},{"from":"p1_review","to":"p1_work1","kind":"feedback","label":"未通过：修订"},{"from":"p1_review","to":"p2_work1","kind":"sequence","label":"通过"},{"from":"p1_review","to":"p2_work2","kind":"sequence","label":"通过"},{"from":"p2_work1","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work2","to":"p2_review","kind":"sequence","label":""},{"from":"p2_review","to":"p2_work1","kind":"feedback","label":"未通过：修订"},{"from":"p2_review","to":"p3_work1","kind":"sequence","label":"通过"},{"from":"p2_review","to":"p3_work2","kind":"sequence","label":"通过"},{"from":"p3_work1","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work2","to":"p3_review","kind":"sequence","label":""},{"from":"p3_review","to":"p3_work1","kind":"feedback","label":"未通过：修订"},{"from":"p3_review","to":"p4_work1","kind":"sequence","label":"通过"},{"from":"p4_work1","to":"p4_work2","kind":"sequence","label":""},{"from":"p4_work2","to":"p4_review","kind":"sequence","label":""},{"from":"p4_review","to":"p4_work1","kind":"feedback","label":"未通过：修订"},{"from":"p4_review","to":"p5_work1","kind":"sequence","label":"通过"},{"from":"p4_review","to":"p5_work2","kind":"sequence","label":"通过"},{"from":"p5_work1","to":"p5_review","kind":"sequence","label":""},{"from":"p5_work2","to":"p5_review","kind":"sequence","label":""},{"from":"p5_review","to":"p5_work1","kind":"feedback","label":"未通过：修订"},{"from":"p5_review","to":"p6_work1","kind":"sequence","label":"通过"},{"from":"p5_review","to":"p6_work2","kind":"sequence","label":"通过"},{"from":"p6_work1","to":"p6_review","kind":"sequence","label":""},{"from":"p6_work2","to":"p6_review","kind":"sequence","label":""},{"from":"p6_review","to":"p6_work1","kind":"feedback","label":"未通过：修订"},{"from":"p5_review","to":"exception_action","kind":"sequence","label":"异常：专项处置"},{"from":"exception_action","to":"exception_review","kind":"sequence","label":""},{"from":"exception_review","to":"p4_work1","kind":"feedback","label":"确认后重新评审"}]}'::jsonb),
('manufacturing-quality-advanced','1bebca55f890b48f5a741eef768b89de','{"nodes":[{"id":"p1_work1","name":"Demand and delivery planning","phase":"Demand and quality goals","kind":"activity","responsibility":"Check volumes, product versions, deadlines and capacity with priorities and constraints. Deliver: production demand and delivery plan."},{"id":"p1_work2","name":"Quality requirements and risk analysis","phase":"Demand and quality goals","kind":"activity","responsibility":"Define quality characteristics, inspection evidence and process risks with control points. Deliver: quality goals and risk register."},{"id":"p1_review","name":"Demand and quality goals review","phase":"Demand and quality goals","kind":"decision","responsibility":"Review demand, capacity and quality requirements and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p2_work1","name":"Process and work instructions","phase":"Process and control design","kind":"activity","responsibility":"Design operations and handoffs and verify materials, equipment and critical parameters. Deliver: process flow and work instructions."},{"id":"p2_work2","name":"Measurement and control plan","phase":"Process and control design","kind":"activity","responsibility":"Define measurement, sampling, exceptions and records with inspection and release ownership. Deliver: measurement and control plan."},{"id":"p2_review","name":"Process and control design review","phase":"Process and control design","kind":"decision","responsibility":"Review process, measurement and controls and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p3_work1","name":"Supply and incoming checks","phase":"Parallel production readiness","kind":"activity","responsibility":"Check material and component versions, batches, quantities and incoming inspection. Deliver: materials and incoming checks."},{"id":"p3_work2","name":"Equipment, tooling and staffing","phase":"Parallel production readiness","kind":"activity","responsibility":"Check equipment, tooling, maintenance, calibration and operator readiness and record gaps. Deliver: equipment and people readiness."},{"id":"p3_review","name":"Parallel production readiness review","phase":"Parallel production readiness","kind":"decision","responsibility":"Review materials, equipment and people readiness and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p4_work1","name":"Pilot and process validation","phase":"Pilot and production readiness","kind":"activity","responsibility":"Run an approved pilot and record process results, measurements, yield and exceptions. Deliver: pilot and process validation."},{"id":"p4_work2","name":"Quality review and process revision","phase":"Pilot and production readiness","kind":"activity","responsibility":"Review critical quality and capability and update processes, controls and instructions. Deliver: production readiness and revision record."},{"id":"p4_review","name":"Pilot and production readiness review","phase":"Pilot and production readiness","kind":"decision","responsibility":"Review pilot results, capability and closed revisions and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p5_work1","name":"Production execution and records","phase":"Production and inspection","kind":"activity","responsibility":"Operators follow approved arrangements and record batches, materials, parameters, operations and deviations. Deliver: production traceability and records."},{"id":"p5_work2","name":"In-process and final inspection","phase":"Production and inspection","kind":"activity","responsibility":"Inspect critical operations and final products and record nonconformance for disposition. Deliver: inspection results and quality issues."},{"id":"p5_review","name":"Production and inspection review","phase":"Production and inspection","kind":"decision","responsibility":"Review production traceability and inspection results and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p6_work1","name":"Release, storage and delivery","phase":"Release, delivery and improvement","kind":"activity","responsibility":"Authorized staff confirm release evidence and check storage, delivery and customer requirements. Deliver: release and delivery record."},{"id":"p6_work2","name":"Quality feedback and improvement","phase":"Release, delivery and improvement","kind":"activity","responsibility":"Combine customer, process and nonconformance feedback and propose control and process improvements. Deliver: quality review and improvement plan."},{"id":"p6_review","name":"Release, delivery and improvement review","phase":"Release, delivery and improvement","kind":"decision","responsibility":"Review release evidence, client receipt and quality feedback and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"exception_action","name":"Nonconformance containment and rework","phase":"Exceptions and recovery","kind":"activity","responsibility":"Contain affected batches, document defects and causes, apply approved rework and repeat inspection."},{"id":"exception_review","name":"Recovery and readiness review","phase":"Exceptions and recovery","kind":"decision","responsibility":"Check impact, response evidence and recovery status. Identify reviews to repeat and obtain authorized confirmation before resuming."}],"edges":[{"from":"p1_work1","to":"p1_review","kind":"sequence","label":""},{"from":"p1_work2","to":"p1_review","kind":"sequence","label":""},{"from":"p1_review","to":"p1_work1","kind":"feedback","label":"Needs revision"},{"from":"p1_review","to":"p2_work1","kind":"sequence","label":"Accepted"},{"from":"p1_review","to":"p2_work2","kind":"sequence","label":"Accepted"},{"from":"p2_work1","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work2","to":"p2_review","kind":"sequence","label":""},{"from":"p2_review","to":"p2_work1","kind":"feedback","label":"Needs revision"},{"from":"p2_review","to":"p3_work1","kind":"sequence","label":"Accepted"},{"from":"p2_review","to":"p3_work2","kind":"sequence","label":"Accepted"},{"from":"p3_work1","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work2","to":"p3_review","kind":"sequence","label":""},{"from":"p3_review","to":"p3_work1","kind":"feedback","label":"Needs revision"},{"from":"p3_review","to":"p4_work1","kind":"sequence","label":"Accepted"},{"from":"p4_work1","to":"p4_work2","kind":"sequence","label":""},{"from":"p4_work2","to":"p4_review","kind":"sequence","label":""},{"from":"p4_review","to":"p4_work1","kind":"feedback","label":"Needs revision"},{"from":"p4_review","to":"p5_work1","kind":"sequence","label":"Accepted"},{"from":"p4_review","to":"p5_work2","kind":"sequence","label":"Accepted"},{"from":"p5_work1","to":"p5_review","kind":"sequence","label":""},{"from":"p5_work2","to":"p5_review","kind":"sequence","label":""},{"from":"p5_review","to":"p5_work1","kind":"feedback","label":"Needs revision"},{"from":"p5_review","to":"p6_work1","kind":"sequence","label":"Accepted"},{"from":"p5_review","to":"p6_work2","kind":"sequence","label":"Accepted"},{"from":"p6_work1","to":"p6_review","kind":"sequence","label":""},{"from":"p6_work2","to":"p6_review","kind":"sequence","label":""},{"from":"p6_review","to":"p6_work1","kind":"feedback","label":"Needs revision"},{"from":"p5_review","to":"exception_action","kind":"sequence","label":"Exception response"},{"from":"exception_action","to":"exception_review","kind":"sequence","label":""},{"from":"exception_review","to":"p4_work1","kind":"feedback","label":"Confirmed re-review"}]}'::jsonb),
('procurement-supply-advanced','6e25a50a88aa4be96cfd0df2f4d37b33','{"nodes":[{"id":"p1_work1","name":"采购需求与预算依据","phase":"需求与规格","kind":"activity","responsibility":"确认业务用途、数量、时间、预算和可替代范围。交付：采购需求与预算依据。"},{"id":"p1_work2","name":"规格与验收标准","phase":"需求与规格","kind":"activity","responsibility":"定义功能、服务、质量与验收证据，避免无法比较的报价口径。交付：规格与验收标准。"},{"id":"p1_review","name":"需求与规格评审","phase":"需求与规格","kind":"decision","responsibility":"核对真实需求、预算与可评估规格并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p2_work1","name":"市场与供应风险","phase":"市场与寻源","kind":"activity","responsibility":"分析供应渠道、交付能力与集中风险，核对替代供应可能性。交付：市场与供应风险分析。"},{"id":"p2_work2","name":"供应商资格与邀约","phase":"市场与寻源","kind":"activity","responsibility":"核对供应商资料、能力与适用审阅，安排询价或招采资料。交付：供应商资格与邀约记录。"},{"id":"p2_review","name":"市场与寻源评审","phase":"市场与寻源","kind":"decision","responsibility":"核对供应市场与候选人可用性并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p3_work1","name":"方案报价与能力评估","phase":"评估与采购决策","kind":"activity","responsibility":"按事先确认的标准评估技术、服务、价格和交付条件。交付：供应方案与比较记录。"},{"id":"p3_work2","name":"样品与商务核对","phase":"评估与采购决策","kind":"activity","responsibility":"核对样品、质量、成本、履约安排及需协商的问题。交付：样品与商务核对。"},{"id":"p3_review","name":"评估与采购决策评审","phase":"评估与采购决策","kind":"decision","responsibility":"核对预设标准、比较与取舍并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p4_work1","name":"采购确认与约定","phase":"采购与履约安排","kind":"activity","responsibility":"有权人确认选择及条件，登记范围、交付、验收和变更安排。交付：采购确认与约定记录。"},{"id":"p4_work2","name":"订单与供应跟踪","phase":"采购与履约安排","kind":"activity","responsibility":"核对订单、版本、生产或备货进度，登记关键节点和责任人。交付：订单与供应进度。"},{"id":"p4_review","name":"采购与履约安排评审","phase":"采购与履约安排","kind":"decision","responsibility":"核对确认决定与可执行履约安排并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p5_work1","name":"到货仓储与数量核对","phase":"到货与联合验收","kind":"activity","responsibility":"核对到货、数量、批次、运输状态和入库安排。交付：到货与仓储核对。"},{"id":"p5_work2","name":"质量与使用验收","phase":"到货与联合验收","kind":"activity","responsibility":"业务与质量人员对照标准核验成果，记录差异及处理依据。交付：联合验收与差异记录。"},{"id":"p5_review","name":"到货与联合验收评审","phase":"到货与联合验收","kind":"decision","responsibility":"核对实物、质量与业务可用性并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p6_work1","name":"订单验收与账单对账","phase":"对账与供应维护","kind":"activity","responsibility":"核对订单、验收和账单，登记付款所需确认及差异处理。交付：对账与差异处置。"},{"id":"p6_work2","name":"供应评估与后续改进","phase":"对账与供应维护","kind":"activity","responsibility":"总结交付、质量、服务和风险变化，提出供应与规格优化。交付：供应商表现与改进。"},{"id":"p6_review","name":"对账与供应维护评审","phase":"对账与供应维护","kind":"decision","responsibility":"核对单据一致性与供应表现并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"exception_action","name":"供应异常与替代安排","phase":"异常处置与恢复","kind":"activity","responsibility":"核对延迟、数量或质量问题，协调供应商、仓储与业务，提出经确认的替代或补供安排。"},{"id":"exception_review","name":"恢复与重新准入","phase":"异常处置与恢复","kind":"decision","responsibility":"核对异常影响、处置证据与恢复状态，明确哪些工作需要重新评审；获得有权人确认后再进入正常推进路径。"}],"edges":[{"from":"p1_work1","to":"p1_review","kind":"sequence","label":""},{"from":"p1_work2","to":"p1_review","kind":"sequence","label":""},{"from":"p1_review","to":"p1_work1","kind":"feedback","label":"未通过：修订"},{"from":"p1_review","to":"p2_work1","kind":"sequence","label":"通过"},{"from":"p1_review","to":"p2_work2","kind":"sequence","label":"通过"},{"from":"p2_work1","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work2","to":"p2_review","kind":"sequence","label":""},{"from":"p2_review","to":"p2_work1","kind":"feedback","label":"未通过：修订"},{"from":"p2_review","to":"p3_work1","kind":"sequence","label":"通过"},{"from":"p2_review","to":"p3_work2","kind":"sequence","label":"通过"},{"from":"p3_work1","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work2","to":"p3_review","kind":"sequence","label":""},{"from":"p3_review","to":"p3_work1","kind":"feedback","label":"未通过：修订"},{"from":"p3_review","to":"p4_work1","kind":"sequence","label":"通过"},{"from":"p4_work1","to":"p4_work2","kind":"sequence","label":""},{"from":"p4_work2","to":"p4_review","kind":"sequence","label":""},{"from":"p4_review","to":"p4_work1","kind":"feedback","label":"未通过：修订"},{"from":"p4_review","to":"p5_work1","kind":"sequence","label":"通过"},{"from":"p4_review","to":"p5_work2","kind":"sequence","label":"通过"},{"from":"p5_work1","to":"p5_review","kind":"sequence","label":""},{"from":"p5_work2","to":"p5_review","kind":"sequence","label":""},{"from":"p5_review","to":"p5_work1","kind":"feedback","label":"未通过：修订"},{"from":"p5_review","to":"p6_work1","kind":"sequence","label":"通过"},{"from":"p5_review","to":"p6_work2","kind":"sequence","label":"通过"},{"from":"p6_work1","to":"p6_review","kind":"sequence","label":""},{"from":"p6_work2","to":"p6_review","kind":"sequence","label":""},{"from":"p6_review","to":"p6_work1","kind":"feedback","label":"未通过：修订"},{"from":"p5_review","to":"exception_action","kind":"sequence","label":"异常：专项处置"},{"from":"exception_action","to":"exception_review","kind":"sequence","label":""},{"from":"exception_review","to":"p3_work1","kind":"feedback","label":"确认后重新评审"}]}'::jsonb),
('procurement-supply-advanced','d1d59197e5653ace91c14617e09ed7d0','{"nodes":[{"id":"p1_work1","name":"Procurement needs and budget","phase":"Requirements and specifications","kind":"activity","responsibility":"Confirm purpose, volumes, timing, budget and acceptable alternatives. Deliver: procurement needs and budget evidence."},{"id":"p1_work2","name":"Specifications and acceptance criteria","phase":"Requirements and specifications","kind":"activity","responsibility":"Define functional, service, quality and acceptance requirements using comparable definitions. Deliver: specifications and acceptance criteria."},{"id":"p1_review","name":"Requirements and specifications review","phase":"Requirements and specifications","kind":"decision","responsibility":"Review needs, budget and evaluable specifications and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p2_work1","name":"Market and supply risks","phase":"Market analysis and sourcing","kind":"activity","responsibility":"Assess channels, delivery capability, concentration risks and possible alternative supply. Deliver: market and supply-risk analysis."},{"id":"p2_work2","name":"Supplier qualification and invitation","phase":"Market analysis and sourcing","kind":"activity","responsibility":"Review supplier information, capability and applicable checks and prepare sourcing materials. Deliver: supplier qualification and invitation."},{"id":"p2_review","name":"Market analysis and sourcing review","phase":"Market analysis and sourcing","kind":"decision","responsibility":"Review supply market and candidate availability and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p3_work1","name":"Proposals, pricing and capability","phase":"Evaluation and procurement decision","kind":"activity","responsibility":"Evaluate technical, service, pricing and delivery terms against agreed criteria. Deliver: supplier proposals and comparison."},{"id":"p3_work2","name":"Samples and commercial checks","phase":"Evaluation and procurement decision","kind":"activity","responsibility":"Verify samples, quality, costs, delivery arrangements and unresolved negotiations. Deliver: sample and commercial checks."},{"id":"p3_review","name":"Evaluation and procurement decision review","phase":"Evaluation and procurement decision","kind":"decision","responsibility":"Review predefined criteria, comparison and tradeoffs and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p4_work1","name":"Confirm procurement and terms","phase":"Procurement and fulfilment planning","kind":"activity","responsibility":"Authorized humans confirm supplier selection and terms, delivery, acceptance and change arrangements. Deliver: procurement confirmation and terms."},{"id":"p4_work2","name":"Orders and supply tracking","phase":"Procurement and fulfilment planning","kind":"activity","responsibility":"Check orders, versions, production or stock progress with milestones and ownership. Deliver: orders and supply progress."},{"id":"p4_review","name":"Procurement and fulfilment planning review","phase":"Procurement and fulfilment planning","kind":"decision","responsibility":"Review confirmed decisions and actionable fulfilment arrangements and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p5_work1","name":"Receiving, storage and quantities","phase":"Receiving and joint acceptance","kind":"activity","responsibility":"Verify arrival, quantities, batches, transport condition and storage arrangements. Deliver: receiving and warehouse checks."},{"id":"p5_work2","name":"Quality and use acceptance","phase":"Receiving and joint acceptance","kind":"activity","responsibility":"Business and quality staff verify results against criteria and record discrepancies and disposition evidence. Deliver: joint acceptance and discrepancies."},{"id":"p5_review","name":"Receiving and joint acceptance review","phase":"Receiving and joint acceptance","kind":"decision","responsibility":"Review received goods, quality and business usability and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p6_work1","name":"Order, receipt and invoice reconciliation","phase":"Reconciliation and supplier maintenance","kind":"activity","responsibility":"Reconcile orders, acceptance and invoices and record required confirmations and discrepancies. Deliver: reconciliation and discrepancy handling."},{"id":"p6_work2","name":"Supplier review and improvement","phase":"Reconciliation and supplier maintenance","kind":"activity","responsibility":"Review delivery, quality, service and risk changes and propose supplier and specification improvements. Deliver: supplier performance and improvements."},{"id":"p6_review","name":"Reconciliation and supplier maintenance review","phase":"Reconciliation and supplier maintenance","kind":"decision","responsibility":"Review document consistency and supplier performance and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"exception_action","name":"Supply exceptions and alternatives","phase":"Exceptions and recovery","kind":"activity","responsibility":"Investigate delays, quantity or quality issues and coordinate approved alternatives or replenishment."},{"id":"exception_review","name":"Recovery and readiness review","phase":"Exceptions and recovery","kind":"decision","responsibility":"Check impact, response evidence and recovery status. Identify reviews to repeat and obtain authorized confirmation before resuming."}],"edges":[{"from":"p1_work1","to":"p1_review","kind":"sequence","label":""},{"from":"p1_work2","to":"p1_review","kind":"sequence","label":""},{"from":"p1_review","to":"p1_work1","kind":"feedback","label":"Needs revision"},{"from":"p1_review","to":"p2_work1","kind":"sequence","label":"Accepted"},{"from":"p1_review","to":"p2_work2","kind":"sequence","label":"Accepted"},{"from":"p2_work1","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work2","to":"p2_review","kind":"sequence","label":""},{"from":"p2_review","to":"p2_work1","kind":"feedback","label":"Needs revision"},{"from":"p2_review","to":"p3_work1","kind":"sequence","label":"Accepted"},{"from":"p2_review","to":"p3_work2","kind":"sequence","label":"Accepted"},{"from":"p3_work1","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work2","to":"p3_review","kind":"sequence","label":""},{"from":"p3_review","to":"p3_work1","kind":"feedback","label":"Needs revision"},{"from":"p3_review","to":"p4_work1","kind":"sequence","label":"Accepted"},{"from":"p4_work1","to":"p4_work2","kind":"sequence","label":""},{"from":"p4_work2","to":"p4_review","kind":"sequence","label":""},{"from":"p4_review","to":"p4_work1","kind":"feedback","label":"Needs revision"},{"from":"p4_review","to":"p5_work1","kind":"sequence","label":"Accepted"},{"from":"p4_review","to":"p5_work2","kind":"sequence","label":"Accepted"},{"from":"p5_work1","to":"p5_review","kind":"sequence","label":""},{"from":"p5_work2","to":"p5_review","kind":"sequence","label":""},{"from":"p5_review","to":"p5_work1","kind":"feedback","label":"Needs revision"},{"from":"p5_review","to":"p6_work1","kind":"sequence","label":"Accepted"},{"from":"p5_review","to":"p6_work2","kind":"sequence","label":"Accepted"},{"from":"p6_work1","to":"p6_review","kind":"sequence","label":""},{"from":"p6_work2","to":"p6_review","kind":"sequence","label":""},{"from":"p6_review","to":"p6_work1","kind":"feedback","label":"Needs revision"},{"from":"p5_review","to":"exception_action","kind":"sequence","label":"Exception response"},{"from":"exception_action","to":"exception_review","kind":"sequence","label":""},{"from":"exception_review","to":"p3_work1","kind":"