('construction-project-advanced','a09d68b1789d47ab037fc0979a575da2','{"nodes":[{"id":"p1_work1","name":"业主目标与项目任务书","phase":"需求与现场","kind":"activity","responsibility":"明确使用目的、范围、预算、交付及接收要求，登记相关利益方。交付：项目任务书与目标。"},{"id":"p1_work2","name":"现场调查与条件盘点","phase":"需求与现场","kind":"activity","responsibility":"核对现场、既有设施、接口和资料，登记需要专业核验的事项。交付：现场与条件记录。"},{"id":"p1_review","name":"需求与现场评审","phase":"需求与现场","kind":"decision","responsibility":"核对目标、场地与项目边界并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p2_work1","name":"概念与空间方案","phase":"方案与成本","kind":"activity","responsibility":"提出空间、功能和主要设计方案，说明与使用目标和场地的关系。交付：概念与方案设计。"},{"id":"p2_work2","name":"成本与实施路径","phase":"方案与成本","kind":"activity","responsibility":"核对估算、采购、排期和实施约束，说明设计与成本取舍。交付：成本与实施计划。"},{"id":"p2_review","name":"方案与成本评审","phase":"方案与成本","kind":"decision","responsibility":"核对方案适用性与预算取舍并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p3_work1","name":"技术设计与专业协调","phase":"技术与准入准备","kind":"activity","responsibility":"整合结构、机电、材料和细节，核对专业接口与图纸版本。交付：协调设计与技术资料。"},{"id":"p3_work2","name":"适用审阅与材料确认","phase":"技术与准入准备","kind":"activity","responsibility":"核对项目适用的审阅、许可、材料与变更确认安排，登记责任人。交付：准入与材料确认记录。"},{"id":"p3_review","name":"技术与准入准备评审","phase":"技术与准入准备","kind":"decision","responsibility":"核对技术一致性与适用确认并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p4_work1","name":"供应与施工资源","phase":"采购与施工准备","kind":"activity","responsibility":"落实材料、设备、施工团队及关键供应节点，核对交付与检查方式。交付：供应与施工资源计划。"},{"id":"p4_work2","name":"施工组织与现场准备","phase":"采购与施工准备","kind":"activity","responsibility":"确认施工顺序、场地接口、作业与现场管理安排。交付：施工准备与组织计划。"},{"id":"p4_review","name":"采购与施工准备评审","phase":"采购与施工准备","kind":"decision","responsibility":"核对供应、场地与施工计划并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p5_work1","name":"施工执行与变更记录","phase":"施工与质量协调","kind":"activity","responsibility":"按确认设计与安排施工，登记进展、现场偏差和需审阅变更。交付：施工进展与变更记录。"},{"id":"p5_work2","name":"质量检查与问题闭合","phase":"施工与质量协调","kind":"activity","responsibility":"核对关键工序、接口、材料和检查记录，跟踪整改与复检。交付：质量证据与整改清单。"},{"id":"p5_review","name":"施工与质量协调评审","phase":"施工与质量协调","kind":"decision","responsibility":"核对实际施工、专业接口与质量证据并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"p6_work1","name":"验收与移交资料","phase":"验收移交与使用","kind":"activity","responsibility":"核对工程成果、未完成项、使用维护资料和接收责任。交付：验收与移交包。"},{"id":"p6_work2","name":"使用观察与缺陷维护","phase":"验收移交与使用","kind":"activity","responsibility":"登记使用反馈、缺陷和维护问题，提出经确认的后续处置。交付：使用与缺陷维护记录。"},{"id":"p6_review","name":"验收移交与使用评审","phase":"验收移交与使用","kind":"decision","responsibility":"核对移交完整性与使用反馈并记录有权人的评审结论。通过后推进；缺项时列明问题与责任人，按退回连线修订。"},{"id":"exception_action","name":"变更、质量与现场纠偏","phase":"异常处置与恢复","kind":"activity","responsibility":"确认设计变更、质量或现场问题及影响，按项目程序暂停受影响工作、提出处置与复核安排。"},{"id":"exception_review","name":"恢复与重新准入","phase":"异常处置与恢复","kind":"decision","responsibility":"核对异常影响、处置证据与恢复状态，明确哪些工作需要重新评审；获得有权人确认后再进入正常推进路径。"}],"edges":[{"from":"p1_work1","to":"p1_review","kind":"sequence","label":""},{"from":"p1_work2","to":"p1_review","kind":"sequence","label":""},{"from":"p1_review","to":"p1_work1","kind":"feedback","label":"未通过：修订"},{"from":"p1_review","to":"p2_work1","kind":"sequence","label":"通过"},{"from":"p1_review","to":"p2_work2","kind":"sequence","label":"通过"},{"from":"p2_work1","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work2","to":"p2_review","kind":"sequence","label":""},{"from":"p2_review","to":"p2_work1","kind":"feedback","label":"未通过：修订"},{"from":"p2_review","to":"p3_work1","kind":"sequence","label":"通过"},{"from":"p2_review","to":"p3_work2","kind":"sequence","label":"通过"},{"from":"p3_work1","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work2","to":"p3_review","kind":"sequence","label":""},{"from":"p3_review","to":"p3_work1","kind":"feedback","label":"未通过：修订"},{"from":"p3_review","to":"p4_work1","kind":"sequence","label":"通过"},{"from":"p3_review","to":"p4_work2","kind":"sequence","label":"通过"},{"from":"p4_work1","to":"p4_review","kind":"sequence","label":""},{"from":"p4_work2","to":"p4_review","kind":"sequence","label":""},{"from":"p4_review","to":"p4_work1","kin