('construction-project-advanced','0b6ff04bb06b122e268f83c7216b41d2','{"nodes":[{"id":"p1_work1","name":"Client goals and project brief","phase":"Brief and site","kind":"activity","responsibility":"Define use, scope, budget, delivery and receipt requirements with stakeholders. Deliver: project brief and goals."},{"id":"p1_work2","name":"Site survey and conditions","phase":"Brief and site","kind":"activity","responsibility":"Survey the site, existing facilities, interfaces and information and flag specialist checks. Deliver: site and condition record."},{"id":"p1_review","name":"Brief and site review","phase":"Brief and site","kind":"decision","responsibility":"Review goals, site and project boundaries and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p2_work1","name":"Concept and spatial design","phase":"Design and cost","kind":"activity","responsibility":"Develop spatial, functional and design proposals against goals and site conditions. Deliver: concept and design proposal."},{"id":"p2_work2","name":"Costs and delivery approach","phase":"Design and cost","kind":"activity","responsibility":"Review estimates, procurement, schedule and delivery constraints with design-cost tradeoffs. Deliver: cost and implementation plan."},{"id":"p2_review","name":"Design and cost review","phase":"Design and cost","kind":"decision","responsibility":"Review design suitability and budget tradeoffs and record the authorized human decision. Advance after acceptance; document issues and owners before returning work."},{"id":"p3_work1","name":"Technical design and coordination","phase":"Technical and readiness preparation","kind":"activity","responsibility":"Coordinate structures, services, materials and details and verify interfaces and drawing versions. Deliver: coordinated designs and technical materials."},{"id":"p3_work2","name":"Applicable reviews and material approval","phase":"Technical and readiness prepa