"sequence","label":"Accepted"},{"from":"p1_review","to":"p2_work2","kind":"sequence","label":"Accepted"},{"from":"p2_work1","to":"p2_review","kind":"sequence","label":""},{"from":"p2_work2","to":"p2_review","kind":"sequence","label":""},{"from":"p2_review","to":"p2_work1","kind":"feedback","label":"Needs revision"},{"from":"p2_review","to":"p3_work1","kind":"sequence","label":"Accepted"},{"from":"p2_review","to":"p3_work2","kind":"sequence","label":"Accepted"},{"from":"p3_work1","to":"p3_review","kind":"sequence","label":""},{"from":"p3_work2","to":"p3_review","kind":"sequence","label":""},{"from":"p3_review","to":"p3_work1","kind":"feedback","label":"Needs revision"},{"from":"p3_review","to":"p4_work1","kind":"sequence","label":"Accepted"},{"from":"p3_review","to":"p4_work2","kind":"sequence","label":"Accepted"},{"from":"p4_work1","to":"p4_review","kind":"sequence","label":""},{"from":"p4_work2","to":"p4_review","kind":"sequence","label":""},{"from":"p4_review","to":"p4_work1","kind":"feedback","label":"Needs revision"},{"from":"p4_review","to":"p5_work1","kind":"sequence","label":"Accepted"},{"from":"p5_work1","to":"p5_work2","kind":"sequence","label":""},{"from":"p5_work2","to":"p5_review","kind":"sequence","label":""},{"from":"p5_review","to":"p5_work1","kind":"feedback","label":"Needs revision"},{"from":"p5_review","to":"p6_work1","kind":"sequence","label":"Accepted"},{"from":"p5_review","to":"p6_work2","kind":"sequence","label":"Accepted"},{"from":"p6_work1","to":"p6_review","kind":"sequence","label":""},{"from":"p6_work2","to":"p6_review","kind":"sequence","label":""},{"from":"p6_review","to":"p6_work1","kind":"feedback","label":"Needs revision"},{"from":"p4_review","to":"exception_action","kind":"sequence","label":"Exception response"},{"from":"exception_action","to":"exception_review","kind":"sequence","label":""},{"from":"exception_review","to":"p2_work1","kind":"feedback","label":"Confirmed re-review"}]}'::jsonb),
